-- ----------------------------
BEGIN;
INSERT INTO `asesmen_lapangan` (`id`, `akreditasi_id`, `kea_id`, `tgl_visitasi_awal`, `tgl_visitasi_akhir`, `jadwal_disetujui`, `tgt_wkt_al`, `lal_submitted`, `hasil_ditetapkan_kea`, `note_penetapan_hasil_al_kea`, `no_surat_tugas_al`, `surat_tugas_al`, `berita_acara_al`, `umpan_balik_asesor`, `created_at`, `updated_at`, `tanggapan_al`, `upps_menanggapi_al`, `asesor_menanggapi_al`, `deadline_tanggapan_al`, `rekomendasi_peringkat_kea`, `catatan_asesor`, `catatan_lain`, `status_akreditasi_oleh_kea`, `surat_pemberitahuan_al`, `no_surat_pemberitahuan_al`, `umpan_balik_asesor_diisi`, `nomor_surat_tugas_al_observer`, `surat_tugas_al_observer`, `catatan_observer`, `catatan_observer_lain`, `umpan_balik_observer`, `umpan_balik_observer_diisi`, `lal_observer_submitted`) VALUES (96, 1, 3, '2022-06-29', '2022-07-02', 1, '2022-07-14', 1, 1, '[1] PS (sudah berumur 29 tahun) memberikan apresiasi untuk LAM Teknik karena laporan AK telah disampaikan PS sebelum AL sebagai bagian bentuk transparansi. Dengan demikian pada saat AL, PS telah menyiapkan apa yang diperlukan melalui link google drive. \r\n[2] Jadwal AL sudah disampaikan sesuai yang diterima dari LAM. Namun terkait DTPS terjadi diskusi, dimana Dosen dengan kompetensi ilmu Hukum dianggap DTPS, demikian juga 3 orang Doktor Teknik Mesin Pertanian (ini bisa disepakati), sedangkan dosen dengan kompetensi ilmu Hukum dan manajemen tidak bisa dinilai sebagai DTPS. PS menilia/menganggap bahwa semua dosen di home base PD-DIKTI adalah DTPS. \r\n[3] Hari kedua suasana sudah cair. Overall semuanya lancar, bukti-bukti disediakan, komunikasi baik, sebagian besar mahasiswanya adalah mahasiswa transfer. Bukti-bukti disajikan dengan lengkap maka nilai AK meningkat ketika saat AL. \r\n[4] Terkait matematika dan basic science, pada saat AK PS menyampaikan gabungan  kurikulum lama dan kurikulum baru, sehingga jadi banyak jumlah sksnya. Sudah diklarifikasi.\r\n[5] Pelaksanaan tata pamong, tata kelola: ini menjadi highlight, mereka pakai azaz efisiensi. Di level UPPS semua terpusat di Dekan, tidak ada Wakil Dekan. Semua bertumpu ke Dekan termasuk laporan mengajar dosen. \r\n[6] Pengukuran dilakukan masih bersifat insidental, sehingga pengukuran secara berkala setiap tahunnya belum ada, RPS sudah dilengkapi rubrik dan porto folio.\r\n[7] Implementasi pelaksanaan penjaminan mutu langsung dari tingkat universitas: UPPS terdiri dari PS Teknik Mesin dan Teknik Sipil. Siklus PPEPP sudah terlihat/terlaksana.\r\n[8] Skor = 279 (Baik)', '40/BATAP APK-PII/128/6/2022', 'surat_tugas_al_AKR911381222.pdf', 'berita_acara_al_AKR911381222.pdf', 'umpan_balik_asesor_AKR911381222.xlsx', '2022-06-10 01:25:36', '2023-07-27 17:55:40', 'tanggapan_al_AKR911381222.xlsx', 1, 1, '2022-07-31', 'Baik', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
COMMIT;

