  CONSTRAINT `asesmen_lapangan_prodi_baru_akreditasi_id_foreign` FOREIGN KEY (`akreditasi_id`) REFERENCES `akreditasi` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `asesmen_lapangan_prodi_baru_validator_id_foreign` FOREIGN KEY (`validator_id`) REFERENCES `validator_prodi_baru` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
