-- ----------------------------
-- Records of asesmen_lapangan_prodi_baru
-- ----------------------------
BEGIN;
INSERT INTO `asesmen_lapangan_prodi_baru` (`id`, `akreditasi_id`, `validator_id`, `tgl_visitasi_awal`, `tgl_visitasi_akhir`, `jadwal_disetujui`, `tgt_wkt_al`, `lal_submitted`, `hasil_ditetapkan_validator`, `note_penetapan_hasil_al_validator`, `no_surat_tugas_al`, `surat_tugas_al`, `berita_acara_al`, `no_surat_pemberitahun_al`, `surat_pemberitahun_al`, `umpan_balik_asesor`, `rekomendasi_peringkat_validator`, `catatan_asesor`, `catatan_lain`, `status_akreditasi_oleh_validator`, `surat_pemberitahuan_al`, `no_surat_pemberitahuan_al`, `umpan_balik_asesor_diisi`, `created_at`, `updated_at`) VALUES (35, 1856, 1, '2025-04-14', '2025-04-16', 1, '2025-04-19', 1, 1, '<p>Telah memenuhi semua syarat operasional program studi baru Sarjana Teknik Kimia&nbsp;</p>', '40/BATAP APK-PII/242/3/2025', 'surat_tugas_al_AKRB94618561121125.pdf', 'berita_acara_al_AKRB94618561121125.pdf', NULL, NULL, 'umpan_balik_asesor_AKRB94618561121125.xlsx', 'Baik', '<p>Hasil asesmen lapangan telah berhasil memverifikasi hasil Asesmen kecukupan. Ada sedikit perubahan penilaian(penurunan) tidak signifikan. Program Studi Teknik Kimia Ubeo telah memenuhi syarat untuk menjalankan kegiatan belajar mengajar. Struktur organisasi UPPS telah disusun dengan baik, meliputi kebijakan, pelaksanaan akademik, pengawasan mutu, dukungan penunjang akademik, dan administrasi. Ketersediaan laboratorium, peralatan praktikum, dan fasilitas pendukung lainnya telah mencukupi sesuai standar (&gt;1.5 m2 per mahasiswa). Tenaga kependidikan yang memenuhi syarat (minimal ijazah D3, usia &lt;56 tahun, bekerja 37,5 jam/minggu) telah tersedia. Sistem penjaminan mutu internal diterapkan dengan baik melalui GPM dan GKM. Rekomendasi meliputi perbaikan kelengkapan laboratorium dan modul praktikum, peningkatan kompetensi tenaga kependidikan, dan optimalisasi digital</p>', '<p>Prodi siap menjalanakan tahn-tahun awal perkuliahan dengan SDM dan Sarpras.&nbsp;</p>', 'normal', 'surat_pemberitahuan_al_AKRB94618561121125.pdf', '10/BATAP APK-PII/220/3/2025', 1, '2025-03-18 19:00:57', '2025-04-19 11:55:09');
COMMIT;

