INSERT INTO `laporan_ak_prodi_baru` (`id`, `ak_id`, `asesor_id`, `link_file`, `syarat_perlu_terakreditasi_terpenuhi`, `skor_asesmen`, `komentar_umum`, `syarat_ketentuan_disetujui`, `wkt_syarat_ketentuan_disetujui`, `created_at`, `updated_at`) VALUES (82, 35, 189, 'laporan_ak_35_189_1742530169_Laporan_AK_Prodi_Baru_Sarjana isi.xlsx', 1, 339, 'Program Studi Teknik Kimia Universitas Borneo telah memenuhi syarat untuk menjalankan kegiatan belajar mengajar. Struktur organisasi UPPS telah disusun dengan baik, meliputi kebijakan, pelaksanaan akademik, pengawasan mutu, dukungan penunjang akademik, dan administrasi. Ketersediaan laboratorium, peralatan praktikum, dan fasilitas pendukung lainnya telah mencukupi sesuai standar (>1.5 m2 per mahasiswa). Tenaga kependidikan yang memenuhi syarat (minimal ijazah D3, usia <56 tahun, bekerja 37,5 jam/minggu) telah tersedia. Sistem penjaminan mutu internal diterapkan dengan baik melalui GPM dan GKM. Rekomendasi meliputi perbaikan peralatan laboratorium, peningkatan kompetensi tenaga kependidikan, dan optimalisasi digital', 1, '2025-03-21 11:09:29', '2025-03-21 11:01:58', '2025-03-21 11:09:29'), (84, 35, 122, 'laporan_ak_35_122_1743163390_Laporan_AK_Prodi_Baru_PSTK_IPB_2025.xlsx', 1, 341, '1.	Pendirian PSTK Ubeo telah mendapatkan persetujuan dari Senat Akademik dan rekomendasi Majelis Wali Amanat dan telah melakukan penelurusan sebagai pembanding ke berbagai Prodi S1 Teknik Kimia yang ada. \r\n2.	UPPS perlu mengupayakan rekruitmen segera dosen dengan kompetensi  bidang Bioproses/Bioteknologi yang sesuai dengan rencana pengembangan PSTK. \r\n3.	Implementasi Penjaminan Mutu di UPPS dan rencana di Prodi disiapkan secara detail termasuk unsur-unsurnya. \r\n4.	Kesiapan sarana prasarana perkuliahan sudah tersedia di UPPS dengan berbagai praktikum dasar tergabung di UPPS dan perlu  disiapkan secara detail terkait rencana Laboratoium Proses dan Laboratorium Unit Operasi dengan modul-modul praktikum apa saja yang menjadi penciri dan pemenuhan kompetensi Teknik Kimia.', 1, '2025-03-28 19:03:10', '2025-03-28 19:03:10', '2025-03-28 19:03:10');
COMMIT;

