  INDEX `rincian_butir_penilaian_ak_kriteria_id_foreign`(`kriteria_id` ASC) USING BTREE,
  CONSTRAINT `rincian_butir_penilaian_ak_kriteria_id_foreign` FOREIGN KEY (`kriteria_id`) REFERENCES `kriteria_butir_penilaian` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
