-- ----------------------------
-- Records of rincian_butir_penilaian_ak
-- ----------------------------
BEGIN;
INSERT INTO `rincian_butir_penilaian_ak` (`id`, `laporan_ak_id`, `nomor_butir`, `skor_butir`, `bobot_butir`, `skor_akhir_butir`, `created_at`, `updated_at`, `deskripsi_butir`, `kriteria_id`) VALUES (22941, 179, 1, 2.00, 1.00, 2.00, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Unit Pengelola Program Studi (UPPS) mampu:\n1) mengidentifikasi kondisi lingkungan dan industri yang relevan, dan\n2) menetapkan posisi relatif program studi terhadap lingkungannya.', NULL), (22942, 179, 2, 3.00, 1.00, 3.00, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Profil UPPS:\n1) kurang menunjukkan keserbacakupan informasi yang jelas dengan data dan informasi yang disampaikan pada masing-masing kriteria,\n2) kurang menggambarkan keselarasan dengan substansi keilmuan program studi. ', NULL), (22943, 179, 3, 3.00, 0.47, 1.41, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'UPPS memiliki: \n1) visi yang mencerminkan visi perguruan tinggi dan memayungi visi keilmuan terkait program studi,\n2) misi, tujuan, dan strategi yang searah dengan misi, tujuan, dan strategi perguruan tinggi serta mendukung pengembangan program studi.', 1), (22944, 179, 4, 3.00, 0.47, 1.41, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Ada mekanisme dalam penyusunan dan penetapan visi, misi, tujuan dan strategi yang terdokumentasi serta ada keterlibatan pemangku kepentingan internal (dosen, mahasiswa dan tenaga kependidikan) dan pemangku kepentingan eksternal (lulusan dan pengguna lulusan).', 1), (22945, 179, 5, 3.00, 0.47, 1.41, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Dipahami dengan baik oleh sebagian  sivitas akademika dan tenaga kependidikan.', 1), (22946, 179, 6, 2.00, 1.42, 2.84, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Strategi untuk mencapai tujuan dan disusun berdasarkan analisis yang sistematis dengan menggunakan metoda yang relevan serta terdokumentasi namun belum terbukti efektifitasnya.', 1), (22947, 179, 7, 2.67, 0.66, 1.76, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'UPPS memiliki dokumen formal struktur organisasi dan tata kerja yang dilengkapi tugas dan fungsinya, serta telah berjalan secara konsisten dan menjamin tata pamong yang baik.', 2), (22948, 179, 8, 2.33, 0.66, 1.54, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Terdapat bukti/pengakuan yang sahih bahwa pimpinan UPPS memiliki 2 karakter diantara kepemimpinan operasional, organisasi, dan publik\n', 2), (22949, 179, 9, 3.00, 1.32, 3.96, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'UPPS memiliki bukti yang sahih terkait kerjasama yang ada telah memenuhi aspek 1 dan 2', 2), (22950, 179, 10, 3.85, 0.66, 2.54, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Data berdasarkan Tabel 1-1 dan 3.a.1, tetapi jumlah NDTPS berdasarkan penilaian kesesuaian dengan bidang keahlian program studi yang diakreditasi hanya 8. Akan diverifikasi saat AL', 2), (22951, 179, 11, 3.00, 1.32, 3.96, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'UPPS menetapkan indikator kinerja tambahan berdasarkan standar pendidikan tinggi yang ditetapkan perguruan tinggi. Indikator kinerja tambahan mencakup sebagian kriteria serta menunjukkan daya saing UPPS dan program studi di tingkat nasional. Data indikator kinerja tambahan telah diukur, dimonitor,dikaji, dan dianalisis untuk perbaikan berkelanjutan.', 2), (22952, 179, 12, 2.00, 1.99, 3.98, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Analisis pencapaian kinerja UPPS di tiap kriteria memenuhi 2 aspek dan dilaksanakan setiap tahun.', 2), (22953, 179, 13, 0.80, 3.31, 2.65, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Berdasarkan data pada Tabel 2a1 di LKPS , jumlah pendaftar dan yang lolos seleksi jumlahnya sama yaitu 89 mahasiswa', 3), (22954, 179, 14, 1.33, 2.21, 2.95, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'UPPS melakukan upaya untuk meningkatkan animo calon mahasiswa dalam 3 tahun terakhir namun trennya menurun.', 3), (22955, 179, 15, 1.67, 1.10, 1.83, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Jenis layanan mencakup bidang penalaran, minat dan bakat mahasiswa. Layanan bidang beasiswa, kewirausahaan dan kesehatan tidak terdapat dalam borang LED.', 3), (22956, 179, 16, 2.86, 0.47, 1.34, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Tidak ada data dosen tidak tetap yang dicantumkan dalam tabel LKPS.', 4), (22957, 179, 17, 2.50, 0.76, 1.90, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Jumlah DTPS yang berpendidikan Doktor sebetulnya ada lebih dari 1 orang, tetapi yang lainnya bidang keahliannya tidak sesuai dengan kompotensi inti program studi yang diakreditasi.', 4), (22958, 179, 18, 3.43, 0.38, 1.30, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Ada 7 DTPS yang berkualifikasi Lektor , tetapi hanya 3 orang yang bidang kompetensinya sesuai dengan kompetensi inti program studi hanya 3 orang.', 4), (22959, 179, 19, 1.87, 0.38, 0.71, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Jumlah mahasiswa aktif pada TS sebanyak 81 orang, tetapi mahasiswa transfer yang jumlahnya cukup banyak perlu dikalrifikasi. Akan diverifikasi saat AL.', 4), (22960, 179, 20, 4.00, 0.66, 2.64, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Rasio mahasiswa bimbingan didapat dengan menjumlahkan semua rata rata dosen pembimbing. Perlu dikonfirmasi', 4), (22961, 179, 21, 1.27, 0.19, 0.24, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'EWMP DTPS didapat dari Tabel3a3 LKPS.', 4), (22962, 179, 22, 4.00, 0.38, 1.52, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Dalam Tabel 3a1 tidak ada dosen tidak tetap yang ditugaskan sebagai pengampu. Perlu konfirmasi', 4), (22963, 179, 23, 4.00, 0.66, 2.64, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Bersarkan data di Tabel 3b1 ada 18 rekognisi untuk 8 NDTPS.', 4), (22964, 179, 24, 2.40, 0.66, 1.58, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Jumlah penelitian 8 DTPS dalam 3 tahun terakhir adalah sbb: Biaya luar negeri NI=0, biaya dalam negeri NN=2, dan biaya PT/Mandiri NL=66.\nData LKPS berbeda dengan LED (biaya dalam negeri = 1), perlu konfirmasi.', 4), (22965, 179, 25, 2.40, 0.38, 0.91, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Data diambil berdasarkan Tabel 3b3.', 4), (22966, 179, 26, 4.00, 0.66, 2.64, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Data diambil dari ringkasan di Tabel 3b4.', 4), (22967, 179, 27, 4.00, 0.66, 2.64, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Data ringkasan artikel yang disitasi hanya 11, sementara di Tabel 3b6 ada satu artikel yang disitasi sampai 22 kali. Perlu konfirmasi.', 4), (22968, 179, 28, 4.00, 0.66, 2.64, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Data diambil sesuai dengan yang tertera di Tabel 3b8.', 4), (22969, 179, 29, 2.50, 1.70, 4.25, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Rencana strategis mencantumkan tentang pengembangan dosen dengan menetapkan syarat pendidikan S3 dan kepangkatan, tetapi dalam implementasinya belum terlihat jelas skemanya. Perlu konfirmasi.', 4), (22970, 179, 30, 3.00, 0.85, 2.55, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Berdasarkan data background pendidikan dari tendik sesuai dengan yang diperlukan oleh UPPS.', 4), (22971, 179, 31, 2.79, 0.83, 2.31, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Rata-rata biaya operasional pendidikan dalam 3 tahun BOP= Rp.1128682600 , sedangkan jumlah mhs pada TS=81, sehigga DOP=13.93 juta.', 5), (22972, 179, 32, 4.00, 0.83, 3.32, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Rata-rata jumlah dana penelitian yg diperoleh 8 DTPS dlm 3 tahun terakhir DP= Rp.133,3 juta, sehingga rata-rata dana penelitian DTPS per tahun= Rp. 16,67 juta. Perlu konfirmasi.', 5), (22973, 179, 33, 4.00, 0.41, 1.64, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Rata-rata jumlah dana PkM yg diperoleh 8 DTPS dlm 3 tahun terakhir DPkM= Rp. 66 juta, sehingga rata-rata dana PkM DTPS per tahun= Rp. 8,3 juta.', 5), (22974, 179, 34, 2.00, 0.41, 0.82, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Penggunaan dana untuk investasi pada PS rata-rata selama 3 tahun terakhir adalah Rp. 69 juta. Lab yang tersedia ada 4 lab. Belum ada informasi target investasi yang direncanakan. ', 5), (22975, 179, 35, 3.00, 0.83, 2.49, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'pelaporan secara tertulis. Usulan kebutuhan anggaran dari unversitas, fakultas atau lembaga secara tertulis sesuai dengan program kerja. Pengadaan sumber dana dilakukan oleh Yayasan atas usul dari rektor. Pimpinan Univ diperkenankan mencari dan menerima sumbangan dari pihak lain dengan persetujuan Yayasan, yang dikelola dan ditetapkan dalam rapat kerja kemudian dialokasikan kepada Program Studi Teknik Mesin sesuai mekanisme yang diatur oleh surat keputusan Yayasan. Dengan rata-rata BOP 22 juta, mencukupi untuk mendukung proses pembelajaran.', 5), (22976, 179, 36, 3.00, 3.31, 9.93, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Sarana penunjang pendidikan program studi Sarjana Teknik Mesin terdiri atas 4 laboratorium, yaitu Lab Manufaktur, Lab Tugas Elemen, Lab Prestasi Mesin dan Lab Komputer. Juga terdapat ruang baca, ruang kelas, ruang lab bahasa Inggris, ruang Ka. Lab.', 5), (22977, 179, 37, 2.20, 2.25, 4.95, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'A) Kurikulum program studi dilakukan pemutakhiran setiap 5 tahun sekali, yang dilakukan oleh tim pengembang kurikulum program studi dan Fak dengan mengundang dosen, stakeholder untuk informasi perkembangan IPTEK, dan direview pakar.\nBelum ada informasi pemutakhiran terakhir yang dilakukan.\nPerlu dikonfirmasi pakar yang dilibatkan.\nB) Kurikulum program studi Sarjana Teknik Mesin disusun dengan mengacu pada profil lulusan yang ditetapkan berdasarkan KKNI Level 6 dan SN-Dikti.\nBelum ada informasi keberkalaan pemutakhiran CPL. Perlu dikonfirmasi.\nC) Pada Tabel 5a-1,  semua MK pada struktur kurikulum memuat CPL, namun belum ada informasi peta kurikulum yang menunjukkan pemenuhan dan keterkaitan CPL dengan CPMK.', 6), (22978, 179, 38, 1.50, 0.45, 0.68, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Tidak ada informasi pemenuhan pemenuhan karakteristik proses pembelajaran, yang terdiri atas sifat: 1) interaktif, 2) holistik, 3) integratif, 4) saintifik, 5) kontekstual, 6) tematik, 7) efektif, 8) kolaboratif, dan 9) berpusat pada mahasiswa.', 6), (22979, 179, 39, 1.17, 1.62, 1.89, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'A). Pada LED hal 93 dan Tabel 5a-1 LKPS disebutkan bahwa seluruh MK dilengkapi dengan silabus dan RPS yang selalu dimutakhirkan. Namun tidak ada informasi kelengkapan RPS mencakup target capaian pembelajaran, bahan kajian, metode pembelajaran, waktu dan tahapan, asesmen hasil capaian pembelajaran.\nB) Belum ada informasi isi materi pembelajaran sesuai dengan RPS, dan memiliki kedalaman dan keluasan yang relevan untuk mencapai capaian pembelajaran lulusan.\nPerlu konfirmasi.', 6), (22980, 179, 40, 1.61, 0.90, 1.45, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'A) Interaksi dosen dengan mahasiswa dalam perkuliahan, bimbingan akademik/konseling, bimbingan tugas perancangan, bimbingan kerja praktek dan bimbingan skripsi/TA. Selain itu ada interaksi dosen melibatkan mahasiswa untuk membantu dalam praktikum maupun penelitian. \nB) Monitoring dan evaluasi (monev) proses belajar mengajar pada PS dilakukan sesuai dengan Peraturan Akademik Universitas  serta RPS. \nBelum disebutkan dokumen yang mendukung kegiatan. Perlu konfirmasi.\nC) Proses pembelajaran yang terkait dengan penelitian dijalankan dengan pelaksanaan penelitian oleh dosen dan mahsiswa. \nPerlu konfirmasi dokumen yang mendukung proses pembelajaran. \nD) Belum ada informasi Integrasi pembelajaran dengan PkM.\nE) Belum ada informasi kesesuaian metode pembelajaran dengan capaian pembelajaran.', 6), (22981, 179, 41, 2.50, 0.54, 1.35, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Jumlah sks pembelajaran praktikum, praktik studio, praktik bengkel, atau praktek lapangan (termasuk KKN) = 25 sedangkan jumlah sks pembelajaran total selama masa pendidikan= 144. \nData diisi dalam sks, perlu dikonfirmasi jumlah total jam belajar perkuliahan dan jam praktikum/praktek', 6), (22982, 179, 42, 2.00, 2.25, 4.50, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Pelaksanaan monitoring yang dilakukan dengan cara mengumpulkan data untuk melihat penyimpangan dan kesenjangan dalam melakukan proses pembelajaran, meminta penjelasan, membandingkan, menelaah dokumen untuk menilai tingkat relevansi materi yang disampaikan pada saat proses pembelajaran (tatap muka) dengan RPS. UPPS dan program studi teknik mesin melakukan pemantauan, serta melaporkan hasil program pembelajaran secara periodik.\nBelum ada informasi dokumentasi terkait dan tindak lanjut.', 6), (22983, 179, 43, 0.40, 1.62, 0.65, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'A) Pada LED hal 91 disebutkan bahwa prinsip penilaian dilakukan secara edukatif, otentik, objektif, akuntable,dan transparan yang dilakukan secara terintegrasi. Namun belum ada informasi bukti shahih terpenuhinya 5 prinsip penilaian pembelajaran edukatif, otentik, objektif, akuntabel, dan transparan yang dilakukan secara terintegrasi untuk mengukur ketercapaian capaian pembelajaran lulusan. Belum ada informasi rubrik/portofolio penilaian. \nB) Belum ada informasi pelaksanaan penilaian dimuat dalam dokumen pedoman akademik universitas tentang teknik dan instrumen penilaian.\nC) Belum ada informasi pelaksanaan penilaian mencakup 7 unsur.', 6), (22984, 179, 44, 2.00, 0.72, 1.44, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Pada Tabel 5a.3 LKPS, jumlah sks MK basic science dan matematika adalah 17 sks mencakup kimia dasar, fisika dasar, kalkulus, fisika II, matematika teknik 1, matematika teknik 2. \nPerlu konfirmasi struktur kurikulum yang digunakan pada TS, kurikulum baru atau lama.', 6), (22985, 179, 45, 1.00, 0.72, 0.72, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Pada Tabel 5a.4 LKPS, MK casptone design adalah Menggambar Teknik, Pemrograman Komputer, Menggambar Mesin, Tugas Elemen Mesin dan Tugas Akhir. Semua MK tersebut memiliki CPL sesuai Tabel 5a.1.\nTidak ada informasi panduan pelaskanaan, penggunaan standar keteknikan dan batasan realistis dan bukti shahih pelaksanaan.', 6), (22986, 179, 46, 2.00, 0.36, 0.72, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Pada LKPS, terdapat 13 sks perkuliahan untuk belajar di luar PS dan 2 kegiatan MBKM dengan jenis kegiatan penelitian dengan Jumlah mahasiswa yang terlibat = 2orang.', 6), (22987, 179, 47, 4.00, 1.62, 6.48, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Pada LKPS, terdapat 40 MK yang dikembangkan berdasarkan hasil penelitian dan/atau PkM DTPS dalam 3 tahun terakhir. \nPerlu konfirmasi data.', 6), (22988, 179, 48, 2.00, 2.25, 4.50, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Kegiatan-kegiatan yang sudah dijalankan oleh PSTM untuk mendukung suasana akademik adalah pelatihan bidang ketenikmesinan (SAP dan AUTOCAD), pengenalan kehidupan kampus yang diadakan pada waktu mahasiswa baru masuk, seminar dan lokakarya dosen bekerja sama dengan Universitas, temu dosen, mahasiswa dan alumni pada saat yudisium. \nBelum ada informasi jadwal dan keberkalaan kegiatan. Perlu konfirmasi bukti.', 6), (22989, 179, 49, 1.33, 2.70, 3.60, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'A) Ada 5 aspek yang diukur, yaitu: keandalan, daya tanggap, kepastian, empati dan tangible. Berikut adalah tingkat kepuasan masing-masing aspek, yaitu: untuk keandalan dengan tingkat kepuasan sangat baik= 27.8%, baik = 72.2%, cukup = 0 dan kurang = 0. Untuk daya tanggap, tingkat kepuasan sangat baik = 52.8%, baik = 47.2%, cukup = 0, dan kurang = 0. Untuk kepastian, tingkat kepuasan dgn sangat baik = 31.9%, baik = 68.1%, cukup = 0, dan kurang = 0, untuk aspek empati, tingkat kepuasan sangat baik = 31.8%, baik = 68.1%, cukup = 0, dan kurang= 0, sedangkan untuk tangible dengan tingkat kepuasan sangat baik = 30.6%, baik = 69.4%, cukup = 0 dan kurang = 0. \nB) Tidak ada informasi dilakukannya evaluasi terhadap kepuasan terhadap proses pembelajaran. Tidak ada penjelasan rencana perbaikan dan pengembangan pendidikan.', 6), (22990, 179, 50, 2.00, 0.94, 1.88, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Relevansi penelitian pada UPPS mencakup : \n1) ada informasi kebijakan arah dan peta jalan penyelenggaraan penelitian berpedoman pada rencana induk penelitian Universitas sesuai Statuta Univ.\n2) ada informasi kebijakan bahwa dalam pelaksanaan penelitian berdasarkan pedoman penelitian dan dapat melibatkan dosen dan/ tendik. Terdapat 21 penelitian dosen yang melibatkan mahasiswa selama 3 tahun terakhir.\n3) UPPS memiliki manual standar evaluasi dan pengendalian hasil penelitian, namun tidak ada informasi melakukan evaluasi kesesuaian penelitian dosen dan mahasiswa dengan peta jalan. \n4) Tidak ada informasi menggunakan hasil evaluasi untuk perbaikan relevansi penelitian dan pengembangan keilmuan program studi.', 7), (22991, 179, 51, 4.00, 1.89, 7.56, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Pada LKPS, terdapat 21 penellitan dosen yang melibatkan mahasiswa, dari total 68 penelitian dosen selama 3 tahun terakhir.\nPerlu konfirmasi bukti keterlibatan.', 7), (22992, 179, 52, 2.00, 0.63, 1.26, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Relevansi PkM pada UPPS mencakup : \n1) ada informasi kebijakan yang tercantum di Statuta Univ bahwa Arah dan peta jalan penyelanggaran pengabdian kepada masyarakat berpedoman pada rencana induk pengabdian universitas.\n2) ada informasi kebijakan bahwa dalam melaksanakan PkM sesuai dengan agenda dosen yang merujuk kepada peta jalan penelitian, dapat melibatkan mahasiswa dan/ tendik.\n3) Tidak ada informasi melakukan evaluasi kesesuaian PkM dosen dan mahasiswa dengan peta jalan, dan \n4) Tidak ada informasi menggunakan hasil evaluasi untuk perbaikan relevansi penelitian dan pengembangan keilmuan program studi.', 8), (22993, 179, 53, 2.51, 1.26, 3.16, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Pada LKPS, terdapat 3 PkM dosen yang melibatkan mahasiswa, dari total 68 penelitian dosen selama 3 tahun terakhir.\nPerlu konfirmasi bukti keterlibatan.', 8), (22994, 179, 54, 0.00, 2.09, 0.00, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Tidak ada informasi dilakukan analisis pemenuhan capaian pembelajaran lulusan yang memenuhi 3 aspek.', 9), (22995, 179, 55, 3.67, 2.09, 7.67, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Data jumlah lulusan adalah sbb: pd TS-2= 6, pd TS-1= 10, dan pad TS= 10, sedangkan IPK rata-rata adalah sbb: pada TS-2=3.09, pd TS-1=3.01, dan pd TS= 3,07, sehingga rata-rata IPK lulusan dalam 3 tahun terakhir adalah=3,05. ', 9), (22996, 179, 56, 3.75, 3.22, 12.08, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Disebutkan terdapat jumlah prestasi mhs di bidang akdemik dlm 3 th terakhir sbb: NI=internasional =0, NN=nasional= 2, dan prestasi lokal/wilayah NW=2, jumlah mhs NM=51. Perlu konfirmasi saat AL', 9), (22997, 179, 57, 3.75, 0.64, 2.40, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Disebutkan terdapat jumlah prestasi mhs di bidang non-akdemik dlm 3 th terakhir sbb: NI=internasional =0, NN=nasional= 9, dan prestasi lokal/wilayah NW=1, jumlah mhs NM=51. Akan diverfikasi saat AL', 9), (22998, 179, 58, 3.04, 2.09, 6.35, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Dari jumlah mahasiswa TS-6 = 10 orang, rata-rata masa studi = 5.10 tahun', 9), (22999, 179, 59, 0.00, 2.09, 0.00, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Jumlah mahasiswa yang diterima pada TS-3 sebanyak 8 orang, belum ada yang lulus pada TS.', 9), (23000, 179, 60, 4.00, 2.09, 8.36, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Dari jumlah mahasiswa yang diterima pada TS-6 sebanyak 10 orang, selurunya telah lulus pada akhir TS.', 9), (23001, 179, 61, 1.00, 3.22, 3.22, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Disebutkan pelaksanaan tracer study dilakukan oleh Fakultas Teknik pada anggl 06 Ags 2021- 09 Oktober 2021 (LED hal 8).  Pelaksanaan telah dilakukan terhadap 230 lulusan. \nTidak ada informasi : dokumentasi dan keberkalaan tracer study; isi kuesioner, target populasi dan sosialisasi hasil tracer study.', 9), (23002, 179, 62, 4.00, 3.22, 12.88, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Dari tabel 8.d.1 LKPS, jumlah lulusan: pada TS-4=12, pd TS-3 = 19, dan pd TS-2=6, selurunya terlacak (100%). Data waktu tunggu lulusannya: (WT) < 6 bulan, dengan tahun lulus pada: TS-4=11, TS-3=17 dan TS-2=5. (WT) 6 bulan ≤ WT ≤ 6 bulan, dengan tahun lulus pada: TS-4=1, TS-3=2 dan TS-2=1. Sedangkan WT > 6 bulan, dengan tahun lulus pada: TS-4=0, TS-3=0 dan TS-2=0. Dari data tersebut, maka rata-rata waktu tunggu lulusan (WT) = 1.8 bulan. ', 9), (23003, 179, 63, 4.00, 2.09, 8.36, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Dari tabel 8.d.2 LKPS, jumlah lulusan: pada TS-4=12, pd TS-3 = 19, dan pd TS-2=6, selurunya terlacak (100%).. Jumlah lulusan dengan kesesuaian: bidang kerja rendah: pada TS-4=0; TS-3=0, dan pd TS-2=0, bidang kerja sedang: pada TS-4=1; TS-3=2 dan pada TS-2=3, dan bidang kerja tinggi: pada TS-4=11; TS-3=17 dan pada TS-2=3, sehingga PBS = Kesesuaian bidang kerja lulusan saat mendapatkan pekerjaan pertama = 91.9%', 9), (23004, 179, 64, 3.75, 2.09, 7.84, '2022-06-13 19:29:49', '2022-06-13 19:29:49', 'Dari tabel 8.e.1 LKPS, jumlah lulusan: pada TS-4=12, pd TS-3 = 19, dan pd TS-2=6, selurunya terlacak (100%). Tingkat dan ukuran tempat kerja lulusan, adalah sbb: Tidak ada lulusan bekerja pada tingkat multi nasional/internasional, lulusan bekerja pada lokal/wilayah/berwirausaha berijin pada TS-4=5, TS-3=8, TS-2=5, lulusan bekerja pada lokal/wilayah/berwirausaha tidak berijin pada TS-4=7, TS-3=11, TS-2=1.', 9), (23005, 179, 65, 3.81, 4.02, 15.33, '2022-06-13 19:29:50', '2022-06-13 19:29:50', 'Dari tabel 8.e.2 LKPS, jumlah lulusan: pada TS-4=12, pd TS-3 = 19, dan pd TS-2=6, selurunya terlacak (100%). Tingkat kepuasan pengguna dalam 7 aspek adalah sbb: 1) Aspek Etika: sangat baik=SB= 80%, baik=B= 20%, cukup=C=0 dan kurang K=0. 2) Aspek Keahlian: SB= 90%, B=10%, C=0, dan K=0. 3) Aspek Kemampuan berbahasa asing: SB=0,9, B=0,1, C=0, dan K= 0. 4) Aspek Penggunaan teknologi informasi: SB=60%, B=40%, C=0, dan K=0. 5) Aspek kemampuan Berkomunikasi: SB=70%, B=30%, C=0, dan K=0. 6) Aspek kerjasama tim: SB=90%, B=10%, C=0, dan K=0. 7) Aspek Pengembangan diri: SB= 90%, B=10%, C=0, dan K=0. ', 9), (23006, 179, 66, 0.81, 2.57, 2.08, '2022-06-13 19:29:50', '2022-06-13 19:29:50', 'Publikasi ilmiah dari mahasiswa yang dihasilkan secara mandiri atau bersama DTPS dengan judul relevan dengan bidang PS dalam 3 tahun terakhir adalah sbb: NA1=publikasi di jurnal nasional tidak terakreditasi = 5, seminar nasional = 6. Sedangkan publikasi lainnya tidak ada.', 9), (23007, 179, 67, 4.00, 0.64, 2.56, '2022-06-13 19:29:50', '2022-06-13 19:29:50', 'Terdapat luaran penelitian/PkM yang dihasilkan mahasiswa secara mandiri atau bersama dosen, dengan perincian sbb : luaran penelitian/PkM yang mendapat pengakuan HKI (Paten, Paten Sederhana) = 6; luaran penelitian/PkM yang diterbitkan dalam bentuk Buku ber-ISBN, Book Chapter=2. Luaran lainnya tidak ada.\nPerlu konfirmasi luaran dalam bentuk paten/paten sederhana dalam bentuk skripsi (5 skripsi)', 9), (23008, 179, 68, 2.00, 1.00, 2.00, '2022-06-13 19:29:50', '2022-06-13 19:29:50', 'Keterlaksanaan sistem penjaminan mutu internal :\n1) Ada informasi struktur organisasi sesuai Statuta yang terdiri dari LPM di tingkat Univ, Kabid SPMI, Kabid SPME dan UPM Fakultas. \nDokumen pembentuk tercantum dalam SK Ketua UPPS mengenao penempatan pegawai tetap LPM dan Keputusan Badan Penyelenggaran.\n2) Belum ada informsai dokumen legal auditor bersifat independen.\n3) Pelaksanaan audit mutu internal pada tahun 2019/2020, dengan hasil mencapai standar dikti. Pelaksanaan AMI 2020/2021 memperoleh hasil Melampaui Standar Dikti.\nPerlu konfirmasi dokumen Laporan AMI.\n4) Belum ada informasi dokumen RTM.', 10), (23009, 179, 69, 3.00, 1.00, 3.00, '2022-06-13 19:29:50', '2022-06-13 19:29:50', 'UPPS memiliki dokumen kebijakan SPMI, dokumen manual SPMI, dokumen standar dalam SPMI dan dokumen formulir yang digunakan SPMI yang  lengkap dan dikembangkan secara berkelanjutan serta memiliki pengakuan mutu nasional.', 10), (23010, 179, 70, 2.00, 2.00, 4.00, '2022-06-13 19:29:50', '2022-06-13 19:29:50', 'Keterlaksanan SPMI memenuhi aspek :\n1) tersedianya SN DIKTI  untuk seluruh standar pada SN DIKTI (24 standar pendidikan) mencakup IKU dan IKT pada kriteria tata pamong, mahasiswa, SDM, keuangan sapras, pendidikan, penelitian, PkM dan Luaran & capaian tridarma PT.\n2) Terlaksananya siklus penjaminan mutu (siklus PPEPP) , didkung kegiatan audit mutu internal dengan tanggal audt 9/12/2021. \nPerlu konfirmasi dokumen bukti terlaksannya siklus PPEPP.\n3) Bukti shahih efektivitas pelaksanaan penjaminan mutu, antara lain implementasi sistem penjaminan mutu pada standar kemahasiswaan dengan bikti dokumen standar non akademik, berita acara rapat kerja dengan peningkatan standar kemahasiswaan.\n4) Belum tersedia informasi peningkatan standar.', 10), (23011, 179, 71, 1.50, 1.00, 1.50, '2022-06-13 19:29:50', '2022-06-13 19:29:50', 'Pada LED hal 150, ada informasi UPPS melakukan survey kepuasan pengguna terhadap layanan manajemen terhadap para pemangku kepentingan, layanan pengelolaan dan pengembangan SDM, layanan pengelolaan keuangan dan fasilitas, layanan dan pelaksanaan proses pendidikan, layanan dan pelaksanaan proses penelitian, layanan dan pelaksanaan PkM dan Kepuasan pengguna lulusan dan mitra kerja terhadap kinerja lulusan dengan metode kuisioner secara langsung pada saat akhir semester. \nBelum ada informasi hasil pengukuran kepuasan, tindak lanjut, review hasil pengukuran dan publikasinya.', 10), (23012, 179, 72, 1.50, 2.00, 3.00, '2022-06-13 19:29:50', '2022-06-13 19:29:50', '1) UPPS melakukan analisis SWOT dengan mengidentifikasi kekuatan, kelemahan dan ancaman.\nBelum ada identifikasi peluang.\n2) Belum ada informasi analisis yang dilakukan terkait dengan hasil analisis capaian kinerja.\n3) Tersedia rumusan strategi pengembangan (12 strategi), namun perlu didukung data dan penetepan tahap sesuai prioritas pengembangan.\n4) UPPS telah merumuskan program pengembangan berkelanjutan, mencakup program peningkatan pengetahuan VMTS, peningkatan kualitas pembelajaran, peningkatan mutu lulusan, peningkatan kerjasama dan promosi, peningkatan penelitian dan PkM.', 11), (23013, 179, 73, 2.00, 1.50, 3.00, '2022-06-13 19:29:50', '2022-06-13 19:29:50', 'UPPS menetapkan tujuan strategis pengembangan berdasarkan hasil analisis SWOT yang mempertimbangkan: \n1) rencana aksi pimpinan dan kemampuan sumber daya UPPS,\n2) kebutuhan jangka pendek dan jangka menengah UPPS,\n3) tujuan dan rencana strategis UPPS  yang berlaku,', 11), (23014, 179, 74, 2.00, 2.50, 5.00, '2022-06-13 19:29:50', '2022-06-13 19:29:50', 'UPPS memiliki kebijakan dalam mengatur SDM dan Sapras, kemampuan melaksanakan ditunjukkan dengan keberadaan SOP. Penjaminan mutu berkelanjutan dengan audit internal, namun perlu konfirmasi  bukti pendukung.', 11), (24297, 146, 1, 2.50, 1.00, 2.50, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Terkait lingkungan eksternal, UPPS melakukan :\n1) identifikasi lingkungan makro, mencakup aspek politik dimana ada keterlibatan FT dalam perencanaan infratruktur daerah. Aspek ekonomi yaitu adanya ketidakjelasan kondisi ekonomi yang menjadikan PSTM agar dapat terus berinovasi dalam marketing dan pembiayaan yang terjangkau. Aspek Kebijakan pemerintah dengan mengeluarkan KIP guna meningkatkan kualitas SDM sehingga memberikan efek positif kepada PS TM dalam peningkatan animo masyarakat. Aspek sosial dan budaya diidentifikasi sebagai faktor peluang yang dapat meningkatkan anomo masyatakat. Aspek perkembangan IPTEK diidentifikasi dapat mendukung kegiatan pembelajaran dan kegiatan PPM.\n2) identifikasi lingkungan mikro menunjukkan bahwa PS TM merupakan salah satu PS dari PTS dengan daya tarik sendiri yang menjalankan PS sesuai VMTS berbasis IPTEK dan ecopreuneurship.\n3) hasil identifikasi digunakan untuk melakukan analisis SWOT mencakup kekuatan antara lain dalam tata pamong, kerjasama dan SDM; kelemahan antara lain dalam monev yang belum optimal, peminat mahasiswa baru yang masih rendah dan  jja dosen dengan Lektor ke atas yang masih rendah; ancaman antara lain semakin bertambahnya pesaing di daerah, perubahan teknologi yang pesat dan minat masyarakat ke pendidikan FT yang rendah.\nAnalisis SWOT digunakan untuk mengembangkan PS.\nAnalisis SWOT belum dilengkapi faktor peluang. Perlu konfirmasi.\n4) UPPS merumuskan 12 strategi pengembangan PS, namun belum dilengkapi dengan tahapan prioritas dan indikator capaian yang relevan. \nPada LED hal 11, terdapat strategi sesuai Renstra 2021-2030 dengan tahapan tahun pertama 2021-2025 mencakup 4 strategi. Perlu dikonfirmasi.\n', NULL), (24298, 146, 2, 3.50, 1.00, 3.50, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'UPPS mendeskripsikan profilnya mencakup:\n1) menunjukkan keserbacakupan informasi yang jelas mencakup sejarah UPPS dimana PS TM berdiri pada 1990, VMTS dan tata nilai, organisasi dan tata kerja, mahasiswa dan lulusan, dosen dan tendik, keuangan dan sapras, dan kinerja PS.\n2) ada keselarasan dengan substansi keilmuan program studi, yang tercermin dalam perumusan VMTS dengan strategi pengembangan yang tertuang dalam Renstra 2021-2025.\n3)  iklim yang kondusif untuk pengembangan keilmuan program studi, dengan mendorong strategi pengembangan PS sejalan dengan UPPS.\n4) menunjukkan reputasi sebagai rujukan di bidang keilmuannya dengan memperoleh penghargaan pada lomba-lomba akademik di tingkat lokal dan nasional.', NULL), (24299, 146, 3, 3.00, 0.47, 1.41, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Visi UPPS adalahMenjadi fakultas teknik unggulan di Provinsi Jawa Tengah, yang profesional berwawasan IPTEK, IMTAQ dan Ecopreneurship pada tahun 2024. Visi tersebut diturunkan dari Visi Universitas dan memayungi kelimuan visi PS yaitu Menjadi Program Studi Teknik Mesin Unggulan  di Provinsi Jawa Tengah, yang profesional berwawasan IPTEK, IMTAQ dan Ecopreneurship pada tahun 2024. \r\nPenyusunan VMTS PS didasarkan pada VMTS yang akan dicapai UPPS. Misi, tujuan dan strategi UPPS searah dan bersinergi dengan misi, tujuan dan strategi PT serta mendukung program studi. \r\nPerlu dikonfirmasi tahun pencapaian visi PS. Belum ada data implementasi yang relevan.', 1), (24300, 146, 4, 3.00, 0.47, 1.41, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Mekanisme penyusunan visi, misi dan tujuan dan sasaran program studi, diawali dengan pembentkan tim task force  untuk mendesain alternatif rancangan dengan melakukan analisis situasi (SWOT PS) serta mengakomodasi masukan baik dari internal stakeholder maupun eksternal stakeholder.  Pihak yang terlibat : pimpinan PS dan UPPS, unit penjaminan mutu seluruh dosen yang terlibat dalam proses belajar mengajar di Program Studi Teknik Mesin,  tendik, mahasiswa, alumni, pengguna alumni. \nBelum ada informasi keterlibatan pakar/mitra/organisasi prfesi/pemerintah).\nPelu konfirmasi pada AL.', 1), (24301, 146, 5, 3.00, 0.47, 1.41, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'VMTS disosialisasikan secara internal kepada dosen dan pegawai melalui pencantuman VMTS dalam berbagai pedoman akademik dan non akademik, disampaikan dalam rapat koordinasi, pemasangan dalam banner di ruangan. Ssosialisasi secara eksternal dengan penyampaian pada acara yang mengundang stakeholder ke kampus, kegiatan sosial WA dan facebook, website, dan brosur PMB, seminar dan pelatihan. \nAda implementasi VMTS pada kurikulum yang melakukan perubahankurikulum sesuai dengan perkembangan IPTEK, kebutuhan masyarakat dan pengguna lulusan. Ada survey pemahaman VMTS yang dilakukan oleh lembaga penjaminan mutu, namun belum dijelaskan metode dan instrumennya. Pada LED hal 27 ada informasi 85% sivitas akademik paham dengan VMTS PS TM. Perlu dikonfirmasi.', 1), (24302, 146, 6, 2.00, 1.42, 2.84, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Pada LED hal 11, dijelaskan Sasaran dan strategi pencapaian PS sesuai dengan Renstra UPPS (2021-2030) disusun dengan 2 (dua) periode Renstra yaitu pada tahun 2021- 2025, dan pada tahun 2025-2030. Orientasi jangka menengah adalah tercapainya pada tingkat lokal, sedangkan rencana panjang tercapainya pada tingkat nasional. Hasil pengukuran capaian IKU diinformasikan adalah 68,21%. Perlu dikonfirmasi instrumen dan metode pengukuran yang dilakukan.\nPerlu dikonfirmasi relevansi target tahapan strategi dengan tahapan pencapaian visi di tahun 2024.', 1), (24303, 146, 7, 2.67, 0.66, 1.76, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'A. UPPS memiliki struktur organisasi terdiri dari Dekan, Unit Penjaminan Mutu, Pimpinan Prodi, Bag Akademik, Sub TU, Kasubag, Kalab dan Operator yang dilengkapi deskripsi ttupoksi dan tugas wewenang, tercantum dalam LED hal 11-19. \nDisebutkan ada dokumen Statuta untuk acuan persyaratan Kaprodi, namun belum ada informasi dokumen formal struktur organisasi dan tata kerja.\nPerlu dikonfirmasi posisi Senat Fakultas dan Ruang Baca pada Struktur.\nB. UPPS menerapkan tata pamong yang mencakup aspek :\n1) Kredibel, dalam hal pemilihan Kaprodi  yang dilakukan melalui rapat senat sesuai persyaratan yang mengacu kepada STatuta Universitas.\nPenerapan peraturan akademik, kode etik mahasiswa, dosen dan pegawai, buku panduan dan tata tertib baik dalam penyelanggaraan, pembelajaran maupun disiplin kepegawaian.\n2)  Adil terhadap dosen, karyawan dan mahasisa yang berprestasi diberikan reward dan kepada yang melanggar aturan dibrikan sanksi (punishment) serta sivitas akademika mendapat perlakuan yang sama sesuai dengan standar-standar yang berlaku.\n3) Transparan dalam penilaian secara terbuka antara pemberi nilai dan yang diniliai.\n4) Akuntabel dengan  setiap kegiatan yang sudah dilaksanakan harus dipertanggungjawabkan dan dilaporkan hasilnya.\n5) Bertanggung jawab ditandai adanya struktur organisasi, uraian tugas, fungsi dan tanggung jawab. Universitas memiliki dan memberlakukan Kode Etik dosen yang mendukung pelaksanaan system yang bertanggung jawab.\nPenjelsan normatif, perlu konfirmasi bentuk penerapannya.\n', 2), (24304, 146, 8, 2.00, 0.66, 1.32, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'A) Karakteristik kepemimpinan operasinal dalam melaksanakan tugas dan tanggung jawab kepemimpinan dengan memberikan arahan, tujuan, peran dan tugas kepada seluruh unsur di dalam Jurusan Teknik Mesin. Pelaksanaan tugas dan tanggung jawab kepemimpinan dilakukan oleh ketua jurusan. Sekretarisjurusan bertugas melakukan pembinaan dan mengkoordinasi pelaksanaan tugas tenaga pendidikan. Kepemimpinan organisasaia dalam bentuk mengarahkan dan mempengaruhi perilaku semua unsurdalam program studi, mengikuti nilai, norma, etika, dan budaya organisasi yangdisepakati bersama, serta mampu membuat keputusan yang tepat dan cepat Fakultas Teknik Universitas Garuda Dipimpin oleh seorang Dekan dengan dibantu oleh Wakil Dekan bidang Akademik (PD I), WakilDekan Bidang Administrasi dan Keuangan (PD II), Wakil Dekan BidangKemahasiswaan (PD. III), sedangkan kepemimpinan pada Program Studidipimpin oleh Ketua Program Studi. \r\nBelum ada informasi kepemimpinan Publik.\r\nB) Kapabilitas pimpinan UPPS mencakup :\r\n1) Perencanaan, dengan membuat program kerja tahunan, setiap tahunnya dilakukan diskusi dengan seluruh tenaga akademik dalam rapat program studi. Bentuk kegiatan dijelaskan bahwa setiap awal semester dilakukan perencanaan untuk kegiatan akademis pada semester bersangkutan, seperti penentuan mata kuliah yang diampu oleh masing-masing tenaga akademik.\r\n2) Pengorganisasian, dengan mengkoordinasikan penyusunan kurikukulum, penyelenggaraan kegiatan akademik, pelaksanaan penelitian dan PkM berkoordinasi dengan LPPM.\r\n3) Penempatan Personil, dengan memperoleh tenaga akademik yang relevan dengan kebutuhan PS  melalui proses rekruitment oleh pihak rektorat dengan mempertimbangkan spesifikasi yang ditentukan PS TM.\r\n4) Pengendalian, dengan cara memantau sebelum, sesama dan setelah kegiatan Tri Dharma Perguruan Tinggi serta juga memantau kesesuaiannya dengan manual prosedur dalam setiap kegiatan.\r\nBelum ada informasi kapabilitas pimpinan terkait pelaksanaan dan pelaporan  yang menjadi dasar tindak lanjut. Pelu konfirmasi pada AL.', 2), (24305, 146, 9, 2.50, 1.32, 3.30, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Terdapat 12 Kerjasama yang sudah dibangun oleh Fakultas Teknik sebagai UPPS dan Prgram Studi TM,  khusunya dengan berbagai universitas lain/stakeholder di tingkat lokal, nasional dan internasional. Kerjasama tersebut meliputi kegiatan Tri Dharma Perguruan Tinggi yaitu kegiatan pendidikan, pengabdian dan penelitian. Bukti pendukung kegiatan kerjasama  adalah SPK. 1) Ada penjelasan ttg manfaat kerjasama antara lain meningkatkan hubungan kelembagaan dan kemitraan, membantu dalam melaksanakan kegiatan pendidikan dan uji tes di lapangan, kegiatan tridarma dalam bidang TM; 2) peningkatan kinerja tridharma berupa fasilitas uji tes; 3) belum ada evaluasi kepauasan kepada mitra industri/kerjasama. \nPenjelasn aspek manfaat masin normatif. Perlu dikonfirmasi.', 2), (24306, 146, 10, 3.85, 0.66, 2.54, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Dari tabel 1 LKPS, terlihat jumlah kerjasama adalah sbb: N1= pendidikan=12, N2=penelitian=12 dan, N3= pengabdian kepada masyarakat=11, sedangkan jumlah dosen tetap NDTPS=8, sehingga RK=6.45. Sedangkan tingkat kerjasama adalah tingkat lokal/wilayah (6), nasioinal (5) dan 1 kerjasama internasional. Akan diverifikasi saat AL.', 2), (24307, 146, 11, 2.50, 1.32, 3.30, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'UPPS telah menetapkan indikator kinerja tambahan pada seluruh kriteria yang menunjukkan daya saing di tingkat nasional, antara lain terlaksananya pengelolaan adm pendidikan d Univ, keaktifan mahasiswa di bid non akademik, target 40% dosen berprestasi dalam luaran tridarma.. Tidak semua indikator kinerja tambahan memiliki indikator kinerja yang dapat diukur. Ada evaluasi capaian kinerja yang dilakukan, yang dilengkapi dengan informasi identifikasi akar masalah, faktor pendukung dan penghampat ketrecapaian.', 2), (24308, 146, 12, 1.50, 1.99, 2.99, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Ada evaluasi capaian kinerja yang dilakukan, yang dilengkapi dengan informasi identifikasi akar masalah, faktor pendukung dan penghampat ketrecapaian. Belum ada informasi metode pengukuran dan analisis keberhasilan dan/atau ketidakberhasilan yang dilakukan. Belum ada informasi publikasi hasil analisis yang dilakukan.', 2), (24309, 146, 13, 0.80, 3.31, 2.65, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Dari tabel 2.a LKPS terlihat jumlah calon mhs yang ikut seleksi=NA=89, dan yg lulus seleksi NB=89, Rasio=1', 3), (24310, 146, 14, 1.67, 2.21, 3.68, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'A) Dari LKPS terlihat jumlah calon yang mendaftar adalah sbb: pd TS-2= 24, pd TS-1= 19, dan pada TS=17. Artinya mengalami penurunan selama 3 tahun terakhir. Upaya yang dilakukan untuk meningkatkan animo sebagai tindak lanjut, yaitu Meningkatkan sosialisasi program studi teknik mesin Universitas Garuda lebih intensif melalui media sosial, alumni dan mahasiswa PS,  Kegiatan himpunan yang ada diluar kampus dan road show ke SMA/MA/SMK, Meningkatkan jumlah layanan kepada mahaiswa untuk minat dan bakat, Meningkatkan sarana dan prasarana pada bidang akademik maupun non akademik   \r\nB)  Tidak ada mahasiswa asing.\r\nData pada LKPS berbeda dengan LED, perlu dikonfirmasi. ', 3), (24311, 146, 15, 1.50, 1.10, 1.65, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'A) Jenis layanan yang tersedia mencakup Layanan bimbingan konseling dengan dosen PA, dosen pembimbing KP dan Skripsi, dan pendamping kegiatan kelembagaan.\nTidak ada informasi layanan minat bakat, layanan beasiswa, layanan kesehatan, layanan bimbingan karir dan kewirausahaan.\nB) Layanan bimbingan dan konseling dapat diaksaes dengan mudah.', 3), (24312, 146, 16, 2.86, 0.47, 1.34, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Dari LPKS terlihat jumlah dosen tetap yang ditugaskan sbg pengampu mata kuliah sesuai bidang keahlian PS yang diakreditasi DTPS= 8 dari 15 dosen tetap. DTPS tersebut adalah Ari Beni, M. Thohirin, Agus A., Kemas MA, M. Yunus, Indriyani, Wisnaningsih dan Refi Arioen. Tidak ada dosen tidak tetap.', 4), (24313, 146, 17, 2.50, 0.76, 1.90, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Dari LPKS terlihat jumlah dosen tetap  bergelar S3 sebanyak 3 orang, dengan bidang keahlian hukum, manajemen dan ilmu pertanian. Dari bidang keahlian ini yang sesuai dengan kompetensi PS hanya 1 orang an Dr. Refi Arioen.', 4), (24314, 146, 18, 3.43, 0.38, 1.30, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Dari 8 DTPS, dosen dengan jabatan akademik Lektor sebanyak 3 orang dan 1 orang Lektor Kepala.', 4), (24315, 146, 19, 1.87, 0.38, 0.71, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Jumlah mahasiswa pada TS=NM=81, sedangkan DTPS=8, sehingga rasio mahasiswa dengan dosen = 6.38. Perlu konfirmasi jumlah mahasiswa transfer 30 orang.', 4), (24316, 146, 20, 4.00, 0.66, 2.64, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Rata-rata jumlah mhs yang dibimbing sebagai pembimbing utama TA = 0.42. Perlu konfirmasi DTPS.', 4), (24317, 146, 21, 1.27, 0.19, 0.24, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Rata-rata EWMP DTPS pd TS=12.18 dengan DTPS berjumlah 8 orang.', 4), (24318, 146, 22, 4.00, 0.38, 1.52, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Tidak ada dosen tidak tetap yang ditugaskan mengampu MK PS.', 4), (24319, 146, 23, 4.00, 0.66, 2.64, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Disebutkan dalam LKPS, dari 8 DTPS terdapat 18 rekognisi dalam 3 tahun terakhir. Rekognisi tersebut antara lain sebagai keynote speaker, staf ahli, editor atau mitra bestari. Perlu cek dokumen.', 4), (24320, 146, 24, 2.40, 0.66, 1.58, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Jumlah penelitian 8 DTPS dalam 3 tahun terakhir adalah sbb: Biaya luar negeri NI=0, biaya dalam negeri NN=2, dan biaya PT/Mandiri NL=66.\nData LKPS berbeda dengan LED (biaya dalam negeri = 1), perlu konfirmasi.\nCek dokumen pada AL.\n', 4), (24321, 146, 25, 2.40, 0.38, 0.91, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Jumlah kegiatan PkM 8 DTPS dalam 3 tahun terakhir adalah sbb: Biaya luar negeri NI=0, biaya dalam negeri NN=2, dan biaya PT/mandiri NL=45.\nData LKPS berbeda dengan LED (biaya dalam negeri = 0), perlu konfirmasi.\nCek dokumen pada AL.', 4), (24322, 146, 26, 4.00, 0.66, 2.64, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Jumlah publikasi 8 DTPS dalam 3 tahun terakhir adalah sbb: di jurnal nasional tidak terakreditasi NA1=43, di jurnal nasional terakreditasi NA2=14, di jurnal internasional NA3=10, di jurnal internasional bereputasi NA4=0. Jumlah publikasi di seminar adalah sbb:  wilayah/lokal NB1=0, nasional NB2=6, internasional NB3=2. Jumlah tulisan di media massa sbb: wilayah NC1=1, nasional NC2=0, dan internasional NC3=0.\nPerlu cek dokumen.', 4), (24323, 146, 27, 4.00, 0.66, 2.64, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Dari 8 DTPS, terdapat 10 judul artikel yang disitasi.\nPerlu cek dokumen. ', 4), (24324, 146, 28, 4.00, 0.66, 2.64, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Dari 8 DTPS, luaran penelitian dan PkM dalam 3 tahun terakhir adalah sbb:  NA=19 paten, NB=0, Teknologi tepat guna/karya seni/poduk NC= 0, dan Buku berISBN, Book chapter ND=11. \nPerlu konfirmasi Paten termasuk skripsi. Akan diverifikasi saat AL.', 4), (24325, 146, 29, 3.00, 1.70, 5.10, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Upaya pengembangan dosen tercantum dalam rencana strategis Unit Pengelola Program Studi, yaitu kewajiban dosen yang mengajar diwajibkan memiliki kepangkatan akademik dan NIDN, sertifikasi dosen dan beasiswa bagi dosen studi lanjut S3.', 4), (24326, 146, 30, 3.00, 0.85, 2.55, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'A) Jumlah total tenaga kependidikan di PS  adalah 14 orang, terdiri dari 1 orang berpendidikan S2 sebagai Ka.Lab Fakultas, 10 orang berpendidikan S1 (1 pustawakan, 6 laboran dan 3 tenaga administrasi), 2 orang teknisi lab dari SMA/SMK dan 1 orang OB.  Jumlah keseluruhan tersebut cukup. B) Laboran PSTM ada 6 orang, seluruhnya S1.\nBelum ada informasi tendik di UPPS.', 4), (24327, 146, 31, 2.79, 0.83, 2.31, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Rata-rata biaya operasional pendidikan dalam 3 tahun BOP= Rp.1128682600 , sedangkan jumlah mhs pada TS=81, sehigga DOP=13.9 juta.', 5), (24328, 146, 32, 4.00, 0.83, 3.32, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Rata-rata jumlah dana penelitian yg diperoleh 8 DTPS dlm 3 tahun terakhir DP= Rp.133,3 juta, sehingga rata-rata dana penelitian DTPS per tahun= Rp. 16,67 juta. Perlu konfirmasi.', 5), (24329, 146, 33, 4.00, 0.41, 1.64, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Rata-rata jumlah dana PkM yg diperoleh 8 DTPS dlm 3 tahun terakhir DPkM= Rp. 66 juta, sehingga rata-rata dana PkM DTPS per tahun= Rp. 8,3 juta.', 5), (24330, 146, 34, 2.00, 0.41, 0.82, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Penggunaan dana untuk investasi pada PS rata-rata selama 3 tahun terakhir adalah Rp. 69 juta. Lab yang tersedia ada 4 lab. Belum ada informasi target investasi yang direncanakan. ', 5), (24331, 146, 35, 3.00, 0.83, 2.49, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Semua sumber dana diperoleh dari Yayasan dengan mekanisme pelaporan secara tertulis. Usulan kebutuhan anggaran dari unversitas, fakultas atau lembaga secara tertulis sesuai dengan program kerja. Pengadaan sumber dana dilakukan oleh Yayasan atas usul dari rektor. Pimpinan Univ diperkenankan mencari dan menerima sumbangan dari pihak lain dengan persetujuan Yayasan, yang dikelola dan ditetapkan dalam rapat kerja kemudian dialokasikan kepada Program Studi Teknik Mesin sesuai mekanisme yang diatur oleh surat keputusan Yayasan. Dengan rata-rata BOP 22 juta, mencukupi untuk mendukung proses pembelajaran.', 5), (24332, 146, 36, 3.00, 3.31, 9.93, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Sarana penunjang pendidikan program studi Sarjana Teknik Mesin terdiri atas 4 laboratorium, yaitu Lab Manufaktur, Lab Tugas Elemen, Lab Prestasi Mesin dan Lab Komputer. Juga terdapat ruang baca, ruang kelas, ruang lab bahasa Inggris, ruang Ka. Lab.', 5), (24333, 146, 37, 2.10, 2.25, 4.73, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'A) Kurikulum program studi dilakukan pemutakhiran setiap 5 tahun sekali, yang dilakukan oleh tim pengembang kurikulum program studi dan Fak dengan mengundang dosen, stakeholder untuk informasi perkembangan IPTEK, dan direview pakar.\nBelum ada informasi pemutakhiran terakhir yang dilakukan.\nPerlu dikonfirmasi pakar yang dilibatkan.\nB) Kurikulum program studi Sarjana Teknik Mesin disusun dengan mengacu pada profil lulusan yang ditetapkan berdasarkan KKNI Level 6 dan SN-Dikti.\nBelum ada informasi keberkalaan pemutakhiran CPL. Perlu dikonfirmasi.\nC) Pada Tabel 5a-1,  semua MK pada struktur kurikulum memuat CPL, namun belum ada informasi peta kurikulum yang menunjukkan pemenuhan dan keterkaitan CPL dengan CPMK.', 6), (24334, 146, 38, 1.00, 0.45, 0.45, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Tidak ada informasi pemenuhan pemenuhan karakteristik proses pembelajaran, yang terdiri atas sifat: 1) interaktif, 2) holistik, 3) integratif, 4) saintifik, 5) kontekstual, 6) tematik, 7) efektif, 8) kolaboratif, dan 9) berpusat pada mahasiswa.', 6), (24335, 146, 39, 1.17, 1.62, 1.89, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'A). Pada LED hal 93 dan Tabel 5a-1 LKPS disebutkan bahwa seluruh MK dilengkapi dengan silabus dan RPS yang selalu dimutakhirkan. Namun tidak ada informasi kelengkapan RPS mencakup target capaian pembelajaran, bahan kajian, metode pembelajaran, waktu dan tahapan, asesmen hasil capaian pembelajaran.\nB) Belum ada informasi isi materi pembelajaran sesuai dengan RPS, dan memiliki kedalaman dan keluasan yang relevan untuk mencapai capaian pembelajaran lulusan.\nPerlu konfirmasi.', 6), (24336, 146, 40, 1.56, 0.90, 1.40, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'A) Interaksi dosen dengan mahasiswa dalam perkuliahan, bimbingan akademik/konseling, bimbingan tugas perancangan, bimbingan kerja praktek dan bimbingan skripsi/TA. Selain itu ada interaksi dosen melibatkan mahasiswa untuk membantu dalam praktikum maupun penelitian. \nB) Monitoring dan evaluasi (monev) proses belajar mengajar pada PS dilakukan sesuai dengan Peraturan Akademik Universitas  serta RPS. \nBelum disebutkan dokumen yang mendukung kegiatan. Perlu konfirmasi.\nC) Proses pembelajaran yang terkait dengan penelitian dijalankan dengan pelaksanaan penelitian oleh dosen dan mahsiswa. \nPerlu konfirmasi dokumen yang mendukung proses pembelajaran. \nD) Belum ada informasi Integrasi pembelajaran dengan PkM.\nE) Belum ada informasi kesesuaian metode pembelajaran dengan capaian pembelajaran.', 6), (24337, 146, 41, 2.50, 0.54, 1.35, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Jumlah sks pembelajaran praktikum, praktik studio, praktik bengkel, atau praktek lapangan (termasuk KKN) = 25 sedangkan jumlah sks pembelajaran total selama masa pendidikan= 144. \nData diisi dalam sks, perlu dikonfirmasi jumlah total jam belajar perkuliahan dan jam praktikum/praktek', 6), (24338, 146, 42, 2.50, 2.25, 5.63, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Pelaksanaan monitoring yang dilakukan dengan cara mengumpulkan data untuk melihat penyimpangan dan kesenjangan dalam melakukan proses pembelajaran, meminta penjelasan, membandingkan, menelaah dokumen untuk menilai tingkat relevansi materi yang disampaikan pada saat proses pembelajaran (tatap muka) dengan RPS. UPPS dan program studi teknik mesin melakukan pemantauan, serta melaporkan hasil program pembelajaran secara periodik.\nBelum ada informasi dokumentasi terkait dan tindak lanjut.', 6), (24339, 146, 43, 0.40, 1.62, 0.65, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'A) Pada LED hal 91 disebutkan bahwa prinsip penilaian dilakukan secara edukatif, otentik, objektif, akuntable,dan transparan yang dilakukan secara terintegrasi. Namun belum ada informasi bukti shahih terpenuhinya 5 prinsip penilaian pembelajaran edukatif, otentik, objektif, akuntabel, dan transparan yang dilakukan secara terintegrasi untuk mengukur ketercapaian capaian pembelajaran lulusan. Belum ada informasi rubrik/portofolio penilaian. \nB) Belum ada informasi pelaksanaan penilaian dimuat dalam dokumen pedoman akademik universitas tentang teknik dan instrumen penilaian.\nC) Belum ada informasi pelaksanaan penilaian mencakup 7 unsur.', 6), (24340, 146, 44, 2.00, 0.72, 1.44, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Pada Tabel 5a.3 LKPS, jumlah sks MK basic science dan matematika adalah 17 sks mencakup kimia dasar, fisika dasar, kalkulus, fisika II, matematika teknik 1, matematika teknik 2. \nPerlu konfirmasi struktur kurikulum yang digunakan pada TS, kurikulum baru atau lama.', 6), (24341, 146, 45, 1.00, 0.72, 0.72, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Pada Tabel 5a.4 LKPS, MK casptone design adalah Menggambar Teknik, Pemrograman Komputer, Menggambar Mesin, Tugas Elemen Mesin dan Tugas Akhir. Semua MK tersebut memiliki CPL sesuai Tabel 5a.1.\nTidak ada informasi panduan pelaskanaan, penggunaan standar keteknikan dan batasan realistis dan bukti shahih pelaksanaan.', 6), (24342, 146, 46, 2.00, 0.36, 0.72, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Pada LKPS, terdapat 13 sks perkuliahan untuk belajar di luar PS dan 2 kegiatan MBKM dengan jenis kegiatan penelitian dengan Jumlah mahasiswa yang terlibat = 2orang.', 6), (24343, 146, 47, 4.00, 1.62, 6.48, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Pada LKPS, terdapat 40 MK yang dikembangkan berdasarkan hasil penelitian dan/atau PkM DTPS dalam 3 tahun terakhir. \nPerlu konfirmasi data.', 6), (24344, 146, 48, 2.00, 2.25, 4.50, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Kegiatan-kegiatan yang sudah dijalankan oleh PSTM untuk mendukung suasana akademik adalah pelatihan bidang ketenikmesinan (SAP dan AUTOCAD), pengenalan kehidupan kampus yang diadakan pada waktu mahasiswa baru masuk, seminar dan lokakarya dosen bekerja sama dengan Universitas, temu dosen, mahasiswa dan alumni pada saat yudisium. \nBelum ada informasi jadwal dan keberkalaan kegiatan. Perlu konfirmasi bukti.', 6), (24345, 146, 49, 1.33, 2.70, 3.60, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'A) Ada 5 aspek yang diukur, yaitu: keandalan, daya tanggap, kepastian, empati dan tangible. Berikut adalah tingkat kepuasan masing-masing aspek, yaitu: untuk keandalan dengan tingkat kepuasan sangat baik= 27.8%, baik = 72.2%, cukup = 0 dan kurang = 0. Untuk daya tanggap, tingkat kepuasan sangat baik = 52.8%, baik = 47.2%, cukup = 0, dan kurang = 0. Untuk kepastian, tingkat kepuasan dgn sangat baik = 31.9%, baik = 68.1%, cukup = 0, dan kurang = 0, untuk aspek empati, tingkat kepuasan sangat baik = 31.8%, baik = 68.1%, cukup = 0, dan kurang= 0, sedangkan untuk tangible dengan tingkat kepuasan sangat baik = 30.6%, baik = 69.4%, cukup = 0 dan kurang = 0. \nB) Tidak ada informasi dilakukannya evaluasi terhadap kepuasan terhadap proses pembelajaran. Tidak ada penjelasan rencana perbaikan dan pengembangan pendidikan.', 6), (24346, 146, 50, 2.50, 0.94, 2.35, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Relevansi penelitian pada UPPS mencakup : \n1) ada informasi kebijakan arah dan peta jalan penyelenggaraan penelitian berpedoman pada rencana induk penelitian Universitas sesuai Statuta Univ.\n2) ada informasi kebijakan bahwa dalam pelaksanaan penelitian berdasarkan pedoman penelitian dan dapat melibatkan dosen dan/ tendik. Terdapat 21 penelitian dosen yang melibatkan mahasiswa selama 3 tahun terakhir.\n3) UPPS memiliki manual standar evaluasi dan pengendalian hasil penelitian, namun tidak ada informasi melakukan evaluasi kesesuaian penelitian dosen dan mahasiswa dengan peta jalan. \n4) Tidak ada informasi menggunakan hasil evaluasi untuk perbaikan relevansi penelitian dan pengembangan keilmuan program studi.', 7), (24347, 146, 51, 4.00, 1.89, 7.56, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Pada LKPS, terdapat 21 penellitan dosen yang melibatkan mahasiswa, dari total 68 penelitian dosen selama 3 tahun terakhir.\nPerlu konfirmasi bukti keterlibatan.', 7), (24348, 146, 52, 2.50, 0.63, 1.58, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Relevansi PkM pada UPPS mencakup : \n1) ada informasi kebijakan yang tercantum di Statuta Univ bahwa Arah dan peta jalan penyelanggaran pengabdian kepada masyarakat berpedoman pada rencana induk pengabdian universitas.\n2) ada informasi kebijakan bahwa dalam melaksanakan PkM sesuai dengan agenda dosen yang merujuk kepada peta jalan penelitian, dapat melibatkan mahasiswa dan/ tendik.\n3) Tidak ada informasi melakukan evaluasi kesesuaian PkM dosen dan mahasiswa dengan peta jalan, dan \n4) Tidak ada informasi menggunakan hasil evaluasi untuk perbaikan relevansi penelitian dan pengembangan keilmuan program studi.', 8), (24349, 146, 53, 2.51, 1.26, 3.16, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Pada LKPS, terdapat 3 PkM dosen yang melibatkan mahasiswa, dari total 68 penelitian dosen selama 3 tahun terakhir.\nPerlu konfirmasi bukti keterlibatan.', 8), (24350, 146, 54, 0.00, 2.09, 0.00, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Tidak ada informasi dilakukan analisis pemenuhan capaian pembelajaran lulusan yang memenuhi 3 aspek.', 9), (24351, 146, 55, 3.68, 2.09, 7.70, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Data jumlah lulusan adalah sbb: pd TS-2= 6, pd TS-1= 10, dan pad TS= 10, sedangkan IPK rata-rata adalah sbb: pada TS-2=3.09, pd TS-1=3.01, dan pd TS= 3,07, sehingga rata-rata IPK lulusan dalam 3 tahun terakhir adalah=3,05. ', 9), (24352, 146, 56, 3.75, 3.22, 12.08, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Disebutkan terdapat jumlah prestasi mhs di bidang akdemik dlm 3 th terakhir sbb: NI=internasional =0, NN=nasional= 2, dan prestasi lokal/wilayah NW=2, jumlah mhs NM=81. Perlu konfirmasi saat AL', 9), (24353, 146, 57, 3.75, 0.64, 2.40, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Disebutkan terdapat jumlah prestasi mhs di bidang non-akdemik dlm 3 th terakhir sbb: NI=internasional =0, NN=nasional= 9, dan prestasi lokal/wilayah NW=1, jumlah mhs NM=81. Akan diverfikasi saat AL', 9), (24354, 146, 58, 3.04, 2.09, 6.35, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Dari jumlah mahasiswa TS-6 = 10 orang, rata-rata masa studi = 5.10 tahun', 9), (24355, 146, 59, 0.00, 2.09, 0.00, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Jumlah mahasiswa yang diterima pada TS-3 sebanyak 8 orang, belum ada yang lulus pada TS.', 9), (24356, 146, 60, 4.00, 2.09, 8.36, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Dari jumlah mahasiswa yang diterima pada TS-6 sebanyak 10 orang, selurunya telah lulus pada akhir TS.', 9), (24357, 146, 61, 1.00, 3.22, 3.22, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Disebutkan pelaksanaan tracer study dilakukan oleh Fakultas Teknik pada anggl 06 Ags 2021- 09 Oktober 2021 (LED hal 8).  Pelaksanaan telah dilakukan terhadap 230 lulusan. \nTidak ada informasi : dokumentasi dan keberkalaan tracer study; isi kuesioner, target populasi dan sosialisasi hasil tracer study.', 9), (24358, 146, 62, 4.00, 3.22, 12.88, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Dari tabel 8.d.1 LKPS, jumlah lulusan: pada TS-4=12, pd TS-3 = 19, dan pd TS-2=6, selurunya terlacak (100%). Data waktu tunggu lulusannya: (WT) < 6 bulan, dengan tahun lulus pada: TS-4=11, TS-3=17 dan TS-2=5. (WT) 6 bulan ≤ WT ≤ 6 bulan, dengan tahun lulus pada: TS-4=1, TS-3=2 dan TS-2=1. Sedangkan WT > 6 bulan, dengan tahun lulus pada: TS-4=0, TS-3=0 dan TS-2=0. Dari data tersebut, maka rata-rata waktu tunggu lulusan (WT) = 1.8 bulan. ', 9), (24359, 146, 63, 4.00, 2.09, 8.36, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Dari tabel 8.d.2 LKPS, jumlah lulusan: pada TS-4=12, pd TS-3 = 19, dan pd TS-2=6, selurunya terlacak (100%).. Jumlah lulusan dengan kesesuaian: bidang kerja rendah: pada TS-4=0; TS-3=0, dan pd TS-2=0, bidang kerja sedang: pada TS-4=1; TS-3=2 dan pada TS-2=3, dan bidang kerja tinggi: pada TS-4=11; TS-3=17 dan pada TS-2=3, sehingga PBS = Kesesuaian bidang kerja lulusan saat mendapatkan pekerjaan pertama = 91.9%', 9), (24360, 146, 64, 3.75, 2.09, 7.84, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Dari tabel 8.e.1 LKPS, jumlah lulusan: pada TS-4=12, pd TS-3 = 19, dan pd TS-2=6, selurunya terlacak (100%). Tingkat dan ukuran tempat kerja lulusan, adalah sbb: Tidak ada lulusan bekerja pada tingkat multi nasional/internasional, lulusan bekerja pada lokal/wilayah/berwirausaha berijin pada TS-4=5, TS-3=8, TS-2=5, lulusan bekerja pada lokal/wilayah/berwirausaha tidak berijin pada TS-4=7, TS-3=11, TS-2=1.', 9), (24361, 146, 65, 3.81, 4.02, 15.33, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Dari tabel 8.e.2 LKPS, jumlah lulusan: pada TS-4=12, pd TS-3 = 19, dan pd TS-2=6, selurunya terlacak (100%). Tingkat kepuasan pengguna dalam 7 aspek adalah sbb: 1) Aspek Etika: sangat baik=SB= 80%, baik=B= 20%, cukup=C=0 dan kurang K=0. 2) Aspek Keahlian: SB= 90%, B=10%, C=0, dan K=0. 3) Aspek Kemampuan berbahasa asing: SB=0,9, B=0,1, C=0, dan K= 0. 4) Aspek Penggunaan teknologi informasi: SB=60%, B=40%, C=0, dan K=0. 5) Aspek kemampuan Berkomunikasi: SB=70%, B=30%, C=0, dan K=0. 6) Aspek kerjasama tim: SB=90%, B=10%, C=0, dan K=0. 7) Aspek Pengembangan diri: SB= 90%, B=10%, C=0, dan K=0. ', 9), (24362, 146, 66, 0.51, 2.57, 1.31, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Publikasi ilmiah dari mahasiswa yang dihasilkan secara mandiri atau bersama DTPS dengan judul relevan dengan bidang PS dalam 3 tahun terakhir adalah sbb: NA1=publikasi di jurnal nasional tidak terakreditasi = 5, seminar nasional = 6. Sedangkan publikasi lainnya tidak ada.', 9), (24363, 146, 67, 4.00, 0.64, 2.56, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Terdapat luaran penelitian/PkM yang dihasilkan mahasiswa secara mandiri atau bersama dosen, dengan perincian sbb : luaran penelitian/PkM yang mendapat pengakuan HKI (Paten, Paten Sederhana) = 6; luaran penelitian/PkM yang diterbitkan dalam bentuk Buku ber-ISBN, Book Chapter=2. Luaran lainnya tidak ada.\nPerlu konfirmasi luaran dalam bentuk paten/paten sederhana dalam bentuk skripsi (5 skripsi)', 9), (24364, 146, 68, 2.00, 1.00, 2.00, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Keterlaksanaan sistem penjaminan mutu internal :\n1) Ada informasi struktur organisasi sesuai Statuta yang terdiri dari LPM di tingkat Univ, Kabid SPMI, Kabid SPME dan UPM Fakultas. \nDokumen pembentuk tercantum dalam SK Ketua UPPS mengenao penempatan pegawai tetap LPM dan Keputusan Badan Penyelenggaran.\n2) Belum ada informsai dokumen legal auditor bersifat independen.\n3) Pelaksanaan audit mutu internal pada tahun 2019/2020, dengan hasil mencapai standar dikti. Pelaksanaan AMI 2020/2021 memperoleh hasil Melampaui Standar Dikti.\nPerlu konfirmasi dokumen Laporan AMI.\n4) Belum ada informasi dokumen RTM.', 10), (24365, 146, 69, 3.00, 1.00, 3.00, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'UPPS memiliki dokumen sistem penjaminan mutu, menakup SK Ketua UPPSTahun 2019 tentang Penetapan Kebijakan Sistem Penjaminan Mutu Internal (SPMI); SK Ketua UPPSTahun 2020 tentang Penetapan Standar Nasional Pendidikan Tinggi UPPS; SK Ketua UPPSTahun 2019 tentang Penetapan Manual Sistem Penjaminan Mutu Internal dan SK Ketua UPPSTahun 2020 tentang Penetapan Buku Formulir SPMI. Sistem penjaminan mutu mengalami peningkatan dengan meningkatkan status hasil AMI menjadi melampaui standar dikti. PS memiliki pengakuan mutu dari lembaga akreditasi BAN PT, telah terakreditasi C.', 10), (24366, 146, 70, 2.50, 2.00, 5.00, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Keterlaksanan SPMI memenuhi aspek :\n1) tersedianya SN DIKTI  untuk seluruh standar pada SN DIKTI (24 standar pendidikan) mencakup IKU dan IKT pada kriteria tata pamong, mahasiswa, SDM, keuangan sapras, pendidikan, penelitian, PkM dan Luaran & capaian tridarma PT.\n2) Terlaksananya siklus penjaminan mutu (siklus PPEPP) , didkung kegiatan audit mutu internal dengan tanggal audt 9/12/2021. \nPerlu konfirmasi dokumen bukti terlaksannya siklus PPEPP.\n3) Bukti shahih efektivitas pelaksanaan penjaminan mutu, antara lain implementasi sistem penjaminan mutu pada standar kemahasiswaan dengan bikti dokumen standar non akademik, berita acara rapat kerja dengan peningkatan standar kemahasiswaan.\n4) Belum tersedia informasi peningkatan standar.\n', 10), (24367, 146, 71, 1.50, 1.00, 1.50, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Pada LED hal 150, ada informasi UPPS melakukan survey kepuasan pengguna terhadap layanan manajemen terhadap para pemangku kepentingan, layanan pengelolaan dan pengembangan SDM, layanan pengelolaan keuangan dan fasilitas, layanan dan pelaksanaan proses pendidikan, layanan dan pelaksanaan proses penelitian, layanan dan pelaksanaan PkM dan Kepuasan pengguna lulusan dan mitra kerja terhadap kinerja lulusan dengan metode kuisioner secara langsung pada saat akhir semester. \nBelum ada informasi hasil pengukuran kepuasan, tindak lanjut, review hasil pengukuran dan publikasinya.', 10), (24368, 146, 72, 1.50, 2.00, 3.00, '2022-06-13 22:24:10', '2022-06-13 22:24:10', '1) UPPS melakukan analisis SWOT dengan mengidentifikasi kekuatan, kelemahan dan ancaman.\nBelum ada identifikasi peluang.\n2) Belum ada informasi analisis yang dilakukan terkait dengan hasil analisis capaian kinerja.\n3) Tersedia rumusan strategi pengembangan (12 strategi), namun perlu didukung data dan penetepan tahap sesuai prioritas pengembangan.\n4) UPPS telah merumuskan program pengembangan berkelanjutan, mencakup program peningkatan pengetahuan VMTS, peningkatan kualitas pembelajaran, peningkatan mutu lulusan, peningkatan kerjasama dan promosi, peningkatan penelitian dan PkM.', 11), (24369, 146, 73, 1.50, 1.50, 2.25, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'Belum ada informasi prioritas program pengembangan, namun ada informasi stratego pengembangan PS TM sebanyak 12 strategi. Penetapan strategi antara lain memperhatikan SDM, ketersediaan sapras dan daya saing global untuk publikasi karya ilmiah.', 11), (24370, 146, 74, 2.00, 2.50, 5.00, '2022-06-13 22:24:10', '2022-06-13 22:24:10', 'UPPS memiliki kebijakan dalam mengatur SDM dan Sapras, kemampuan melaksanakan ditunjukkan dengan keberadaan SOP. Penjaminan mutu berkelanjutan dengan audit internal, namun perlu konfirmasi  bukti pendukung.', 11);
COMMIT;

-- ----------------------------
-- Table structure for rincian_butir_penilaian_ak_prodi_baru
-- ----------------------------
DROP TABLE IF EXISTS `rincian_butir_penilaian_ak_prodi_baru`;
CREATE TABLE `rincian_butir_penilaian_ak_prodi_baru`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `laporan_ak_id` bigint(20) UNSIGNED NOT NULL,
  `nomor_butir` smallint(5) UNSIGNED NOT NULL,
  `skor_butir` decimal(5, 2) NOT NULL,
  `bobot_butir` decimal(5, 2) NOT NULL,
  `skor_akhir_butir` decimal(5, 2) NOT NULL,
  `deskripsi_butir` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `kriteria_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `rincian_butir_penilaian_ak_prodi_baru_laporan_ak_id_foreign`(`laporan_ak_id` ASC) USING BTREE,
  INDEX `rincian_butir_penilaian_ak_prodi_baru_kriteria_id_foreign`(`kriteria_id` ASC) USING BTREE,
  CONSTRAINT `rincian_butir_penilaian_ak_prodi_baru_kriteria_id_foreign` FOREIGN KEY (`kriteria_id`) REFERENCES `kriteria_butir_penilaian_prodi_baru` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `rincian_butir_penilaian_ak_prodi_baru_laporan_ak_id_foreign` FOREIGN KEY (`laporan_ak_id`) REFERENCES `laporan_ak_prodi_baru` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 2865 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- ----------------------------
-- Records of rincian_butir_penilaian_ak_prodi_baru
-- ----------------------------
BEGIN;
INSERT INTO `rincian_butir_penilaian_ak_prodi_baru` (`id`, `laporan_ak_id`, `nomor_butir`, `skor_butir`, `bobot_butir`, `skor_akhir_butir`, `deskripsi_butir`, `kriteria_id`, `created_at`, `updated_at`) VALUES (2145, 82, 1, 3.00, 4.00, 12.00, 'Prdi TK Ubeo brfokus pada pengolahan biomassa dari pertanian, kelautan, dan biosains tropika.\r\nPerbandingan dengan Prodi Sejenis: Dibandingkan dengan ITB, UGM, dan UI, Ubeo lebih menekankan pada Teknik Pangan dan Bioproses. Pengembangan Keilmuan sudah terintegrasi dalam bidang Teknik Pangan, Teknik Bioproses, dan teknologi pendukung seperti IoT dan AI. Kajian CPL mengacu pada KKNI, IABEE, dan Permendikbud 53/2023, dengan penekanan pada pengembangan keterampilan teknis dan non-teknis. Kurikulum prodi yang diusulakn berbeda karena berfokus pada bahan terbarukan, sementara ITB, UGM, dan UI lebih menekankan bahan fosil. Beberapa perbandingan ini tidak terlalu tepat namun sudah dilakukan. ', 1, '2025-03-21 11:09:29', '2025-03-21 11:09:29'), (2146, 82, 2, 4.00, 3.00, 12.00, 'UPPS telah menguraikan profil lulusan berupa profesi atau jenis pekerjaan atau bentuk kerja lainnya dilengkapi dengan (1) uraian ringkas seluruh profil, yang sesuai dengan program pendidikannya dan (2) keterkaitan profil dengan keunikan atau keunggulan prodi. Ada 4 profil lulusan yaitu sebagai: Perekayasa (Engineer) di perusahaan manufaktur yang mampu merancang proses dan pengembangan produk di industri terkait dengan pangan, pertanian, farmasi, dan energi; Konsultan teknik kimia yang memberikan saran dalam pengembangan produk, memecahkan masalah teknis, dan meningkatkan efisiensi operasional; Akademisi yang bekerja sebagai asisten pengajar di perguruan tinggi atau pengajar di sekolah menengah atas/kejuruan bidang teknik proses kimia; dan sebagai Wirausahawan yang mengembangkan usaha mandiri di bidang manufaktur kecil, konsultan independen, atau startup teknologi terkait Teknik Kimia.\r\nKeterkaitan Profil dengan Keunikan atau Keunggulan Prodi: Lulusan  dirancang untuk memiliki keahlian dalam mengembangkan dan mengoptimalkan proses produksi di sektor pertanian, kelautan, dan biosains tropika. Ini sesuai dengan kekhasan Program Studi Teknik Kimia Ubeo yang menekankan peminatan pada Teknik Pangan dan Teknik Bioproses​', 1, '2025-03-21 11:09:29', '2025-03-21 11:09:29'), (2147, 82, 3, 4.00, 8.00, 32.00, 'Rumusan capaian pembelajaran lulusan (CPL) disusun untuk memenuhi kemampuan profesional yang dibutuhkan oleh profil lulusan seperti Perekayasa (Engineer), Konsultan Teknik Kimia, Akademisi, dan Wirausahawan. CPL dirumuskan dengan mengacu pada kompetensi yang dibutuhkan dalam perancangan, pengembangan, pengelolaan, dan evaluasi proses produksi di sektor pangan, pertanian, farmasi, energi, dan industri lainnya. \r\nKompetensi yang diuraikan sudah sesuai SN-Dikti yang mencakup 4 domain capaian pembelajaran dan sesuai level 6 KKNI yaitu: Sikap: CPL #1 dan CPL #2 terkait dengan nilai-nilai moral, etika, kerja sama tim, profesionalisme, dll. Pengetahuan: CPL #3, CPL #4, dan CPL #5 mengacu pada penerapan prinsip-prinsip Teknik Kimia, desain produk, proses, dan sistem yang kompleks. Keterampilan Khusus: CPL #9 dan CPL #10 menekankan pada kemampuan berpikir kritis, menganalisis masalah, dan membuat keputusan yang tepat. Keterampilan Umum: CPL #6, CPL #7, dan CPL #8 berkaitan dengan perencanaan, pengembangan, evaluasi proses, serta penggunaan perangkat lunak teknis.\r\nSesuai Level 6 KKNI: Dirumuskan berdasarkan Permendikbud No. 53 Tahun 2023 dan mengacu pada standar IABEE dan KKNI yang merujuk pada level 6 (sarjana).\r\nKeunikan Prodi Teknik Kimia Ubeo terkait dengan kajian pemanfaatan dan pengolahan biomassa dari sektor pertanian, kelautan, dan biosains tropika sangat terintegrasi dalam CPL yang dirancang.\r\nCPL khususnya menekankan pada kemampuan merancang, mengembangkan, mengoptimasi, mengendalikan, mengevaluasi, dan memperbaiki proses produksi yang berbasis agromaritim.\r\nBeberapa capaian pembelajaran lulusan (CPL) secara eksplisit mengacu pada Permendikbud No. 53 Tahun 2023 yang merupakan bagian dari standar pendidikan nasional (SN-Dikti)\r\n', 1, '2025-03-21 11:09:29', '2025-03-21 11:09:29'), (2148, 82, 4, 3.00, 15.00, 45.00, 'Dokumen LED UPPS menyajikan struktur kurikulum dengan MK wajib yang mencakup: Agama (3 sks); Pancasila (1 sks); Pendidikan Kewarganegaraan (1 sks) dan Bahasa Indonesia (2 sks) yang terdapat pada semester awal (Semester 1 dan 2) yang menunjukkan kesesuaian dengan ketentuan umum mengenai mata kuliah wajib.\nSetiap mata kuliah yang disusun dalam kurikulum memiliki keterkaitan langsung dengan Capaian Pembelajaran Lulusan (CPL) yang dirumuskan. Sebagai contoh:MK Neraca Massa dan Energi dan Termodinamika Teknik Kimia mendukung CPL terkait perancangan proses, analisis data, dan pengelolaan sistem teknik kimia yang kompleks (CPL 3 - 5); MK Perancangan Proses dan Simulasi Proses & Optimasi Proses berkaitan dengan kemampuan mengembangkan dan mengelola proses produksi di bidang agromaritim (CPL 6 - 9).\nUrutan MK telah terlihat logis dan terstruktur dengan MK dasar di awal perkuliahan, diikuti dengan mata kuliah yang lebih spesifik terkait dengan peminatan (Teknik Bioproses atau Teknik Pangan). \nTotal SKS yang perlu diselesaikan adalah 144 SKS, yang dibagi secara proporsional pada setiap semester dengan rata-rata beban per semester adalah 18 SKS, (wajar dan sesuai dengan SN-Dikti).\n\nRekomendasi:\n1. Meskipun sudah ada peminatan khusus pada Teknik Bioproses dan Teknik Pangan, perlu diperkuat kurikulum yang membahas reaksi kimia, proses kimia, perpindahan massa, perpindahan panas, dan rekayasa produk kimia.\n2. Apakah seluruh capaian pemblajaran yang diatur oleh APTEKIM sudah sepenuhnya terintegrasi dalam kurikulum?', 1, '2025-03-21 11:09:29', '2025-03-21 11:09:29'), (2149, 82, 5, 3.50, 9.00, 31.50, 'Semua sembilan komponen RPS telah terpenuhi dengan baik dalam LED ini. Sebagian besar referensi yang digunakan cukup mutakhir, terutama yang berasal dari artikel ilmiah dan publikasi terbaru di bidang bioproses dan pangan. Terdapat beberapa referensi klasik yang sudah agak lama, khususnya untuk mata kuliah dasar. Saran: walaupun relevansi ilmiah buku-buku ini masih kuat, sebaiknya ditambah dengan artikel ilmiah terbaru yang terkait dengan aplikasi terkini.\nSelain itu penyusunan RPS (Rencana Pembelajaran Semester) perlu memperhatikan apakah materi yang diajarkan oleh setiap dosen sudah sesuai dengan kompetensinya.', 1, '2025-03-21 11:09:29', '2025-03-21 11:09:29'), (2150, 82, 6, 3.50, 1.00, 3.50, 'Kebijakan Dosen Pembimbing Akademik (DPA) disediakan untuk setiap mahasiswa dan bertugas memantau serta memberikan arahan terhadap proses belajar mahasiswa, khususnya yang mengambil kegiatan di luar program studi utama. POB Pembentukan Dosen Penggerak (Dosen Wali) sudah tersedia dalam dokumen untuk mendukung pelaksanaan MBKM.\nKurikulum dirancang agar memungkinkan mahasiswa mengambil pembelajaran di luar Prodi mencakup pertukaran pelajar, magang, kewirausahaan, proyek independen, pengabdian masyarakat, dan penelitian, dengan memungkinkan mahasiswa mengambil minimal 10 SKS per semester di luar program studi.\nRekomendasi: Perlu diintegrasikan lebih lanjut sistem monitoring kemajuan mahasiswa selama mengikuti program MBKM agar lebih terpantau dengan baik.', 1, '2025-03-21 11:09:29', '2025-03-21 11:09:29'), (2151, 82, 7, 3.50, 32.73, 114.55, 'Persyaratan calon dosen tetap sebanyak 5 orang sudah terpenuhi, bahkan terdapat 6 calon dosen tetap dengan kualifikasi yang sangat relevan dengan bidang ilmu Teknik Kimia. Kualifikasi akademik sudah mencakup lulusan magister dan doktor yang relevan (level 8 dan 9 KKNI).  Status PNS atau CASN sudah dimiliki oleh para dosen yang terdaftar.\nSaran & Rekomendasi:\n1. Penguatan Dosen yang Berbasis Teknik Kimia Murni:\nAgar program studi ini memiliki fondasi yang kuat dalam bidang Teknik Kimia, perlu diupayakan perekrutan lebih banyak dosen yang memiliki latar belakang Sarjana, Magister, dan Doktor dalam Teknik Kimia murni.Hal ini penting untuk menjaga konsistensi dan kualitas pendidikan Teknik Kimia yang sesuai dengan standar nasional dan internasional.\n2. Rekrutmen Dosen dari Bidang Teknik Kimia yang Relevan dengan Agromaritim:\nPerekrutan dosen yang memiliki spesialisasi di bidang Teknik Kimia yang terkait dengan pengolahan biomassa, proses biokimia, energi terbarukan, atau teknologi pangan yang berbasis kimia, akan lebih mendukung keunikan program studi ini.\n3. Kolaborasi Interdisipliner:\nMeski sebagian besar dosen tidak berasal dari Teknik Kimia murni, mereka tetap dapat memberikan kontribusi dalam bidang Teknik Bioproses atau Teknik Pangan. Namun disarankan dibentuk tim pengajar yang sinergis untuk memastikan penguasaan keilmuan Teknik Kimia tetap dominan, sementara integrasi dengan bidang lain dapat menjadi nilai tambah.\n4. Evaluasi Kesesuaian Pengajaran:\nPengelola program studi perlu memastikan bahwa setiap dosen mengajar sesuai dengan kompetensi utama yang mereka kuasai.\no	\n', 2, '2025-03-21 11:09:29', '2025-03-21 11:09:29'), (2152, 82, 8, 3.00, 2.27, 6.82, 'Telh terdapat penjelasan mengenai struktur organisasi UPPS (sekolah teknik Ubeo) pada bagian kriteria 3. unit pengelola program studi (halaman 21 - 28). \r\n5 unsur unit penglola program studi (UPPS) telah terpenuhi. kebijakan ditetapkan oleh dekan dan senat sekolah, dengan landasan aturan dari Ubeo dan peraturan yang relevan.\r\nunsur pelaksana akademik tlah terpenuhi. pelaksanaan akademik dikelola secara trstruktur mulai dari dekan, wakil dekan, hingga ketua program studi.\r\nunsur pengawas dan penjaminan mutu telah terpenuhi. sistem penjaminan mutu terstruktur dengan baik melalui gpm dan gkm yang telah memiliki tugas dan fungsi yang jelas.\r\nunsur penunjang akademik atau sumber belajar telah terpenuhi. infrastruktur pendukung sudah mencakup sistem layanan akademik berbasis digital serta sarana laboratorium dan perpustakaan.\r\nunsur pelaksana administrasi atau tata usaha telah terpenuhi. sistem pengelolaan administratif sudah dibentuk dengan baik di bawah sekolah teknik yang mengacu pada aturan Ubeo.\r\ntata kerja sudah diatur dengan baik melalui sistem yang terstruktur\r\nhierarki hubungan antar unsur di UPPS sudah dijelaskan dengan jelas. \r\nRekomendasi:\r\n1. Perkuat kolaborasi GPM & GKM agar lebih efektif dalam mengintegrasikan hasil evaluasi mutu untuk peningkatan kurikulum dan pembelajaran.\r\n2. Perbaikan sistem digitalisasi dengan meningkatkan integrasi berbagai platform layanan akademik untuk memudahkan monitoring dan pelaporan.\r\n3. Penyempurnaan dokumentasi dengan menyusun buku panduan atau SOP (Standard Operating Procedure) yang lebih spesifik terkait hubungan kerja antar unit di bawah UPPS.', 3, '2025-03-21 11:09:29', '2025-03-21 11:09:29'), (2153, 82, 9, 3.00, 3.18, 9.55, 'Upaya tata kelola/good governance yang baik dalam pengelolaan Prodi telah terlihat. Pemilihan Dekan & Wakil Dekan dilakukan berdasarkan kriteria kompetensi, integritas, dan kemampuan memimpin sesuai dengan Peraturan Rektor Nomor 1/IT3/KP/2017. SPMI dikelola oleh Kantor Manajemen Mutu (KMM) yang memastikan standar yang digunakan dapat dipertanggungjawabkan. \r\nSistem manajemen akademik (SIMAK Ubeo, SIPAKARIL, Repositori Ubeo) memfasilitasi keterbukaan informasi. Keterbukaan pengelolaan melalui sistem informasi digital yang dapat diakses oleh pemangku kepentingan.\r\nPengelolaan Kinerja dilakukan dengan SIMAKER, termasuk pelaporan capaian kinerja setiap semester. Proses audit dan evaluasi yang terstruktur melalui Gugus Penjamin Mutu (GPM) dan Gugus Kendali Mutu (GKM). Penggunaan kontrak kinerja yang dievaluasi secara berkala dan menjadi dasar pengambilan kebijakan.\r\nPengelolaan sumber daya & anggaran, tanggung jawab dalam Tridharma PT dan pengelolaan Prodi sudah mencerminkan mekanisme pelaporan dan pengawasan yang ketat.\r\nPrinsip keadilan terjaga melalui prosedur yang obyektif dan tanpa diskriminasi.\r\nRekomendasi:\r\n1. Peningkatan Integrasi Sistem Digital dengan mengintegrasikan seluruh platform digital (SIMAK, SIMAKER, SIPAKARIL, Repositori Ubeo, dll.) agar lebih mudah diakses dan digunakan oleh dosen, mahasiswa, dan tenaga kependidikan. Apakah sudah ada portal khusus yang mengelola seluruh aspek tata kelola, mulai dari pelaporan akademik hingga monitoring kinerja?\r\n2. Penguatan koordinasi GPM dan GKM dengan mengintegrasikan lebih baik antara hsil evaluasi mutu dgn peningkatan kurikulum & pelaksanaan pembelajaran.\r\n3. Menyusun Prosedur Operasional Baku (POB) yang lebih spesifik terkait hubungan kerja antar unit di bawah UPPS.', 3, '2025-03-21 11:09:29', '2025-03-21 11:09:29'), (2154, 82, 10, 3.00, 9.55, 28.64, 'Seluruh lima aspek SPMI (Penetapan, Pelaksanaan, Evaluasi, Pengendalian, dan Peningkatan) telah tercrmin. \nRekomendasi:\n1. Penguatan koordinasi antara GPM dan GKM dengan membangun integrasi lebih kuat antara kegiatan pengawasan akademik dan non-akademik agar dapat saling mendukung. Mengadakan rapat evaluasi secara rutin dengan melibatkan dosen, mahasiswa, dan tenaga kependidikan. \n2. Peningkatan kompetensi dosen dan TENDIK dengan memberikan pelatihan rutin terkait penjaminan mutu, penggunaan teknologi, dan perbaikan kurikulum, mengingat prodi masih baru dan dosen berasal dari erabagi prodi yang berbeda sebelumnya.', 3, '2025-03-21 11:09:29', '2025-03-21 11:09:29'), (2155, 82, 11, 4.00, 3.47, 13.88, 'Jumlah Ruang Kuliah: Terdapat 4 ruang kuliah utama yang digunakan untuk perkuliahan teori.\nLuas Ruang: Setiap ruang memiliki luas rata-rata 75 m2, yang berarti dapat menampung hingga 50 mahasiswa per sesi kuliah dengan standar 1.5 m2 per mahasiswa.\nFasilitas: Dilengkapi dengan proyektor, whiteboard, AC, dan jaringan internet (Wi-Fi) yang berfungsi dengan baik.\nKondisi & Penggunaan: Sudah memadai untuk mendukung proses pembelajaran dengan jumlah mahasiswa yang ada.\nRuang kuliah telah memenuhi standar luas per mahasiswa dan dilengkapi dengan fasilitas pendukung yang baik.', 3, '2025-03-21 11:09:29', '2025-03-21 11:09:29'), (2156, 82, 12, 3.00, 2.60, 7.80, 'Sudah terdapat ruang akademik khusus yang disediakan untuk setiap jenis kegiatan praktikum yang berbeda. Setiap laboratorium memiliki luas yang mencukupi (> 1.5 m2 per mahasiswa) dan merupakan milik sendiri.Kelengkapan peralatan sesuai dengan kebutuhan kurikulum.  Perlu dilihat saat visitasi. \nSaran:\n1. Perlu ada pembaruan peralatan tertentu agar lebih relevan dengan perkembangan teknologi secara periodik, khususnya yang terkait dengan simulasi proses kimia, bioproses, dan pengolahan pangan.\n2. Optimalisasi penggunaan ruang dengan menggunakan sistem manajemen laboratorium yang lebih efektif agar pemanfaatan ruang dapat lebih optimal sertta mengintegrasikan laboratorium yang memiliki fungsi serupa agar dapat digunakan lebih efisien.', 3, '2025-03-21 11:09:29', '2025-03-21 11:09:29'), (2157, 82, 13, 3.50, 3.47, 12.15, 'Untuk dua tahun pertama, peralatan yang tersedia sudah mencukupi untuk mendukung praktikum dasar dan praktikum terapan yang sesuai dengan kurikulum yang ditetapkan.\nPengadaan peralatan telah memperhitungkan standar minimal (>1.5 m2 per mahasiswa, 25 orang mahasiswa per ruang).\nStatus kepemilikan peralatan adalah milik sendiri, dan peralatan tersebut sudah sesuai dengan standar nasional dan internasional (IABEE, SN-Dikti).\n5. Kelengkapan Peralatan:\nPeralatan untuk praktikum dasar dan lanjutan telah disiapkan dengan baik.\nBeberapa peralatan mutakhir sudah tersedia untuk menunjang proses praktikum yang lebih modern, khususnya di bidang bioproses dan teknologi pangan.\nPeralatan yang digunakan telah melalui proses pengadaan dan pemeliharaan yang teratur, meskipun perlu ada pembaruan untuk alat-alat tertentu yang sudah mulai usang.\nRkomendasi:\n1. Pngganti atau memperbaiki peralatan yang mulai mengalami penurunan kualitas atau sudah ketinggalan zaman.\nPengadaan alat-alat baru yang lebih mutakhir sesuai dengan perkembangan industri terkini, terutama yang terkait dengan simulasi proses, pengolahan pangan, dan bioproses.\n2. Memastikan bahwa setiap peralatan yang disediakan relevan dengan capaian pembelajaran yang ingin dicapai. Mengadakan evaluasi peralatan setiap tahun untuk menyesuaikan dengan perubahan kurikulum atau perkembangan teknologi.\n3. Memberikan pelatihan kepada mahasiswa untuk mengoptimalkan penggunaan peralatan yang lebih kompleks. Menyediakan panduan penggunaan peralatan secara digital agar lebih mudah diakses oleh mahasiswa dan dosen.', 3, '2025-03-21 11:09:29', '2025-03-21 11:09:29'), (2158, 82, 14, 3.50, 2.73, 9.55, 'Meskipun telah memenuhi syarat minimal, jumlah tenaga kependidikan yang tersedia mungkin belum cukup optimal untuk mendukung kegiatan program studi yang berkembang pesat. Beban kerja tenaga kependidikan dapat menjadi lebih berat jika program studi mengembangkan lebih banyak kegiatan praktikum, penelitian, dan kegiatan MBKM (Merdeka Belajar - Kampus Merdeka).\nRekomendasi:\n1. Menambah minimal 1 orang tenaga kependidikan tambahan yang memiliki spesialisasi dalam manajemen laboratorium atau administrasi akademik untuk membantu pengelolaan praktikum dan pengelolaan MBKM.\n2. Berikan pelatihan rutin untuk meningkatkan kompetensi dalam penggunaan sistem informasi akademik, manajemen laboratorium, dan pelayanan administrasi. Menyediakan kesempatan bagi tenaga kependidikan untuk mengikuti pelatihan digitalisasi, layanan perpustakaan modern, dan pengelolaan program MBKM.\n3. Mlakukan evaluasi rutin trhadap beban kerja tenaga kependidikan agar tidak melebihi kapasitas yang ideal. ', 3, '2025-03-21 11:09:29', '2025-03-21 11:09:29'), (2173, 84, 1, 3.50, 4.00, 14.00, 'PSTK Ubeo telah menjelaskan keunikannya dbandingkan dengan prodi sejenis seperti Teknik Kimia ITB, Teknik Kimia UI dan Teknik Kimia UGM  dengan relevansi yang besar terhadap pengembangan pertanian, kelautan, dan biosains tropika karena kontribusinya dalam memperbaiki proses produksi, meningkatkan kualitas produk, dan menjaga keberlanjutan lingkungan dalam sektor-sektor tersebut. PSTK Ubeo menekankan peminatan pada bidang Teknik Pangan dan Teknik Bioproses karena kedua bidang ini sangat berkaitan erat dengan pertanian, kelautan dan biosains tropika.Terkait keunikan yang lebih detail akan didiskusiksan saat AL', 1, '2025-03-28 19:03:10', '2025-03-28 19:03:10'), (2174, 84, 2, 3.75, 3.00, 11.25, 'Profil lulusan PSTK Ubeo difokuskan pada 4 profil yang mencakup: 1) Perekayasa (engineer) di perusahaan manufaktur: yang memiliki kemampuan untuk merancang proses dan pengembangan produk di industri yang terkait dengan pangan, pertanian, farmasi dan energi, 2) Konsultan teknik kimia yang bekerja di perusahaan konsultan untuk meningkatkan efisiensi operasional, memecahkan masalah teknis, dan memberikan saran dalam pengembangan produk, 3) Akademisi sebagai asisten pengajar di perguruan tinggi atau pengajar di Sekolah Menengah Atas/kejuruan bidang teknik proses kimia dan 4 Wirausahawan yang mampu mengembangkan usaha secara mandiri (perusahaan manufaktur kecil, konsultan independen, atau startup teknologi yang inovatif di bidang penerapan Teknik Kimia). ', 1, '2025-03-28 19:03:10', '2025-03-28 19:03:10'), (2175, 84, 3, 3.50, 8.00, 28.00, 'Rumusan Capaian Pembelajaran Lulusan (CPL) PSTK Ubeo sudah sesuai dengan profil lulusan  degan 10 rumusan Capaian Pembelajaran Lulusan (CPL) dari PSTK yang mencakup aspek sikap, pengetahuan, keterampilan khusus dan keterampilan umum dengan penyusunan CPL mengacu pada Permendikbud No. 53 Tahun 2023 tentang Penjaminan Mutu Pendidikan, deskripsi level 6 (enam) dalam Kerangka Kualifikasi Nasional Indonesia (KKNI) sesuai Perpres Nomor 8 Tahun 2012, dan standar pendidikan keteknikan dari Indonesian Accreditation Board for Engineering Education (IABEE). ', 1, '2025-03-28 19:03:10', '2025-03-28 19:03:10'), (2176, 84, 4, 3.50, 15.00, 52.50, 'PSTK Ubeo memiliki total 144 sks dengan komposisi matakuliah dalam kurikulum merujuk pada kriteria akreditasi LAM-Teknik dan IABEE meliputi aspek: (i) Ilmu dasar (Matematika dan ilmu pengetahuan alam spesifik dengan disiplin ilmu) minimal 20%, (ii) ilmu keteknikan minimal sebesar 40%, dan (iii) Pendidikan umum meliputi moralitas, etika, sosio-budaya, lingkungan, dan manajemen, maksimal sebesar 30%. Kurikulum Program Studi Teknik Kimia dirancang untuk memenuhi persyaratan tersebut, yaitu (a) Mata Kuliah Pengetahuan Umum (18,1%); (b) Mata Kuliah Dasar (22,2%), dan (3) Mata kuliah bidang ilmu ketek-nikan (53,5%.) Kurikulum yang dikembangkan juga benchmarking dengan kurikulum program studi di universitas lain dalam (ITB, UI, UGM), dan luar negeri (UPM, NUS, dan CU).', 1, '2025-03-28 19:03:10', '2025-03-28 19:03:10'), (2177, 84, 5, 3.50, 9.00, 31.50, 'PSTK Ubeo telah memiliki Rencana Pembelajaran Semester (RPS) sebagai contoh sebanyak 10 RPS dengan peminatan Teknik Pangan dan Teknik Bioproses yang disimpan dalam https://ubeo.link/rps-teknik-kimia. RPS dirancang untuk memandu proses pembelajaran di setiap mata kuliah dalam PSTK. RPS pada setiap mata kuliah mencakup nama program studi, nama dan kode mata kuliah, semester, jumlah sks, serta nama dosen pengampu. RPS memuat capaian pembelajaran lulusan yang dibebankan pada mata kuliah, kemampuan akhir yang diharapkan pada setiap tahap pembelajaran untuk mencapai capaian pembelajaran lulusan, serta bahan kajian yang terkait dengan kemampuan yang akan dicapai. RPS juga mencantumkan metode pembelajaran, waktu yang disediakan untuk mencapai kemampuan pada tiap tahap pembelajaran, serta pengalaman belajar mahasiswa yang dijabarkan dalam deskripsi tugas yang harus dikerjakan mahasiswa selama satu semester. Kriteria, indikator, dan bobot penilaian juga dijelaskan dalam RPS, serta daftar referensi yang digunakan. Diskusi saat AL', 1, '2025-03-28 19:03:10', '2025-03-28 19:03:10'), (2178, 84, 6, 3.00, 1.00, 3.00, 'PSTK telah menuangkan terkait Kebijakan Merdeka Belajar Kampus Merdeka  (MBKM) dalam kurikulum untuk memfasilitasi kebijakan dan implementasi MBKM bagi mahasiswa yang melakukan pembelajaran di luar program studi. Rancangan MBKM merujuk pada Panduan Pengelolaan MBKM di Ubeo dengan total alokasi waktu yang setara dengan minimal 10 sks per semester yang dapat dilaksanakan pada semester 5 s/d 8. Kegiatan MBKM dapat berupa keikutsertaan dalam program pertukaran mahasiswa atau dalam bentuk aktivitas lain dalam kanal MBKM, sesuai minat mahasiswa. Kegiatan MBKM dalam bentuk aktivitas di luar kampus yang dapat dikonversi ke dalam mata kuliah pengayaan kode Ubeo setelah melalui proses penilaian yang sesuai dengan capaian pembelajaran. Diskusi saat AL. ', 1, '2025-03-28 19:03:10', '2025-03-28 19:03:10'), (2179, 84, 7, 3.50, 32.73, 114.55, 'PSTK memiliki enam (6) orang dosen dengan latar belakang pendidikan yang relevan dengan bidang ilmu teknik kimia, yaitu 5 orang berpendidikan doktor dan 1 orang berpendidikan Magister. Sebanyak dua (2) orang memiliki Jabatan Akademik Guru Besar, dua orang memiliki Jabatan Akademik Lektor Kepala, dan dua orang lainnya berstatus CASN. PSTK perlu melakukan rekruitmen dosen baru yang memiliki kompetensi bidang Bioproses/Bioteknologi yang sesuai dengan rencana pengembangan PSTK. ', 2, '2025-03-28 19:03:10', '2025-03-28 19:03:10'), (2180, 84, 8, 3.00, 2.27, 6.82, 'PSTK Ubeo secara struktur berada di bawah Sekolah Teknik Universitas Borneo (Ubeo) sebagai Unit Pengelola Program Studi (UPPS). Pendirian Sekolah Teknik Ubeo sendiri ditetapkan berdasarkan Surat Keputusan Senat Akademik Ubeo Nomor 03 Tahun 2024 dan Surat Kepu-tusan Rektor Nomor 92 Tahun 2024. Sesuai Surat Keputusan Senat Akademik Ubeo Nomor 26 Tahun 2024, Sekolah Teknik Ubeo mengelola lima belas (15) program studi multistrata (S1, S2, dan S3) yang sebelumnya di bawah penge-lolaan Fakultas Teknologi Pertanian (Fateta), ditambah dengan dua program studi baru (Teknik Mesin dan Teknik Kimia) berdasarkan Surat Keputusan Senat Akademik Ubeo Nomor 24 Tahun 2025 (untuk Program Studi Teknik Mesin) dan Nomor 25 Tahun 2024 (untuk Program Studi Teknik Kimia). ', 3, '2025-03-28 19:03:10', '2025-03-28 19:03:10'), (2181, 84, 9, 3.00, 3.18, 9.55, 'Perwujudan good governance PSTK Ubeo dengan menerapkan lima pilar tata pamong yang benar yakni meliputi kredibel, transparan, akuntabel, bertanggung jawab, dan adil telah diterapkan di UPPS untuk mewujudkan visi, misi, tujuan dan strategi dari Sekolah Teknik dan program studi yang dikelola di bawahnya yang sejalan dengan penerapan sistem tata pamong yang sesuai dengan SOTK Ubeo. Layanan akademik didukung dengan sistem informasi yang terintegrasi di tingkat Ubeo dan fakultas/sekolah. DIskusi saat AL', 3, '2025-03-28 19:03:10', '2025-03-28 19:03:10'), (2182, 84, 10, 3.00, 9.55, 28.64, 'Penjaminan mutu di Ubeo dijalankan berdasarkan Peraturan Majelis Wali Amanat (MWA) Ubeo Nomor 06/MWA-UBEO/ P/2020 tentang Struktur Organisasi dan Tata Kerja (SOTK) Universitas Borneo (Ubeo) pada Pasal 119, disebutkan bahwa sistem penjaminan mutu internal (SPMI) di tingkat institusi dikoordinasikan oleh Kantor Manajemen Mutu (KMM). KMM bertugas dalam melaksanakan pengembangan sistem penjaminan mutu, peningkatan mutu, dan akuntabilitas penyelenggaraan program dan kegiatan Ubeo, pengembangan sistem dan pelaksanaan pengawasan internal dalam bidang akademik. KMM melaksanakan fungsi (a) pembinaan unit kerja di lingkungan Ubeo terkait dengan penegakan aturan, pencapaian standar mutu dan indikator kinerja dalam penyelenggaraan program dan kegiatan Ubeo; (b) penguatan sistem penjaminan mutu berbasis digital bidang akademik dan non-akademik; (c) pelaksa-naan koordinasi dan penilaian sistem penjaminan mutu, evaluasi standar mutu penyelenggaraan program dan kegiatan Ubeo serta dokumentasi hasil pelaksa-naannya; (d) pelaksanaan koordinasi proses akreditasi dan sertifikasi tingkat nasional maupun internasional pada level institut, fakultas, departemen, program studi dan/atau unit kerja pelaksana administrasi/penunjang. Diskusi saat AL terkait Penjaminan Mutu di Sekolah dan Prodi', 3, '2025-03-28 19:03:10', '2025-03-28 19:03:10'), (2183, 84, 11, 4.00, 3.47, 13.88, 'Keberadaan ruang kuliah, ruang kerja dosen,  ruang kerja pegawai dan perpustakaan di PSTK Ubeo memadai dengan gambaran dan penjelasan yang detail.  ', 3, '2025-03-28 19:03:10', '2025-03-28 19:03:10'), (2184, 84, 12, 3.00, 2.60, 7.80, 'UPPS telah memiliki laboratorium untuk persiapan PSTK seperti Lab. Fisika, Lab Kimia, Lab Komputasi, Lab Mikrobiologi, Lab Instrumen, Lab Pilot Plant, Lab Analisis dan Lab Riset, namun belum diuraikan secara detail terkait rencana Laboratoium Proses dan Laboratorium Unit Operasi dengan modul-modul praktikum apa saja yang menjadi penciri dan pemenuhan kompetensi PSTK. Diskusi saat AL', 3, '2025-03-28 19:03:10', '2025-03-28 19:03:10'), (2185, 84, 13, 3.00, 3.47, 10.41, 'Peralatan praktikum pada tahun pertama yang dimiliki PSTK sudah disiapkan dan menginduk/sharing dengan Program Studi di UPPS,  namun perlu disiapkan secara detail terkait rencana Laboratoium Proses dan Laboratorium Unit Operasi dengan modul-modul praktikum apa saja yang menjadi penciri dan pemenuhan kompetensi Teknik Kimia. Diskusi saat AL ', 3, '2025-03-28 19:03:10', '2025-03-28 19:03:10'), (2186, 84, 14, 3.50, 2.73, 9.55, 'Jumlah dan kualifikasinya tenaga kependidikan di PSTK memadai dengan sudah disiapkan 6 orang tenaga kependidikan bergelar sarjana dan sarjana muda secara khusus sebagai pustakawan, administrasia akademik dan 4 tenaga teknisi dan selebihnya tenaga kependidikan berada di UPPS. Diskusi saat AL.', 3, '2025-03-28 19:03:10', '2025-03-28 19:03:10');
COMMIT;

-- ----------------------------
-- Table structure for rincian_butir_penilaian_al
-- ----------------------------
DROP TABLE IF EXISTS `rincian_butir_penilaian_al`;
CREATE TABLE `rincian_butir_penilaian_al`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `laporan_al_id` bigint(20) UNSIGNED NOT NULL,
  `kriteria_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `nomor_butir` smallint(5) UNSIGNED NOT NULL,
  `skor_butir` decimal(5, 2) NOT NULL,
  `bobot_butir` decimal(5, 2) NOT NULL,
  `skor_akhir_butir` decimal(5, 2) NOT NULL,
  `deskripsi_butir` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `catatan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `rincian_butir_penilaian_al_laporan_al_id_foreign`(`laporan_al_id` ASC) USING BTREE,
  INDEX `rincian_butir_penilaian_al_kriteria_id_foreign`(`kriteria_id` ASC) USING BTREE,
  CONSTRAINT `rincian_butir_penilaian_al_kriteria_id_foreign` FOREIGN KEY (`kriteria_id`) REFERENCES `kriteria_butir_penilaian` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `rincian_butir_penilaian_al_laporan_al_id_foreign` FOREIGN KEY (`laporan_al_id`) REFERENCES `laporan_al` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 166796 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- ----------------------------
-- Records of rincian_butir_penilaian_al
-- ----------------------------
BEGIN;
INSERT INTO `rincian_butir_penilaian_al` (`id`, `laporan_al_id`, `kriteria_id`, `nomor_butir`, `skor_butir`, `bobot_butir`, `skor_akhir_butir`, `deskripsi_butir`, `catatan`, `created_at`, `updated_at`) VALUES (7901, 96, NULL, 1, 3.00, 1.00, 3.00, 'Kondisi Eksternal Program Studi meliputi lingkungan makro dan mikro tingkat lokal, nasional  dan internasional terdiri: lingkungan politik, ekonomi, sosial budaya, teknologi dan persaingan berikut penjelasannya. Program Studi menyesuaikan perkembangan IPTEK di bidang manufaktur. Prodi D3 Teknologi Manufaktur menyesuaikan dengan Kebijakan Pemerintah/Kemenristek Dikti/Dirjen Vokasi. Calon mahasiswa berasal dari daerah Jawa Timur dan lapisan masyarakat. Hasil analisis SWOT dari UPPS yang mencakup kondisi Internal terkait strength (S) dan Weakness (W).  Sedangkan Eksternal terkait Strength (S), Weakness (W), Opportunity (O) dan Threat (T) dan telah diuraikan adanya korelasi antara SO, WO, ST dan WT.  Hasil pengembangan SWOT untuk pengembangan Prodi terutama pada pengembangan kompetensi mahasiswa, peningkatan kerjasama dengan pengguna lulusan, peningkatan keunggulan Prodi, peningkatan promosi Prodi dan optimalisasi pemanfaatan wibesite Prodi. Terdapat dukungan yang kuat dari pihak Universitas dalam pengembangan UPPS dan Prodi.', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7902, 96, NULL, 2, 3.00, 1.00, 3.00, 'UPPS membawahi Program Studi D3 Teknologi Manufaktur, D3 Teknologi Listrik dan D3 Agroindustri.  Visi UPPS: terwujudnya pendidikan Vokasi yang UNGGUL di bidang permesinan konvensional dan otomatis, desain, pengelasan  dan pembuatan mesin tepat guna yang berbasis nilai dan karakter bangsa pada tahun 2035. Implementasi Visi dan Misi Prodi  D3 Teknologi Manufaktur dilaksanakan secara konsisten dan berkelanjutan. Pada tahun 2018, Program Studi memperoleh status akreditasi dari BAN-PT dengan nilai C berdasarkan Surat Keputusan 2246/SK/BAN-PT/Akred/Dipl-III/VIII/2018 tertanggal 15 Agustus 2018. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7903, 96, 1, 3, 3.00, 0.47, 1.41, 'Ada informasi tentang mekanisme penetapan/penyusunan VMTS UPPS yang mengacu pada VMTS UPPS.  Penyusunan VMTS melibatkan civitas akademika antara lain: dosen, mahasiswa, tenaga kependidikan, alumni, Asosiasi Pendidikan Vokasi (FPTVI), Asosiasi Profesi (ASTTI dan PERTAPIN), ATMI Surakarta dan pengguna lulusan, yang bentuk/isi masukannya di rangkum di Tabel 7, LKPT.  Hasil masukan dari pihak yang terlibat adalah bidang manufaktur dan otomatis (CNC), desain, pengelasan dan pembuatan mesin tepat guna, unggul tanpa menghilangkan karakter bangsa. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7904, 96, 1, 4, 3.50, 0.47, 1.65, 'Ada informasi tentang mekanisme penetapan/penyusunan VMTS UPPS yang mengacu pada VMTS UPPS.  Penyusunan VMTS melibatkan civitas akademika antara lain: dosen, mahasiswa, tenaga kependidikan, alumni, Asosiasi Pendidikan Vokasi (FPTVI), Asosiasi Profesi (ASTTI dan PERTAPIN), ATMI Surakarta dan pengguna lulusan, yang bentuk/isi masukannya di rangkum di Tabel 7, LKPT.  Hasil masukan dari pihak yang terlibat adalah bidang manufaktur dan otomatis (CNC), desain, pengelasan dan pembuatan mesin tepat guna, unggul tanpa menghilangkan karakter bangsa. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7905, 96, 1, 5, 3.00, 0.47, 1.41, 'Ada informasi tentang sosialisasi VMTS  untuk meningkatkan pemahaman melalui buku petunjuk pedoman akademik, banner diletakkan di sudut ruangan, diletakkan di dinding yang dapat dilihat oleh mahasiswa, dosen  dan tenaga kependidikan. Sosialisasi juga dilakukan dengan mengundang secara tatap muka dengan dosen, tenaga kependidikan, alumni serta pengguna lulusan untuk menyebarluaskan VMTS Prodi D3 Teknologi Manufaktur. Tingkat kepuasan terhadap pemahaman VMTS menunjukkan hasil sangat baik dan efektif dengan kategori: sangat memahami 80.6 % dan memahami sebesar 19.4 %. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7906, 96, 1, 6, 2.50, 1.42, 3.55, 'Ada strategi pencapaian kepuasan terhadap pemahaman VMTS Prodi D3 Teknologi Manufaktur, yaitu langkah pertama (2019-2024), milestone peringkat 25 secara nasional, periode kedua (2025-2029) milestone peringkat 15 secara nasional dan periode ketiga (2030-2035) milestone peringakt 10 secara nasional. Hal tersebut dituangkan dalam dalam bentuk RENOP dan PROKER 5 tahunan Prodi dan telah dilaksanakan secara konsisten. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7907, 96, 2, 7, 3.00, 0.66, 1.98, 'Tata pemong UPPS Fakultas Vokasi mengacu pada SOP tata kelola dan SOP tata pamong, yang menerapkan 5 pilar, yaitu kredibel (pemilihan pimpinan dan pengelolaan Fakultas), transparansi (semua layanan dapat diakses), akuntabilitas (Audit Mutu Internal), bertanggungjawaB/responsibilitas (kepatuhan pada peraturan internal dan pemerintah) dan keadilan (pemerataan beban kerja dosen dan pengembangan diri) yang dilengkapi dengan penjelasan yang memadai. Tata pamong diterapkan untuk mewujudkan VMTS institusi agar dapat berjalan secara efektif dan efisien. Struktur organisasi ditunjukkan di Gambar 1 (dokumen LED), mulai dari rektor, dekan, ketua program studi, kepala laboratorium hingga laboran dan masing-masing disertai dengan penjelasan tupoksinya. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7908, 96, 2, 8, 3.00, 0.66, 1.98, 'Pelaksanaan kepemimpinan Fakultas Vokasi memiliki bukti sahih terkait penerapan good university government (GUG) 5 pilar (butir 7). Sistem pengelolaan fungsional dan operasional mencakup perencanaan, pengoperasian, penempatan personil, pengarahan dan pengawasan dalam bentuk dokumen RENSTRA dan RENOP. Struktur organsasi Fakultas Vokasi dan Prodi D3 Teknologi Manufaktur ditunjukkan di gambar 4 (dokumen LED) berikut penjelasan yang memadai. Kepemimpinan Prodi mencakup : a. Operasional (tugas, tanggung jawab dan wewenang), b. Organisasi (tanggungjawab mengacu pada struktur organisasi Fakultas Vokasi) dan c. Publik (berkontribusi dengan publik/masyarakat) dan masing-masing berikut ada penjelasannya. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7909, 96, 2, 9, 3.00, 1.32, 3.96, 'Ada pengakuan tentang kerjasama lokal/wilayah pendidikan, yaitu credit transfer system, penelitian (joint research) dan hasil kegiatan pengabdian masyarakat/PkM. Untuk bidang Pendidikan: ada 16 lembaga MITRA kerjasama (4 SMA/SMK dan 11 Perusahaan CV/PT sebagai tempat praktek/magang/beasiswa dan 1 Direktorat Kursus dan Pelatihan Dirjen Pendidikan Vokasi/pelatihan). Manfaatnya adalah dapat peningkatan penerimaan calon mahasiswa baru dan peningkatan jumlah penelitian laboratorium, waktu sekitar 3-4 tahun dan antara tahun 2022-2023. ', 'Sudah Ssesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7910, 96, 2, 10, 3.92, 0.66, 2.59, 'DI Tabel-1, LKPS, total kerjasama ada 30 jenis perusahaan/PT/CV meliputi bidang pendidikan 14 jenis, PkM 12 jenis dan Tri Dharma 4 perusahaan. N1 =  14, N2 = 4 dan N3 = 12', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7911, 96, 2, 11, 2.50, 1.32, 3.30, 'Strategi pencapaian Standar, yaitu dengan cara kerjasama Penelitian dan PKM dengan Lembaga Penelitian dan Pengabdian Masyarakat (LPPM) setiap semester yang dibiayai oleh Hibah Kemenristek Dikti yang melibatkan dosen dan tenaga kependidikan. Indikator Tambahan  mengacu pada RENSTRA Fakultas Vokasi Vokasi ada 3 target, yaitu pengakuan dosen tetap (DT) Prodi, dosen kualitas S1 dan S2 dan rasio antara tenaga kependidikan dan jumlah mahasiswa.           ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7912, 96, 2, 12, 2.70, 1.99, 5.37, 'Hasil capaian kinerja UPPS antara lain: rasio dosen terhadap mahasiswa sekitar 1: 8, dosen memiliki kompetensi 100 %, dosen yang tersertifikasi 71 %,. Dosen tetap Prodi sedang  dalam penyelesaian studi S3. Untuk tenaga kependidikan ada yang S1 dan ada 3 orang S3.', 'Perbaikan penjelasan dosen yang terkait dengan studi lanjut ke S3..', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7913, 96, 3, 13, 2.67, 3.31, 8.83, 'Metoda penerimaan calon mahasiswa baru/rekrutmen di Universitas Garuda dengan menggunakan tes kognitif, tes aptitude, tes potensial akademik, tes buta warna. Hal ini dilakukan untuk mendapatkan calon mahasiswa baru yang berkualitas. Cara mendaftar dilakukan secara on-line yang dapat diakses dari mana saja atau dapat melalui wibesite Fakultas Vokasi. Kuliah dilaksanakan dengan metoda on-line atau sistem hibrid selama masa pandemi Covid-19. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7914, 96, 3, 14, 3.50, 3.31, 11.59, 'Untuk kegiatan akademik, pelayanan dalam PBM: disediakan materi ajar, kisi2, contoh soal, bahan ETS dan bahan EAS. Untuk non akademik berupa Bimbingan dan Konseling: meningkatkan minat dan bakat. Ada program kreativitas mahasiswa. Kegiatan ekstra kurikuler berupa minat/kajian Teknologi Manufaktur (Tabel 16, ada 12 jenis prestasi yang sudah dicapai, LKPT). Fasilitas lainnya berupa beasiswa dari internal, beasiswa mahasiswa berprestasi, beasiswa dari luar PT dan beasiswa CSR kerjasama dengan industri.  Ada mata kuliah kewirausahaan dan tersedia pelatihan dengan inkubasi bisnis yang didampingi oleh Lembaga Inovasi dan Kewirausahaan. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7915, 96, 4, 15, 2.39, 0.47, 1.12, 'Data DTPS ada 7 orang dan 1 orang dosen Praktisi. Dari 7 orang, 6 orang S2 dan 1 orang S3 (Tabel 19, Profil pendidikan DTPS Teknologi Manufaktur, LKPS).  Rasio antara dosen : mahasiswa sekitar 1 : 8. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7916, 96, 4, 16, 2.00, 0.76, 1.52, 'Tabel 3.a.1, LKPT: Dosen Tetap dengan gelar S3  = 0 dan Dosen Tetap Prodi S2 ada 7 orang dengan keahlian di bidang Teknik Mesin ada 5 orang dan keahlian di bidang Teknik Elektro ada 2 orang. Jabatan akademik Lektor ada 5 orang dan jabatan Asisten Ahli ada 2 orang. Keahlian dosen tetap sesuai dengan kompetensi Prodi D3 Teknologi Manufaktur.', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7917, 96, 4, 17, 4.00, 0.47, 1.88, 'Jumlah DTPS yang memiliki sertifikat kompetensi atau NDSK 5 orang dan jumlah dosen tetsp Prodi D3 Teknilogi Manufaktur atau NDTPS 7 orang.', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7918, 96, 4, 18, 4.00, 0.38, 1.52, 'Dosen tetap di PS D3 Teknologi Manufaktur total 7 orang: S2 ada 5 orang jabatan Lektor dan 2 orang jabatan Asisten Ahli (Tabel 3a.1, LKPS). Dosen Jabatan Guru Besar = 0.', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7919, 96, 4, 19, 3.26, 0.28, 0.91, 'Jumlah mahasiswa Nm = 57 orang dan jumlah dosen tetap prodi NDTPS = 7 orang (Tabel 3.a.1, LKPS). ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7920, 96, 4, 20, 4.00, 0.66, 2.64, 'Jumlah mahasiswa pasa saat TS 57 orang dan jumlah dosen tetap Prodi yang mengampu mata kuliah 7 orang (Tabel 3a.1). ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7921, 96, 4, 21, 4.00, 0.19, 0.76, 'Jumlah DTPS yang membimbing 6 orang, jumlah total sks per semester 84.5 atau rata2 EWMP setiap dosen per semester sekitar 14 sks. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7922, 96, 4, 22, 3.38, 0.28, 0.95, 'Jumlah dosen tidak tetap atau DTT Prodi = 1 orang (Tabel 3a.3, LKPS) dan dosen tetap Prodi atau DTPS = 7 orang, Dosen tetap sesuai kompetensi / keahlian = 7 orang.', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7923, 96, 4, 23, 4.00, 0.09, 0.36, 'Ada 1 orang dosen dari Industri/Praktisi (Managemen Konstruksi Utama) dengan bidang keahlian Managemen Industri dakn K3. Mata kuliah yang diajarkan adalah: 1. Managemen Mutu, 2. Managemen Produksi dan 3. K3. Total SKS 10 per semester. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7924, 96, 4, 24, 4.00, 0.66, 2.64, 'Di Tabel 3.b.1  Ada 11 dosen yang mendapat PENGAKUAN dengan keahlian: ISO, desain, mekanikal, pendamping SMKPK dan MBKM di tingkat wilayah (1 orang) dan tingkat nasional (10 orang) dari tahun 20017 hingga tahun 2021.  Sebagai pengakuan/rekognisi : nara sumber, viciting lecture, keynote speaker dan penghargaan.', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7925, 96, 4, 25, 2.41, 0.66, 1.59, 'Dari tahun TS-2 hingga TS (3 tahun): jumlah penelitian mandiri/PT ada 20, penelitian dalam negeri ada 2 dan TIDAK ada penelitian dengan pihak  Luar negeri (Tabel 3b.2, LKPS). ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7926, 96, 4, 26, 1.20, 0.28, 0.33, 'Dari TS-2 hingga TS, jumlah penelitian Perguruan Tinggi dan Mandiri ada 8, pembiayaan Dalam Negeri ada 2 dan TIDAK ada pembiayaan dari Luar Negeri. Total penelitian ada 9 jenis (Tabel 3b.3, LKPT).  ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7927, 96, 4, 27, 4.00, 0.66, 2.64, 'Dari tahun TS-2 hingga TS (3 tahun): publikasi di jurnal nasional tidak terakreditasi = 4, publikasi di jurnal nasional terakreditasi = 7, publikasi di jurnal internasional= 4, publikasi di jurnal internasional bereputasi = 3. Tidak ada publikasi di seminar lokal, tidak ada publikasi di seminar nasional dan tidak ada publikasi di seminar internasional. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7928, 96, 4, 28, 4.00, 0.66, 2.64, 'Produk/jasa yang dapat dimanfaatkan sebanyak 7 jenis, antara lain pembuatan alat/mesin (5 jenis), desain alat (1 jenis) dan pelatihan (1 jenis). Hasilnya berupa laporan, foto, surat kerjasama. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7929, 96, 4, 29, 4.00, 0.38, 1.52, 'Tabel 3.b.8: Hasil Penelitian dan PkM dapat pengakuan PATEN Sederhana = 0. Ada produk HKI berupa Hak Cipta dan Desain Produk Industri 5 judul ciptaan: Penerapan Sistem (buku, 2020), Model Rancangan (karya tulis/artikel, 2018), Interprise Resourse 2 buah (buku, 2021) dan Rancang Bangun (karya tulis/artikel, 2021).  Selain itu ada hasil Penelitian dan PkM yang lain, yaitu: Enterprose Planning (2019) dan Penerapan Managemen ISO (2019) ber ISBN. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7930, 96, 4, 30, 3.00, 1.70, 5.10, 'Ada informasi dari UPPS tentang pengembangan dosen dari tahun 2015 hingga tahun 2019. Pengembangan SDM tertuang dalam dokumen RENSTRA dan dianggarkan dalam program kegiatan tahunan RENOP. Ada kegiatan PEKERTI, kegiatan AA untuk karier dosen. Semua diatur dalam Tupoksi, Kode Etik Dosen dan Kode Etik Tenaga Kependidikan. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7931, 96, 4, 31, 2.60, 0.85, 2.21, 'Tabel 3C, LKPS untuk Tenaga Kependidikan terdiri: 7 orang Pustakawan (masing-masing S2 ada 1 orang, S1 ada 1 orang dan D2 ada 5 orang), 4 orang laboran/teknisi (S1 ada 1 orang, D4 ada 2 orang dan D3 ada 1 orang), 5 analis/operator (S2 ada 2 orang dan S1 ada 3 orang) dan administrasi 1 orang (SMA). Saat AL Prodi dapat memperlihatkan dokumen terkait yang mendukung  kegiatan berdasarkan jenis pekerjaannya.', 'Ada penjelasan dari tim akreditasi dan tersedia dokumen yang terkait.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7932, 96, 5, 32, 4.00, 0.83, 3.32, 'Rata-rata biaya operasional Prodi selama 3 tahun terakhir untuk: Pendidikan Prodi sekitar 1.3 milyar untuk jumlah mahasiswa aktif 57 orang. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7933, 96, 5, 33, 2.23, 0.83, 1.85, 'Rata-rata biaya operasional Prodi selama 3 tahun terakhir untuk: Penelitian di Prodi sekitar 1.5 milyar untuk jumlah mahasiswa aktif 57 orang. ', 'Sidah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7934, 96, 5, 34, 4.00, 0.41, 1.64, 'Rata-rata biaya operasional Prodi selama 3 tahun terakhir untuk: PkM di Prodi sekitar 552.6 juta untuk jumlah mahasiswa aktif 57 orang. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7935, 96, 5, 35, 4.00, 0.41, 1.64, 'Ada 5 jenis Laboratorium yang berbeda milik sendiri / UPPS dan kondisi terawat yang digunakan untuk kegiatan praktek / praktikum mahasiswa D3 Program Studi Teknik Elektronika. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7936, 96, 5, 36, 3.40, 0.83, 2.82, 'Dana yang digunakan untuk pencapaian pembelajaran (teori dan praktek/praktikum) serta lainnya relatif cukup dan mendapat dukungan penuh dari Universitas dan yayasan.', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7937, 96, 5, 37, 4.00, 3.31, 13.24, 'Untuk 5 jenis Laboratorium, pemakaian Laboratorium untuk kegiatan praktek/praktikum sekitar 110.6 jam/minggu atau untuk setiap Laboratorium sekitar 22 jam per minggu. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7938, 96, 6, 38, 3.10, 2.25, 6.98, 'Evaluasi pemutakhiran kurikulum melibatkan stakeholder Internal dan Eksternal. Stakeholder Internal antara lain dosen, mahasiswa dan tenaga kependidikan, sedangkan Stakeholder Eksternal meliputi alumni, pengguna lulusan dan pakar. Profil Lulusan sesuai dengan jenjang KKNI, yaitu menjadi ahli teknik elektronika, teknisi kontrol dan wirausaha elektronika. Untuk mencapai hasil pembelajaran, telah dilengkapi dengan dokumen RPS (Rencana Pembelajaran Semester) untuk setiap mata kuliah dan menerapkan sistem pembelajaran CPL.                                 ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7939, 96, 6, 39, 3.50, 0.90, 3.15, 'Proses pembelajaran dilaksanakan dengan presentasi yang dilengkapi dengan silabus dan RPS mata kuliah. Kompetensi lulusan dinyatakan dalam rumusan Capaian Pembelajaran (CP). Menerapkan kurikulum PT dengan basis SN DIKTI yang CP nya menghasilkan Sikap, Penguasaan Pengetahuan, Keterampilan Umum dan Keterampilan Khusus yang masing-masing ada penjelaskannya CP nya.                             ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7940, 96, 6, 40, 3.50, 1.62, 5.67, 'Tersedia silabus dan RPS untuk mata kuliah teori DAN mata kuliah praktek. Proses pembelajaran dilaksanakan dengan presentasi yang dilengkapi dengan silabus dan RPS mata kuliah yang selalu dimutakhirkan. Standar kompetensi lulusan (SKL) dijabarkan dalam capaian pembelajaran lulusan (CPL). Evaluasi dilaksanakan melalui ujian, pemberian tugas, evaluasi semester,  Proyek Akhir (PA) dan ujian Proyek Akhir. Kompetensi lulusan yang diharapkan adalah keterampilan praktis, intelektual dan managerial, berwawasan dan berkarakter kebangsaan. Prodi dapat menunjukkan silabus, rps yang dilakukan evaluasi secara berkala.                               ', 'Ada penjelasan tambahan dari Prodi D3 Teknologi Manufaktur berikut tersedia dokumen yang terkait.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7941, 96, 6, 41, 3.17, 1.80, 5.70, 'Pembelajaran dilaksanakan dengan presentasi yang dilengkapi dengan silabus dan RPS yang isinya selalu dimutakhirkan, ada interaksi antara dosen-mahasiswa-sumber belajar. Strategi pencapaian standar, Universitas memberi ruang bahwa penilaian secara edukatif dan transparan. BPM melaksanakan pengendalian pada sistem pembelajaran.  Saat AL Prodi memperlihatkan  Proses pembelajaran dilakukan secara on line dan offline, UPPS menyiapkan ruang berupa studio untuk membuat audio visual.', 'Ada penjelasan tambahan dan ', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7942, 96, 6, 42, 4.00, 0.54, 2.16, 'Dari Tabel 5.a.1 LKPS: Jumlah 39 mata kuliah terdiri dari mata kuliah teori dan praktek. Dari dokumen Kurilulum (di lampirkan), jumlah jam praktikum 2301, jumlah jam teori 2063 jam dan jam pembelajaran total selama masa pendidikan= 4364. ', 'Ada perbaikan perhitungan jumlah jam teori dan jumlah jam praktek selama 6 semester dan dilengkapi dengan dokumen perbaikan yang terkait.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7943, 96, 6, 43, 3.00, 2.25, 6.75, 'Sistem pembelajaran di Prodi dengan menerapkan metoda CBT dan Teaching Factory untuk melatih mahasiswa dan produksi/Bisnis. Unit BPM akan meng-Audit Mutu Internal (AMI) pelaksanaan sistem pembelajaran di Prodi. Meskipun Program D3 MBKM tidak wajib, namun Prodi Teknologi Manufaktur merancang dan akan melaksanakan implementasi MBKM dengan cara mahasiswa magang di industri selama 6 bulan. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7944, 96, 6, 44, 3.00, 1.62, 4.86, 'Sistem evaluasi pembelajaran di Prodi D3 Teknologi Manufaktur menerapkan standar penilaian yang sudah ditentukan. Keberhasilan mahasiswa ditentukan oleh evaluasi setiap semester (UTS dan UAS), tugas-tugas, Proyek Akhir (PA), interaksi antara dosen dan mahasiswa serta sumber belajar. Tidak ada informasi tentang evaluasi Praktek Kerja/Magang di Industri. BPM  melaksanakan pengendalian tentang proses belajar mengajar melalui GPM. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7945, 96, 6, 45, 4.00, 1.62, 6.48, 'Kegiatan penelitian/PkM ada 63 judul, TIDAK ada penelitian/PkM Internasional, penelitian/PkM nasional 33 judul, penelitian/PkM wilayah 30 judul,  penelitian dengan Roadmap yang sesuai 63 judul dan TIDAK ada penelitian dengan Roadmap yang kurang sesuai dan tidak sesuai serta jumlah dosen 63 orang. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7946, 96, 6, 46, 4.00, 2.70, 10.80, 'Suasana akademik diluar kegiatan pembelajaran antara lain: mahasiswa aktif dalam kegiatan non akademik secara perorangan maupun kelompok di tingkat lokal maupun nasional, ada 12 kegiatan mahasiswa, 1 sebagai peserta dan yang lainnya juara (Tabel 16, Prestasi mahasiswa yg dicapai, dokumen LKPS). Ada kegiatan untuk menyalurkan minat dan bakat, program kreativitas mahasiswa, kegiatan non akademik dan kegiatan karier dan kewirausahaan (inovasi).', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7947, 96, 6, 47, 3.67, 2.70, 9.90, 'Tingkat kepuasan mahasiswa terhadap proses pembelajaran di Prodi Teknologi Manufaktur meliputi 5 aspek, yaitu sangat baik sekitar 83 %, baik sekitar 13 % dan kurang sekitar 3 %. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7948, 96, 7, 48, 4.00, 1.89, 7.56, 'Dalam 3 tahun terakhir, terdapat 22 judul penelitian dosen yang cenderung meningkat (Gambar 9, Kinerja Penelitian, dokumen LKPS). Dari hasil Penelitian tersebut, ada 11 kegiatan antara lain 2 kegiatan sebagai Keynote  Speacker, 5 kegiatan sebagai nara sumber dan 3 dosen sebagai \"visiting lecture\". dan menghasilkan 31 luaran yang dilaksanakan dosen dan melibatkan mahasiswa, dipublikasikan dan diimplementasikan ke dalam kegiatan perkuliahan. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7949, 96, 8, 49, 4.00, 0.94, 3.76, 'PKM. Dalam 3 tahun terakhir dihasilkan 9 judul PKM jumlahnya cenderung meningkat (Gambar 10 dokumen LKPS), lokasi di SMA/SMK dengan sasaran guru dan siswa. Biaya berasal dari insitusi/Universitas Garuda. Selain itu ada 15 jenis produk jasa yang diadopsi/diterapkan di industri/masyarakat (Tabel 3b7 LKPS) yang berkolaborasi antara dosen dengan mahasiswa. PKM yang lain, ada 5 karya cipta dosen: 2 jenis hak cipta karya tulis (artikel) dan 3 jenis karya cipta buku. Selain itu, ada 1 jenis karya teknologi tepat guna yang dimanfaatkan masyarakat berupa \"Mesin Pemintal Tali Tampar\". ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7950, 96, 8, 50, 4.00, 1.89, 7.56, 'PkM perguruan Tinggi dan PkM Mandiri jumlahnya 9 luaran untuk jangka waktu 3 tahun terakhir dari tahun 2018 hingga tahun 2020 (Tabel 3.b.3 LKPS). Sedangkan di Tabel 7 LKPS  kegiatan PkM Dosen yang melibatkan mahasiswa diuraikan dengan jelas dengan tema \"Desain Perancangan\" dan \"Perancangan Produk\" tentang : Pelatihan CAD dan CAM, Penggunaan Software Auto Cad,  Keterampilan Permesinan. Kegiatan tersebut untuk SMK dan pelatihan tentang \"Pengemasan Model Cup Jamu Cair untuk  UMKM \"Aleng Jaya\".                                                                  ', 'Perbaikan penjelasan terkait dengan Tabel 3.b.3 Pengabdian Masyarakat yang melibatkan DTPS dan mahasiswa dan Tabel 7 dokumen LKPS terkait dengan uraian/ penjelasan dari Tabel 3.b.3.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7951, 96, 9, 51, 3.00, 2.09, 6.27, 'Capaian Pembelajaran Lulusan (CPL) Prodi D3 Teknologi Manufaktur Fakultas Vokasi ditunjukkan oleh Indikator Kerja Utama (IKU) meliputi: sasaran, strategi pencapaian dan         Indikator Kinerja Kinerja Utama (IKU) untuk tahun 2020 dan 2021 berupa monitoring oleh GPM terhadap perkuliahan, evaluasi kinerja dosen dan mahasiswa, peningkatan kualitas UTS dan UAS, IPK rata2 bagi lulusan minimal 3.5 dan lulus antara 3-4 tahun. IKU dan IKT dikembangkan secara kontinu.', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7952, 96, 9, 52, 4.00, 2.09, 8.36, 'Tabel 8.a LKPS untuk Prodi D3 Teknologi Manufaktur: jumlah lulusan TS-2 ada 12 orang, TS-1 ada 13 orang dan TS ada 20 orang. Nilai rata2 lulusan untuk TS-2  3.75,  TS-1  3.83 dan untuk TS 3.82.  ', 'Ada perbaikan isi atau data2 nilai IPK rata2 di Tabel 8.a LKPS.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7953, 96, 9, 53, 3.75, 3.22, 12.08, 'Tabel 2.a.2 Seleksi mahasiswa Prodi D3, jumlah mahasiswa aktif di Prodi Teknologi Manufaktur ada 57 orang. Sedangkan di Tabel 8.b.1 Prestasi akademik mahasiswa untuk skala: internasional = 0, nasional = 10 dan wilayah/lokal = 0.  ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7954, 96, 9, 54, 3.52, 0.96, 3.38, 'Jumlah mahasiswa aktif 57 orang (no. 53). Di Tabel 8.b.2, jumlah prestasi non-akademik INTERNASIONAL = 0, jumlah prestasi non-akademik NASIONAL = 1, jumlah prestasi non-akademik Wilayah/Lokal =  5. Prodi dapat menunjukkan dokumennya.', 'Perbaikan isi di Tabel 8.b.2 LKPS.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7955, 96, 9, 55, 4.00, 2.09, 8.36, 'Jumlah mahasiswa reguler per angkatan pada akhir TS-4 ada 25, jumlah mahasiswa reguler per angkatan pada akhir TS dari saat masuk TS-4 ada 2. Jumlah mahasiswa reguler per angkatan pada akhir TS-3 ada 17 orang. Jumlah mahasiswa reguler per angkatan pada akhir TS (masuk dari TS-3) ada 1 orang. Jumlah mahasiswa reguler per angkatan pada akhir TS-2 ada 25 orang dan jumlah mahasiswa reguler per angkatan pada akhir TS (masuk dari TS-2) ada 0 orang.', 'Perbaikan data-data di Tabel 8.c LKPS.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7956, 96, 9, 56, 4.00, 2.09, 8.36, 'Tabel 8.c LKPS: jumlah mahasiswa yang diterima pada tahun TS-2 ada 25 dan jumlah mahasiswa yang yang lulus pada tahun yang sama ada 20. Persentasi kelulusan adalah 80 % (hasil hitungan).', 'Penambahan penjelasan.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7957, 96, 9, 57, 0.10, 2.09, 0.21, 'Tabel 8.c LKPS. jumlah mahasiswa yang diterima pada TS-4 ada 25, jumlah yang terdaftar pada TS ada 2  dan jumlah yang lulus pada TS ada 12.  Hasil perhitungan: mahasiswa lulus tepat waktu 80 % dan mahasiswa yang DO atau Mengundurkan Diri (MDO) sekitar 44 %. ', 'Ada perubahan input  di kolom isian data yang terkait dengan Tabel 8.c untuk Program Studi D3 Teknologi Manufaktur.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7958, 96, 9, 58, 2.00, 3.22, 6.44, 'Hasil Tracer Study di Prodi D3 Teknologi Manufaktur: sukses dan maksimal yang ditunjukkan Gambar 32 (Hasil Tracer Study) dari TS-2 hingga TS (3 tahun), total ada 55 lulusan. Rata2 di atas 75 % mendapatkan kerja sesuai dengan bidangnya, masih dipercaya oleh dunia industri. Keterangan tambahan telah dilengkapi  diminta di butir ini adalah TS-4 sampai dengan TS-2.', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7959, 96, 9, 59, 4.00, 3.22, 12.88, 'Tabel 8.d.1 yang lulus pada: TS-4  = 0, TS-3 = 7 dan TS-2 = 12. Jumlah lulusan terlacak pada: TS-4 = 0, TS-3 = 7 dan TS-2 = 12.  Jadi waktu tunggu rata2 lulusan untuk mendapatkan pekerjaan pertama kurang dari 3 bulan. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7960, 96, 9, 60, 4.00, 2.09, 8.36, 'Tabel 8.d.2. Jumlah lulusan pada TS-4 = 0, TS-3 =  dan TS-2 = 12. Kesesuaian tingkat kerja kategori tinggi ada 6 padaTS-3 dan ada 2 pada TS-2.', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7961, 96, 9, 61, 4.00, 2.09, 8.36, 'Tabel 8.e.1. Jumlah lulusan TD-4 = 0,  TS-3 = 7 dan TS-2 = 12. Lulusan bekerja sebagai wirausaha: TS-4 = 0, TS-3 = 7 dan TS-2 = 12 . ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7962, 96, 9, 62, 3.53, 4.02, 14.18, 'Dari Tabel 8e.1, jumlah lulusan terlacak TS-3 ada 7 orang, lulusan terlacak pada TS-2 ada 12 orang, Tabel 8.e.2 Tingkat pengguna Lulusan terdiri dari 7 parameter telah diisi semua dan kecenderungannya baik. Tersedia dokumen yang terkait.', 'Ada penjelasan tambahan dan tersedia dokumen yang tekait.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7963, 96, 9, 63, 4.00, 2.89, 11.56, 'Tabel 8.f.4. Ada produk/karya mahasiswa sebanyak 7 jenis (atas nama Fajrul Fikri Al-Firdausi 1 jenis, Nur Cahyono 5 jenis dan Eri Pudji Cahyono 1 jenis) terdiri dari pembuatan mesin pemintal tali, desain dan pembuatan alat, dan rancang bangun alat dan hasilnya ditunjukkan oleh foto alat dan dokumen laporan.  ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7964, 96, 10, 64, 3.50, 1.00, 3.50, 'Penjaminan mutu Prodi dilaksanakan oleh Fakultas yang dilakukan secara konsisten dan berkelanjutan dengan tujuan: a. melaksanakan standar mutu layanan akademik, b. transparan dan akuntabel, c. semua pihak melaksanakan VMTS. Ada Gugus Pengendalian Mutu (GPM) di tingkat Universitas Garuda dan Sistem Pengendalian Mutu Internal (SPMI) di tingkat Fakultas. Tersedia dokumen: pernyataan mutu, kebijakan mutu, manual mutu, standar mutu, prosedur mutu dan dokumen mutu lainnya. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7965, 96, 10, 65, 3.50, 1.00, 3.50, 'Penjaminan mutu Prodi dilaksanakan oleh Fakultas .  Tersedia 4 dokumen/buku: 1. Kebijakan mutu SPMI, 2. Manual mutu SPMI, 3. Standar mutu SPMI dan 4. Formulir SPMI.                         (Tabel 9b LKPS). Ada pengakuan mutu eksternal antara lain: akreditasi Prodi oleh BAN PT (nilai C), ISO 9001-2015 (tahun 2022), ISO 21001-2018 (tahun 2022), audit Perpustakaan dan audit Keuangan. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7966, 96, 10, 66, 3.00, 2.00, 6.00, 'Tersedia 32 dokumen standar yang masing2 standar memiliki dokumen pelaksanaan standar, dokumen monev Audit Mutu Internal, dokumen umpan balik Audit Mutu Internal dan RTM. Terdapat 8 standar pendidikan, 8 standar penelitian dan 8 standar pengabdian kepada masyarakat. Implementasi sistem penjaminan mutu di UPPS dan Prodi sesusi dengan Standar Nasional Pendidikan yang terkait pada 8 aspek dan mererapkan konsep siklus PPEPP. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7967, 96, 10, 67, 4.00, 1.00, 4.00, 'Hasil analisis tingkat kepuasan Pemangku Kepentingan disampaikan kepada pihak yang terkait untuk ditindaklanjuti dalam rangka peningkatan pelayanan untuk masa yang akan datang. Hasil tersebut juga dapat dipublikasikan dan dapat diakses oleh pihak yang berkepentingan. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7968, 96, 11, 68, 3.00, 2.00, 6.00, 'Strategi pengembangan Prodi melibatkan faktor Internal (kekuatan dan kelemahan), faktor Eksternal (peluang dan ancaman) dan 9 aspek (hal 149 dst dokumen LED) dan masing2 aspek dilengkapi dengan uraian/penjelasan tentang analisis SWOT dengan isu strategis berbasis LRAISE, yaitu: a. Program pengembangan kurikulum dan dosen  berbasis KBK, b. Peningkatan kualitas penelitian mahasiswa ke arah jurnal, c. Optimalisasi GBM, monitoring dan belajar berkelanjutan. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7969, 96, 11, 69, 3.00, 1.50, 4.50, 'Analisa SWOT tentang analisis SWOT dengan isu strategis berbasis LRAISE (Tabel 39 dokumen LED) dihasilkan rata2, bobot dan skor, yang intinya ada kekuatan dan kelemahan. Ada 3 jenis Isu strategis: a. Program pengembangan kurikulum dan dosen berbasis KBK, b. Peningkatan kualitas penelitian mahasiswa ke arah jurnal, c. Optimalisasi GBM, monitoring dan belajar berkelanjutan. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21'), (7970, 96, 11, 70, 3.00, 2.50, 7.50, 'Program Pengembangan Berkelanjutan mencakup: 1. Penguatan calon tenaga dosen vokasional, 2. Peningkatan jumlah kerjasama dan 3. Membangun karakter lulusan dan pengguna lulusan (stakeholder). Tahun 2020, hasil ada yang memenuhi target dan ada yang belum memenuhi target. Tahun 2022 dan seterusnya, ada peningkatan kinerja  program pengembangan. ', 'Sudah sesuai.', '2022-07-05 19:15:21', '2022-07-05 19:15:21');
COMMIT;

-- ----------------------------
-- Table structure for rincian_butir_penilaian_al_prodi_baru
-- ----------------------------
DROP TABLE IF EXISTS `rincian_butir_penilaian_al_prodi_baru`;
CREATE TABLE `rincian_butir_penilaian_al_prodi_baru`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `laporan_al_id` bigint(20) UNSIGNED NOT NULL,
  `kriteria_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `nomor_butir` smallint(5) UNSIGNED NOT NULL,
  `skor_butir` decimal(5, 2) NOT NULL,
  `bobot_butir` decimal(5, 2) NOT NULL,
  `skor_akhir_butir` decimal(5, 2) NOT NULL,
  `deskripsi_butir` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `catatan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `rincian_butir_penilaian_al_prodi_baru_laporan_al_id_foreign`(`laporan_al_id` ASC) USING BTREE,
  INDEX `rincian_butir_penilaian_al_prodi_baru_kriteria_id_foreign`(`kriteria_id` ASC) USING BTREE,
  CONSTRAINT `rincian_butir_penilaian_al_prodi_baru_kriteria_id_foreign` FOREIGN KEY (`kriteria_id`) REFERENCES `kriteria_butir_penilaian_prodi_baru` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `rincian_butir_penilaian_al_prodi_baru_laporan_al_id_foreign` FOREIGN KEY (`laporan_al_id`) REFERENCES `laporan_al_prodi_baru` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 907 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- ----------------------------
-- Records of rincian_butir_penilaian_al_prodi_baru
-- ----------------------------
BEGIN;
INSERT INTO `rincian_butir_penilaian_al_prodi_baru` (`id`, `laporan_al_id`, `kriteria_id`, `nomor_butir`, `skor_butir`, `bobot_butir`, `skor_akhir_butir`, `deskripsi_butir`, `catatan`, `created_at`, `updated_at`) VALUES (608, 39, 1, 1, 3.50, 4.00, 14.00, 'Prodi TK Ubeo berfokus pada pengolahan biomassa dari pertanian, kelautan, dan biosains tropika.\r\nPerbandingan dengan Prodi Sejenis: Dibandingkan dengan ITB, UGM, dan UI, yaitu bahwa Ubeo lebih menekankan pada Teknik Pangan dan Bioproses. Pengembangan Keilmuan sudah terintegrasi dalam bidang Teknik Pangan, Teknik Bioproses, dan teknologi pendukung seperti IoT dan AI. Kajian CPL mengacu pada KKNI, IABEE, dan Permendikbud 53/2023, dengan penekanan pada pengembangan keterampilan teknis dan non-teknis. Kurikulum prodi yang diusulkan berbeda karena berfokus pada bahan terbarukan, sementara ITB, UGM, dan UI lebih menekankan bahan fosil. Beberapa perbandingan ini tidak terlalu tepat namun sudah dilakukan. ', NULL, '2025-04-16 18:02:18', '2025-04-16 18:02:18'), (609, 39, 1, 2, 3.50, 3.00, 10.50, 'UPPS telah menguraikan profil lulusan berupa profesi atau jenis pekerjaan atau bentuk kerja lainnya dilengkapi dengan (1) uraian ringkas seluruh profil, yang sesuai dengan program pendidikannya dan (2) keterkaitan profil dengan keunikan atau keunggulan prodi. Ada 4 profil lulusan yaitu sebagai: Perekayasa (Engineer) di perusahaan manufaktur yang mampu merancang proses dan pengembangan produk di industri terkait dengan pangan, pertanian, farmasi, dan energi; Konsultan teknik kimia yang memberikan saran dalam pengembangan produk, memecahkan masalah teknis, dan meningkatkan efisiensi operasional; Akademisi yang bekerja sebagai asisten pengajar di perguruan tinggi atau pengajar di sekolah menengah atas/kejuruan bidang teknik proses kimia; dan sebagai Wirausahawan yang mengembangkan usaha mandiri di bidang manufaktur kecil, konsultan independen, atau startup teknologi terkait Teknik Kimia.\r\nKeterkaitan Profil dengan Keunikan atau Keunggulan Prodi: Lulusan  dirancang untuk memiliki keahlian dalam mengembangkan dan mengoptimalkan proses produksi di sektor pertanian, kelautan, dan biosains tropika. Ini sesuai dengan kekhasan Program Studi Teknik Kimia Ubeo yang menekankan peminatan pada Teknik Pangan dan Teknik Bioproses​', NULL, '2025-04-16 18:02:18', '2025-04-16 18:02:18'), (610, 39, 1, 3, 3.50, 8.00, 28.00, 'Rumusan capaian pembelajaran lulusan (CPL) disusun untuk memenuhi kemampuan profesional yang dibutuhkan oleh profil lulusan seperti Perekayasa (Engineer), Konsultan Teknik Kimia, Akademisi, dan Wirausahawan. CPL dirumuskan dengan mengacu pada kompetensi yang dibutuhkan dalam perancangan, pengembangan, pengelolaan, dan evaluasi proses produksi di sektor pangan, pertanian, farmasi, energi, dan industri lainnya. \r\nKompetensi yang diuraikan sudah sesuai SN-Dikti yang mencakup 4 domain capaian pembelajaran dan sesuai level 6 KKNI yaitu: Sikap: CPL #1 dan CPL #2 terkait dengan nilai-nilai moral, etika, kerja sama tim, profesionalisme, dll. Pengetahuan: CPL #3, CPL #4, dan CPL #5 mengacu pada penerapan prinsip-prinsip Teknik Kimia, desain produk, proses, dan sistem yang kompleks. Keterampilan Khusus: CPL #9 dan CPL #10 menekankan pada kemampuan berpikir kritis, menganalisis masalah, dan membuat keputusan yang tepat. Keterampilan Umum: CPL #6, CPL #7, dan CPL #8 berkaitan dengan perencanaan, pengembangan, evaluasi proses, serta penggunaan perangkat lunak teknis.\r\nSesuai Level 6 KKNI: Dirumuskan berdasarkan Permendikbud No. 53 Tahun 2023 dan mengacu pada standar IABEE dan KKNI yang merujuk pada level 6 (sarjana).\r\nKeunikan Prodi Teknik Kimia Ubeo terkait dengan kajian pemanfaatan dan pengolahan biomassa dari sektor pertanian, kelautan, dan biosains tropika sangat terintegrasi dalam CPL yang dirancang.\r\nCPL khususnya menekankan pada kemampuan merancang, mengembangkan, mengoptimasi, mengendalikan, mengevaluasi, dan memperbaiki proses produksi yang berbasis agromaritim.\r\nBeberapa capaian pembelajaran lulusan (CPL) secara eksplisit mengacu pada Permendikbud No. 53 Tahun 2023 yang merupakan bagian dari standar pendidikan nasional (SN-Dikti)', NULL, '2025-04-16 18:02:18', '2025-04-16 18:02:18'), (611, 39, 1, 4, 3.00, 15.00, 45.00, 'Dokumen LED UPPS menyajikan struktur kurikulum dengan MK wajib yang mencakup: Agama (3 sks); Pancasila (1 sks); Pendidikan Kewarganegaraan (1 sks) dan Bahasa Indonesia (2 sks) yang terdapat pada semester awal (Semester 1 dan 2) yang menunjukkan kesesuaian dengan ketentuan umum mengenai mata kuliah wajib.\nSetiap mata kuliah yang disusun dalam kurikulum memiliki keterkaitan langsung dengan Capaian Pembelajaran Lulusan (CPL) yang dirumuskan. Sebagai contoh:MK Neraca Massa dan Energi dan Termodinamika Teknik Kimia mendukung CPL terkait perancangan proses, analisis data, dan pengelolaan sistem teknik kimia yang kompleks (CPL 3 - 5); MK Perancangan Proses dan Simulasi Proses & Optimasi Proses berkaitan dengan kemampuan mengembangkan dan mengelola proses produksi di bidang agromaritim (CPL 6 - 9).\nUrutan MK telah terlihat logis dan terstruktur dengan MK dasar di awal perkuliahan, diikuti dengan mata kuliah yang lebih spesifik terkait dengan peminatan (Teknik Bioproses atau Teknik Pangan). \nTotal SKS yang perlu diselesaikan adalah 144 SKS, yang dibagi secara proporsional pada setiap semester dengan rata-rata beban per semester adalah 18 SKS, (wajar dan sesuai dengan SN-Dikti).\n\n', NULL, '2025-04-16 18:02:18', '2025-04-16 18:02:18'), (612, 39, 1, 5, 3.50, 9.00, 31.50, 'Semua sembilan komponen RPS telah terpenuhi dengan baik dalam LED ini. Sebagian besar referensi yang digunakan cukup mutakhir, terutama yang berasal dari artikel ilmiah dan publikasi terbaru di bidang bioproses dan pangan. Terdapat beberapa referensi klasik yang sudah agak lama, khususnya untuk mata kuliah dasar. ', NULL, '2025-04-16 18:02:18', '2025-04-16 18:02:18'), (613, 39, 1, 6, 3.50, 1.00, 3.50, 'Kebijakan Dosen Pembimbing Akademik (DPA) disediakan untuk setiap mahasiswa dan bertugas memantau serta memberikan arahan terhadap proses belajar mahasiswa, khususnya yang mengambil kegiatan di luar program studi utama. POB Pembentukan Dosen Penggerak (Dosen Wali) sudah tersedia dalam dokumen untuk mendukung pelaksanaan MBKM.\nKurikulum dirancang agar memungkinkan mahasiswa mengambil pembelajaran di luar Prodi mencakup pertukaran pelajar, magang, kewirausahaan, proyek independen, pengabdian masyarakat, dan penelitian, dengan memungkinkan mahasiswa mengambil minimal 10 SKS per semester di luar program studi.', NULL, '2025-04-16 18:02:18', '2025-04-16 18:02:18'), (614, 39, 2, 7, 3.50, 32.73, 114.55, 'Persyaratan calon dosen tetap sebanyak 5 orang sudah terpenuhi, bahkan terdapat 6 calon dosen tetap dengan kualifikasi yang sangat relevan dengan bidang ilmu Teknik Kimia. Kualifikasi akademik sudah mencakup lulusan magister dan doktor yang relevan (level 8 dan 9 KKNI).  Status PNS atau CASN sudah dimiliki oleh para dosen yang terdaftar.\n', NULL, '2025-04-16 18:02:18', '2025-04-16 18:02:18'), (615, 39, 3, 8, 3.50, 2.27, 7.95, 'Telah terdapat penjelasan mengenai struktur organisasi UPPS (sekolah teknik Ubeo) pada bagian kriteria 3. unit pengelola program studi (halaman 21 - 28). \r\n5 unsur unit penglola program studi (UPPS) telah terpenuhi. kebijakan ditetapkan oleh dekan dan senat sekolah, dengan landasan aturan dari Ubeo dan peraturan yang relevan.\r\nUnsur pelaksana akademik telah terpenuhi. Pelaksanaan akademik dikelola secara terstruktur mulai dari dekan, wakil dekan, hingga ketua program studi.\r\nUnsur pengawas dan penjaminan mutu telah terpenuhi. Sistem penjaminan mutu terstruktur dengan baik melalui GPM dan GKM yang telah memiliki tugas dan fungsi yang jelas.\r\nUnsur penunjang akademik atau sumber belajar telah terpenuhi. Infrastruktur pendukung sudah mencakup sistem layanan akademik berbasis digital serta sarana laboratorium dan perpustakaan.\r\nUnsur pelaksana administrasi atau tata usaha telah terpenuhi. sistem pengelolaan administratif sudah dibentuk dengan baik di bawah sekolah teknik yang mengacu pada aturan Ubeo.\r\nTata kerja sudah diatur dengan baik melalui sistem yang terstruktur hierarki hubungan antar unsur di UPPS sudah dijelaskan dengan jelas. \r\n', NULL, '2025-04-16 18:02:18', '2025-04-16 18:02:18'), (616, 39, 3, 9, 3.00, 3.18, 9.55, 'Upaya tata kelola/good governance dalam pengelolaan UPPS dan Prodi telah berjalan dengan baik. Pemilihan Dekan & Wakil Dekan dilakukan berdasarkan kriteria kompetensi, integritas, dan kemampuan memimpin sesuai dengan Peraturan Rektor Nomor 1/IT3/KP/2017. SPMI dikelola oleh Kantor Manajemen Mutu (KMM) yang memastikan standar yang digunakan dapat dipertanggungjawabkan. Sistem manajemen akademik (SIMAK Ubeo, SIPAKARIL, Repositori Ubeo) memfasilitasi keterbukaan informasi. Keterbukaan pengelolaan melalui sistem informasi digital yang dapat diakses oleh pemangku kepentingan. Pengelolaan Kinerja dilakukan dengan SIMAKER, termasuk pelaporan capaian kinerja setiap semester. Proses audit dan evaluasi yang terstruktur melalui Gugus Penjamin Mutu (GPM) dan Gugus Kendali Mutu (GKM). Penggunaan kontrak kinerja yang dievaluasi secara berkala dan menjadi dasar pengambilan kebijakan. Pengelolaan sumber daya & anggaran, tanggung jawab dalam Tridharma PT dan pengelolaan Prodi sudah mencerminkan mekanisme pelaporan dan pengawasan yang ketat dan akuntable. Prinsip keadilan terjaga melalui prosedur yang obyektif dan tanpa diskriminasi. Layanan akademik telah didukung dengan sistem informasi yang terintegrasi di tingkat Ubeo dan fakultas/sekolah.\r\n', NULL, '2025-04-16 18:02:18', '2025-04-16 18:02:18'), (617, 39, 3, 10, 3.00, 9.55, 28.64, 'Penjaminan mutu di Ubeo dijalankan berdasarkan Peraturan Majelis Wali Amanat (MWA) Ubeo Nomor 06/MWA-UBEO/ P/2020 tentang Struktur Organisasi dan Tata Kerja (SOTK) Universitas Borneo (Ubeo) pada Pasal 119, disebutkan bahwa sistem penjaminan mutu internal (SPMI) di tingkat institusi dikoordinasikan oleh Kantor Manajemen Mutu (KMM). KMM bertugas dalam melaksanakan pengembangan sistem penjaminan mutu, peningkatan mutu, dan akuntabilitas penyelenggaraan program dan kegiatan Ubeo, pengembangan sistem dan pelaksanaan pengawasan internal dalam bidang akademik. KMM melaksanakan fungsi (a) pembinaan unit kerja di lingkungan Ubeo terkait dengan penegakan aturan, pencapaian standar mutu dan indikator kinerja dalam penyelenggaraan program dan kegiatan Ubeo; (b) penguatan sistem penjaminan mutu berbasis digital bidang akademik dan non-akademik; (c) pelaksa-naan koordinasi dan penilaian sistem penjaminan mutu, evaluasi standar mutu penyelenggaraan program dan kegiatan Ubeo serta dokumentasi hasil pelaksa-naannya; (d) pelaksanaan koordinasi proses akreditasi dan sertifikasi tingkat nasional maupun internasional pada level institut, fakultas, departemen, program studi dan/atau unit kerja pelaksana administrasi/penunjang. Seluruh lima aspek SPMI (Penetapan, Pelaksanaan, Evaluasi, Pengendalian, dan Peningkatan) telah tercerrmin. \r\n', NULL, '2025-04-16 18:02:18', '2025-04-16 18:02:18'), (618, 39, 3, 11, 4.00, 3.47, 13.88, 'Jumlah Ruang Kuliah: Terdapat 4 ruang kuliah utama yang digunakan untuk perkuliahan teori.\nLuas Ruang: Setiap ruang memiliki luas rata-rata 75 m2, yang berarti dapat menampung hingga 50 mahasiswa per sesi kuliah dengan standar 1.5 m2 per mahasiswa.\nFasilitas: Dilengkapi dengan proyektor, whiteboard, AC, dan jaringan internet (Wi-Fi) yang berfungsi dengan baik.\nKondisi & Penggunaan: Sudah memadai untuk mendukung proses pembelajaran dengan jumlah mahasiswa yang ada.\nRuang kuliah telah memenuhi standar luas per mahasiswa dan dilengkapi dengan fasilitas pendukung yang baik.', NULL, '2025-04-16 18:02:18', '2025-04-16 18:02:18'), (619, 39, 3, 12, 3.50, 2.60, 9.10, 'Sudah terdapat ruang akademik khusus yang disediakan untuk setiap jenis kegiatan praktikum yang berbeda. Setiap laboratorium memiliki luas yang mencukupi (> 1.5 m2 per mahasiswa) dan merupakan milik sendiri.Kelengkapan peralatan sesuai dengan kebutuhan kurikulum.  Perlu dilihat saat visitasi. \n\n', NULL, '2025-04-16 18:02:18', '2025-04-16 18:02:18'), (620, 39, 3, 13, 3.00, 3.47, 10.41, 'Prodi telah menyiapkan petalatan yang mencukupi untuk mendukung praktikum dasar dan praktikum terapan yang sesuai dengan kurikulum yang ditetapkan pada 2 tahun awal. Pengadaan peralatan telah memperhitungkan standar minimal (>1.5 m2 per mahasiswa, 25 orang mahasiswa per ruang). Status kepemilikan peralatan adalah milik sendiri, dan peralatan tersebut sudah sesuai dengan standar nasional dan internasional (IABEE, SN-Dikti). Peralatan untuk praktikum dasar dan lanjutan telah disiapkan dengan baik di berbagai lanboratorium yang ada. Beberapa peralatan mutakhir sudah tersedia untuk menunjang proses praktikum yang lebih modern, khususnya di bidang bioproses dan teknologi pangan. Peralatan yang digunakan telah melalui proses pengadaan dan pemeliharaan yang teratur dan perlu ada pembaruan untuk alat-alat tertentu yang sudah mulai usang. ', NULL, '2025-04-16 18:02:18', '2025-04-16 18:02:18'), (621, 39, 3, 14, 3.50, 2.73, 9.55, 'Prodi telah memenuhi syarat minimal jumlah tenaga kependidikan dengan kondisi sudah disiapkan 6 orang tenaga kependidikan bergelar sarjana dan sarjana muda secara khusus sebagai pustakawan, administrasia akademik dan 4 tenaga teknisi dan selebihnya tenaga kependidikan berada di UPPS.Beban kerja tenaga kependidikan dapat menjadi lebih berat jika program studi mengembangkan lebih banyak kegiatan praktikum, penelitian, dan kegiatan MBKM (Merdeka Belajar - Kampus Merdeka) sehingga perlu adanya penambahan pegawai yang menangani laboratorium dan kegiatan MBKM \n', NULL, '2025-04-16 18:02:18', '2025-04-16 18:02:18');
COMMIT;

-- ----------------------------
-- Table structure for riwayat_sk
-- ----------------------------
DROP TABLE IF EXISTS `riwayat_sk`;
CREATE TABLE `riwayat_sk`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `prodi_id` bigint(20) UNSIGNED NOT NULL,
  `institusi_id` bigint(20) UNSIGNED NOT NULL,
  `jenjang_id` bigint(20) UNSIGNED NOT NULL,
  `no_sk` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `tahun_sk` smallint(5) UNSIGNED NOT NULL,
  `jenis_sk` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `peringkat` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `berlaku_mulai` date NOT NULL,
  `berakhir_pada` date NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `status_sk_id` tinyint(3) UNSIGNED NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `riwayat_sk_prodi_id_foreign`(`prodi_id` ASC) USING BTREE,
  INDEX `riwayat_sk_institusi_id_foreign`(`institusi_id` ASC) USING BTREE,
  INDEX `riwayat_sk_jenjang_id_foreign`(`jenjang_id` ASC) USING BTREE,
  INDEX `riwayat_sk_status_sk_id_foreign`(`status_sk_id` ASC) USING BTREE,
  CONSTRAINT `riwayat_sk_institusi_id_foreign` FOREIGN KEY (`institusi_id`) REFERENCES `institusi` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `riwayat_sk_jenjang_id_foreign` FOREIGN KEY (`jenjang_id`) REFERENCES `jenjang` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `riwayat_sk_prodi_id_foreign` FOREIGN KEY (`prodi_id`) REFERENCES `prodi` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `riwayat_sk_status_sk_id_foreign` FOREIGN KEY (`status_sk_id`) REFERENCES `status_sk` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 4015 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- ----------------------------
-- Records of riwayat_sk
-- ----------------------------
BEGIN;
INSERT INTO `riwayat_sk` (`id`, `prodi_id`, `institusi_id`, `jenjang_id`, `no_sk`, `tahun_sk`, `jenis_sk`, `peringkat`, `berlaku_mulai`, `berakhir_pada`, `created_at`, `updated_at`, `status_sk_id`) VALUES (5, 138, 635, 1, '1114/SK/LAM Teknik/AS/VIII/2022', 2022, 'Akreditasi', 'Baik', '2022-08-21', '2027-08-20', '2022-08-17 20:02:28', '2023-11-26 13:44:58', 1), (1266, 77, 768, 1, '1124/SK/LAM Teknik/PB.AS/XII/2022', 2022, 'Akreditasi', 'Baik', '2022-12-21', '2024-12-20', '2024-01-24 17:56:00', '2024-01-24 17:56:00', 1), (2928, 112, 40, 1, '1287/SK/LAM Teknik/AS/IV/2025', 2025, 'Akreditasi', 'Baik', '2025-04-21', '2027-04-20', '2025-04-21 08:21:21', '2025-04-21 08:21:21', 1);
COMMIT;

-- ----------------------------
-- Table structure for sekretariat
-- ----------------------------
DROP TABLE IF EXISTS `sekretariat`;
CREATE TABLE `sekretariat`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `remember_token` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 0,
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `photo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `sekretariat_email_unique`(`email` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- ----------------------------
