-- ----------------------------
BEGIN;
INSERT INTO `sekretariat` (`id`, `name`, `email`, `email_verified_at`, `password`, `remember_token`, `created_at`, `updated_at`, `is_active`, `phone`, `photo`) VALUES (1, 'Dr. Soetomo', 'soetomo@lamteknik.or.id', NULL, '$2y$10$B3PQ50mSCBDOtuVPaQtoc.uXHT2o4uLjV/WTmm6S4Hmj/dE9//0Wi', NULL, '2022-03-31 07:59:04', '2025-10-10 19:56:13', 1, '08123456789', 'sekretariat/1_68e9026d73c13.jpeg'), (2, 'Pierre Tendean', 'tendean@lamteknik.or.id', NULL, '$2y$10$ZxbLSy2kWJgfjrD2lhdQZeNx1I83Znxn2oL7xVoRfXKaZYI6twvv.', 'MgJ8KVXmgU1YafXItGcpamc9Wao01Pi2JftRtUuQxBV397nUiaMDLy5RSMDj', '2022-03-31 08:01:06', '2025-07-10 15:20:54', 1, '08123456789', NULL), (3, 'Dewi Sartika', 'sartika@lamteknik.or.id', NULL, '$2y$10$.I7YkUIBNArI6vrF9leuVeZDHLJjhIlQrtxfIJneh5hC1rxn2DCKi', NULL, '2022-03-31 08:02:32', '2022-04-08 13:43:23', 1, '08123456789', NULL), (4, 'Kartini', 'kartini@lamteknik.or.id', NULL, '$2y$10$dRrsRqf3H51faoS.eQ4dq.zc/sXxtwLSeqduN1aXR0XfnW7ioDpK2', 'IhZPx91zy0b3F2vlFZVOvIuayfa39L8qsnMNkJ60qCBtuEBivJpFq7IdLZzn', '2022-03-31 09:33:32', '2022-03-31 09:34:48', 1, '08123456789', NULL), (5, 'Cut Nyak Dhien', 'cut@lamteknik.or.id', NULL, '$2y$10$4UGMo22H28BipvBh.KaG4eLBoC78F4sTcngRNUiE90g2s4Tm/z0aO', 'YqWbRfihqabhnSMqF2LhZpfqMrtpr0wCUFjj15k57JAupdvwqK9YWKOBzIEa', '2022-03-31 09:35:08', '2022-03-31 09:35:51', 1, '08123456789', NULL), (6, 'Hasanuddin', 'hasanuddin@lamteknik.or.id', NULL, '$2y$10$R/3pc9QzQMq3JOoScnqUJOZgL2sT8VOtyBSf/UMgLAZcqa6i7JdhG', 'A7NJjAad5jiLJAISEWB7KMgd2khveA6tatKRNJjNI62LXW0GVYnd5VmNGgEg', '2022-03-31 09:36:25', '2022-04-18 14:53:32', 1, '08123456789', NULL), (7, 'Soedirman', 'soedirman@lamteknik.or.id', NULL, '$2y$10$l/GWstwSMiWDLW0ThvWjOePqlyT6grxus6UJRo5lC3CZOu9sZ3sNW', 'mWTGVgjP19SK0449SOZCNykrj3rleBO6dBbTSU4kpHkCTtDNyAa6hnV9Ebuu', '2022-03-31 09:37:07', '2022-03-31 09:45:27', 1, '08123456789', NULL), (8, 'Diponegoro', 'dipo@lamteknik.or.id', NULL, '$2y$10$CWO1yCZfh5VBqw6cr5W6QOGTe04K8tEE0UAZPYZi1DlOhDb7IGPDW', 'Nt8Rs3QK5PAhcdvv1Zvhsi3NqTyu8zEBJuDqdAMkoKqmmoAvF2uKYoVLkUu6', '2022-09-01 09:03:32', '2022-09-01 09:10:55', 1, '08123456789', NULL), (11, 'Rasuna Said', 'rsaid@lamteknik.or.id', NULL, '$2y$10$kdqNZf7HqRyx17cfVoYQDOAD4w2grbY0090h0EmFfGfuDjoku4sqC', 'n5T7pxmqQyD5N5u0cpHfLDnxZzt3tgDDRH299qZedwuFO5Zx7ObMbs87ChmK', '2025-05-07 15:33:30', '2025-05-19 12:07:47', 1, '08123456789', NULL);
COMMIT;

-- ----------------------------
-- Table structure for sk
-- ----------------------------
DROP TABLE IF EXISTS `sk`;
CREATE TABLE `sk`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `prodi_id` bigint(20) UNSIGNED NOT NULL,
  `institusi_id` bigint(20) UNSIGNED NOT NULL,
  `jenjang_id` bigint(20) UNSIGNED NOT NULL,
  `no_sk` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `tahun_sk` smallint(5) UNSIGNED NOT NULL,
  `jenis_sk` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `peringkat` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `berlaku_mulai` date NOT NULL,
  `berakhir_pada` date NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `kode_pt` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `id_sp` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `kode_ps` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `id_sms` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `sk_prodi_id_foreign`(`prodi_id` ASC) USING BTREE,
  INDEX `sk_institusi_id_foreign`(`institusi_id` ASC) USING BTREE,
  INDEX `sk_jenjang_id_foreign`(`jenjang_id` ASC) USING BTREE,
  CONSTRAINT `sk_institusi_id_foreign` FOREIGN KEY (`institusi_id`) REFERENCES `institusi` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `sk_jenjang_id_foreign` FOREIGN KEY (`jenjang_id`) REFERENCES `jenjang` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `sk_prodi_id_foreign` FOREIGN KEY (`prodi_id`) REFERENCES `prodi` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 2292 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

