BEGIN;
INSERT INTO `sk` (`id`, `prodi_id`, `institusi_id`, `jenjang_id`, `no_sk`, `tahun_sk`, `jenis_sk`, `peringkat`, `berlaku_mulai`, `berakhir_pada`, `created_at`, `updated_at`, `kode_pt`, `id_sp`, `kode_ps`, `id_sms`) VALUES (5, 138, 635, 1, '1114/SK/LAM Teknik/AS/VIII/2022', 2022, 'Akreditasi', 'Baik', '2022-08-21', '2027-08-20', '2022-08-17 20:02:28', '2022-08-17 20:02:28', '1234456', 'e07f9464-1edf-4a32-a4cc-1be800015df7', '123456', 'feb7b9a3-cf4b-488f-b3ff-826cbbc7fc98'), (879, 77, 768, 1, '1124/SK/LAM Teknik/PB.AS/XII/2022', 2022, 'Akreditasi', 'Baik', '2022-12-21', '2024-12-20', '2024-01-24 17:56:00', '2024-01-24 17:56:00', '654321', 'a2b64075-2bfe-424b-9525-13fcaf5070d7', '654321', 'a7bd3ea5-fe91-428d-aed6-f0ae07d5faae'), (1810, 112, 40, 1, '1287/SK/LAM Teknik/AS/IV/2025', 2025, 'Akreditasi', 'Baik', '2025-04-21', '2027-04-20', '2025-04-21 08:21:21', '2025-04-21 08:21:21', '02468', '8ebe63e4-c6d1-4d0c-973b-416c22186779', '86420', '68ba0b97-d731-4013-85f1-dba3956ff090');
COMMIT;

