-- ----------------------------
-- Table structure for tanggapan_al
-- ----------------------------
DROP TABLE IF EXISTS `tanggapan_al`;
CREATE TABLE `tanggapan_al`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `al_id` bigint(20) UNSIGNED NOT NULL,
  `nomor` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `kriteria` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `deskripsi_berdasarkan_hasil_ak` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `deskripsi_berdasarkan_verifikasi_al` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `tanggapan_prodi` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `informasi_faktual` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `tanggapan_asesor` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `tanggapan_al_al_id_foreign`(`al_id` ASC) USING BTREE,
  CONSTRAINT `tanggapan_al_al_id_foreign` FOREIGN KEY (`al_id`) REFERENCES `asesmen_lapangan` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 140886 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- ----------------------------
-- Records of tanggapan_al
-- ----------------------------
BEGIN;
INSERT INTO `tanggapan_al` (`id`, `al_id`, `nomor`, `kriteria`, `deskripsi_berdasarkan_hasil_ak`, `deskripsi_berdasarkan_verifikasi_al`, `tanggapan_prodi`, `informasi_faktual`, `tanggapan_asesor`, `created_at`, `updated_at`) VALUES (22873, 96, '1', 'A. Kondisi Eksternal\nKonsistensi dengan hasil analisis SWOT dan/atau analisis lain serta rencana pengembangan ke depan.	', 'Terkait lingkungan eksternal, UPPS melakukan :\n1) identifikasi lingkungan makro, mencakup aspek politik dimana ada keterlibatan FT dalam perencanaan infratruktur daerah. Aspek ekonomi yaitu adanya ketidakjelasan kondisi ekonomi yang menjadikan PSTM agar dapat terus berinovasi dalam marketing dan pembiayaan yang terjangkau. Aspek Kebijakan pemerintah dengan mengeluarkan KIP guna meningkatkan kualitas SDM sehingga memberikan efek positif kepada PS TM dalam peningkatan animo masyarakat. Aspek sosial dan budaya diidentifikasi sebagai faktor peluang yang dapat meningkatkan anomo masyatakat. Aspek perkembangan IPTEK diidentifikasi dapat mendukung kegiatan pembelajaran dan kegiatan PPM.\n2) identifikasi lingkungan mikro menunjukkan bahwa PS TM merupakan salah satu PS dari PTS dengan daya tarik sendiri yang menjalankan PS sesuai VMTS berbasis IPTEK dan ecopreuneurship.\n3) hasil identifikasi digunakan untuk melakukan analisis SWOT mencakup kekuatan antara lain dalam tata pamong, kerjasama dan SDM; kelemahan antara lain dalam monev yang belum optimal, peminat mahasiswa baru yang masih rendah dan  jja dosen dengan Lektor ke atas yang masih rendah; ancaman antara lain semakin bertambahnya pesaing di daerah, perubahan teknologi yang pesat dan minat masyarakat ke pendidikan FT yang rendah.\nAnalisis SWOT digunakan untuk mengembangkan PS.\nAnalisis SWOT belum dilengkapi faktor peluang. Perlu konfirmasi.\n4) UPPS merumuskan 12 strategi pengembangan PS, namun belum dilengkapi dengan tahapan prioritas dan indikator capaian yang relevan. \nPada LED hal 11, terdapat strategi sesuai Renstra 2021-2030 dengan tahapan tahun pertama 2021-2025 mencakup 4 strategi. Perlu dikonfirmasi.\n', 'Terkait lingkungan eksternal, UPPS melakukan :\n1) identifikasi lingkungan makro, mencakup aspek politik dimana ada keterlibatan FT dalam perencanaan infratruktur daerah. Aspek ekonomi yaitu adanya ketidakjelasan kondisi ekonomi yang menjadikan PSTM agar dapat terus berinovasi dalam marketing dan pembiayaan yang terjangkau. Aspek Kebijakan pemerintah dengan mengeluarkan KIP guna meningkatkan kualitas SDM sehingga memberikan efek positif kepada PS TM dalam peningkatan animo masyarakat. Aspek sosial dan budaya diidentifikasi sebagai faktor peluang yang dapat meningkatkan anomo masyatakat. Aspek perkembangan IPTEK diidentifikasi dapat mendukung kegiatan pembelajaran dan kegiatan PPM.\n2) identifikasi lingkungan mikro menunjukkan bahwa PS TM merupakan salah satu PS dari PTS dengan daya tarik sendiri yang menjalankan PS sesuai VMTS berbasis IPTEK dan ecopreuneurship.\n3) hasil identifikasi digunakan untuk melakukan analisis SWOT mencakup kekuatan antara lain dalam tata pamong, kerjasama dan SDM; kelemahan antara lain dalam monev yang belum optimal, peminat mahasiswa baru yang masih rendah dan  jja dosen dengan Lektor ke atas yang masih rendah; ancaman antara lain semakin bertambahnya pesaing di daerah, perubahan teknologi yang pesat dan minat masyarakat ke pendidikan FT yang rendah.\nAnalisis SWOT digunakan untuk mengembangkan PS.\nPada AL, terkonfirmasi analisis SWOT tertuang dalam Renstra mencakup peluang berupa dukungan PEMDA untuk peinjaman biaya sekolah, hibah eksternal. \n4) UPPS merumuskan 12 strategi pengembangan PS, namun belum dilengkapi dengan tahapan prioritas dan indikator capaian yang relevan. \nPada LED hal 11, terdapat strategi sesuai Renstra 2021-2030 dengan tahapan tahun pertama 2021-2025 mencakup 4 strategi. Tahapan terkonfirmasi pada AL dengan dukungan dokumen Renstra dan Renp 2021-2025.\n', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22874, 96, '2', 'B. Profil Unit Pengelola Program Studi\nKeserbacakupan informasi dalam profil dan konsistensi antara profil dengan data dan informasi yang disampaikan pada masing-masing kriteria, serta menunjukkan iklim yang kondusif untuk pengembangan dan reputasi sebagai rujukan di bidang keilmuannya.', 'UPPS mendeskripsikan profilnya mencakup:\n1) menunjukkan keserbacakupan informasi yang jelas mencakup sejarah UPPS dimana PS TM berdiri pada 1990, VMTS dan tata nilai, organisasi dan tata kerja, mahasiswa dan lulusan, dosen dan tendik, keuangan dan sapras, dan kinerja PS.\n2) ada keselarasan dengan substansi keilmuan program studi, yang tercermin dalam perumusan VMTS dengan strategi pengembangan yang tertuang dalam Renstra 2021-2025.\n3)  iklim yang kondusif untuk pengembangan keilmuan program studi, dengan mendorong strategi pengembangan PS sejalan dengan UPPS.\n4) menunjukkan reputasi sebagai rujukan di bidang keilmuannya dengan memperoleh penghargaan pada lomba-lomba akademik di tingkat lokal dan nasional.', 'UPPS mendeskripsikan profilnya mencakup:\n1) menunjukkan keserbacakupan informasi yang jelas mencakup sejarah UPPS dimana PS TM berdiri pada 1990, VMTS dan tata nilai, organisasi dan tata kerja, mahasiswa dan lulusan, dosen dan tendik, keuangan dan sapras, dan kinerja PS.\n2) ada keselarasan dengan substansi keilmuan program studi, yang tercermin dalam perumusan VMTS dengan strategi pengembangan yang tertuang dalam Renstra 2021-2025.\n3)  iklim yang kondusif untuk pengembangan keilmuan program studi, dengan mendorong strategi pengembangan PS sejalan dengan UPPS.\n4) menunjukkan reputasi sebagai rujukan di bidang keilmuannya dengan memperoleh penghargaan pada lomba-lomba akademik di tingkat lokal dan nasional.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22875, 96, '3', 'C. Kriteria\nC.1. Visi, Misi, Tujuan dan Strategi\nC.1.4. Indikator Kinerja Utama\nKesesuaian Visi, Misi, Tujuan dan Strategi (VMTS) Unit Pengelola Program Studi (UPPS) terhadap VMTS Perguruan Tinggi (PT) dan visi keilmuan Program Studi (PS) yang dikelolanya.', 'Visi UPPS adalahMenjadi fakultas teknik unggulan di Provinsi Sumatera Tengah, yang profesional berwawasan IPTEK, IMTAQ dan Ecopreneurship pada tahun 2024. Visi tersebut diturunkan dari Visi Universitas dan memayungi kelimuan visi PS yaitu Menjadi Program Studi Teknik Mesin Unggulan  di Provinsi Sumatera Tengah, yang profesional berwawasan IPTEK, IMTAQ dan Ecopreneurship pada tahun 2024. \r\nPenyusunan VMTS PS didasarkan pada VMTS yang akan dicapai UPPS. Misi, tujuan dan strategi UPPS searah dan bersinergi dengan misi, tujuan dan strategi PT serta mendukung program studi. \r\nPerlu dikonfirmasi tahun pencapaian visi PS. Belum ada data implementasi yang relevan.', 'Visi UPPS adalah menjadi fakultas teknik unggulan di Provinsi Sumatera Tengah, yang profesional berwawasan IPTEK, IMTAQ dan Ecopreneurship pada tahun 2024. Visi tersebut diturunkan dari Visi Universitas dan memayungi kelimuan visi PS yaitu Menjadi Program Studi Teknik Mesin Unggulan  di Provinsi Sumatera Tengah, yang profesional berwawasan IPTEK, IMTAQ dan Ecopreneurship pada tahun 2024. \r\nPenyusunan VMTS PS didasarkan pada VMTS yang akan dicapai UPPS. Misi, tujuan dan strategi UPPS searah dan bersinergi dengan misi, tujuan dan strategi PT serta mendukung program studi. \r\nPada AL, tekonfirmasi tahapan pencapaian visi dalam 4 tahap dengan target capaian pada tahun 2024 yang didukung oleh Renstra 2021-2025. Kriteria unggul dinyatakan sebagai rujukan dalam topik unggulan pengolahan sampah dan teknologi tepat guna. Saat ini masuk dalam tahapan pengembangan SDM (2022-2023).', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22876, 96, '4', 'Mekanisme dan keterlibatan pemangku kepentingan dalam penyusunan VMTS UPPS.', 'Mekanisme penyusunan visi, misi dan tujuan dan sasaran program studi, diawali dengan pembentkan tim task force  untuk mendesain alternatif rancangan dengan melakukan analisis situasi (SWOT PS) serta mengakomodasi masukan baik dari internal stakeholder maupun eksternal stakeholder.  Pihak yang terlibat : pimpinan PS dan UPPS, unit penjaminan mutu seluruh dosen yang terlibat dalam proses belajar mengajar di Program Studi Teknik Mesin,  tendik, mahasiswa, alumni, pengguna alumni. \nBelum ada informasi keterlibatan pakar/mitra/organisasi prfesi/pemerintah).\nPelu konfirmasi pada AL.', 'Mekanisme penyusunan visi, misi dan tujuan dan sasaran program studi, diawali dengan pembentkan tim task force  untuk mendesain alternatif rancangan dengan melakukan analisis situasi (SWOT PS) serta mengakomodasi masukan baik dari internal stakeholder maupun eksternal stakeholder.  Pihak yang terlibat : pimpinan PS dan UPPS, unit penjaminan mutu seluruh dosen yang terlibat dalam proses belajar mengajar di Program Studi Teknik Mesin,  tendik, mahasiswa, alumni, pengguna alumni. \nPada AL, terkonfirmasi ada keterlibatan eksternal dalam penyusunan Visi yaitu industri : PT. Cokro, Unila, Pertakindo dan Perkindo (Asosiasi). Ada dokumen SOP Penyusunan Visi dan Penetapan. Ada Berita Acara Penyusunan Visi Misi dilengkapi dengan daftar hadir dan notulensi rapat.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22877, 96, '5', 'Pemahaman  visi, misi, tujuan, dan sasaran Program Studi oleh seluruh pemangku kepentingan internal (internal stakeholders): sivitas akademika (dosen dan mahasiswa) dan tenaga kependidikan.\n', 'VMTS disosialisasikan secara internal kepada dosen dan pegawai melalui pencantuman VMTS dalam berbagai pedoman akademik dan non akademik, disampaikan dalam rapat koordinasi, pemasangan dalam banner di ruangan. Ssosialisasi secara eksternal dengan penyampaian pada acara yang mengundang stakeholder ke kampus, kegiatan sosial WA dan facebook, website, dan brosur PMB, seminar dan pelatihan. \nAda implementasi VMTS pada kurikulum yang melakukan perubahankurikulum sesuai dengan perkembangan IPTEK, kebutuhan masyarakat dan pengguna lulusan. Ada survey pemahaman VMTS yang dilakukan oleh lembaga penjaminan mutu, namun belum dijelaskan metode dan instrumennya. Pada LED hal 27 ada informasi 85% sivitas akademik paham dengan VMTS PS TM. Perlu dikonfirmasi.', 'VMTS disosialisasikan secara internal kepada dosen dan pegawai melalui pencantuman VMTS dalam berbagai pedoman akademik dan non akademik, disampaikan dalam rapat koordinasi, pemasangan dalam banner di ruangan. Ssosialisasi secara eksternal dengan penyampaian pada acara yang mengundang stakeholder ke kampus, kegiatan sosial WA dan facebook, website, dan brosur PMB, seminar dan pelatihan. \nAda implementasi VMTS pada kurikulum yang melakukan perubahankurikulum sesuai dengan perkembangan IPTEK, kebutuhan masyarakat dan pengguna lulusan. Ada survey pemahaman VMTS yang dilakukan oleh lembaga penjaminan mutu. Pada LED hal 27 ada informasi 85% sivitas akademik paham dengan VMTS PS TM. \nPada AL dikonfirmasi bahwa survey pemahaman dilakukan dengan instrumen Google Form yang memuat pertanyaan mengenai pemahaman visi dengan skala 1-4.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22878, 96, '6', 'Strategi pencapaian tujuan disusun berdasarkan analisis yang sistematis, serta pada pelaksanaannya dilakukan pemantauan dan evaluasi yang ditindaklanjuti. ', 'Pada LED hal 11, dijelaskan Sasaran dan strategi pencapaian PS sesuai dengan Renstra UPPS (2021-2030) disusun dengan 2 (dua) periode Renstra yaitu pada tahun 2021- 2025, dan pada tahun 2025-2030. Orientasi jangka menengah adalah tercapainya pada tingkat lokal, sedangkan rencana panjang tercapainya pada tingkat nasional. Hasil pengukuran capaian IKU diinformasikan adalah 68,21%. Perlu dikonfirmasi instrumen dan metode pengukuran yang dilakukan.\nPerlu dikonfirmasi relevansi target tahapan strategi dengan tahapan pencapaian visi di tahun 2024.', 'Pada LED hal 11, dijelaskan Sasaran dan strategi pencapaian PS sesuai dengan Renstra UPPS (2021-2030) disusun dengan 2 (dua) periode Renstra yaitu pada tahun 2021- 2025, dan pada tahun 2025-2030. Orientasi jangka menengah adalah tercapainya pada tingkat lokal, sedangkan rencana panjang tercapainya pada tingkat nasional. Hasil pengukuran capaian IKU diinformasikan adalah 68,21%. \nPada AL, dikonfirmasi tahapan pencapaian visi dibagi menjadi 4 tahap.\nInstrumen pengukuran capaian IKU adalah dengan perhitungan capaian terhadap target, yang dimuat dalam dokumen Renop Fakultas per tahun.\n', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22879, 96, '7', 'C.2. Tata Pamong, Tata Kelola dan Kerjasama\nC.2.4. Indikator Kinerja Utama\nC.2.4.a) Sistem Tata Pamong\nA. Kelengkapan struktur organisasi dan keefektifan penyelenggaraan organisasi.\nB. Perwujudan good governance dan pemenuhan lima pilar sistem tata pamong, yang mencakup: 1) Kredibel, 2) Transparan, 3) Akuntabel, 4) Bertanggung jawab, 5) Adil.', 'A. UPPS memiliki struktur organisasi terdiri dari Dekan, Unit Penjaminan Mutu, Pimpinan Prodi, Bag Akademik, Sub TU, Kasubag, Kalab dan Operator yang dilengkapi deskripsi ttupoksi dan tugas wewenang, tercantum dalam LED hal 11-19. \nDisebutkan ada dokumen Statuta untuk acuan persyaratan Kaprodi, namun belum ada informasi dokumen formal struktur organisasi dan tata kerja.\nPerlu dikonfirmasi posisi Senat Fakultas dan Ruang Baca pada Struktur.\nB. UPPS menerapkan tata pamong yang mencakup aspek :\n1) Kredibel, dalam hal pemilihan Kaprodi  yang dilakukan melalui rapat senat sesuai persyaratan yang mengacu kepada STatuta Universitas.\nPenerapan peraturan akademik, kode etik mahasiswa, dosen dan pegawai, buku panduan dan tata tertib baik dalam penyelanggaraan, pembelajaran maupun disiplin kepegawaian.\n2)  Adil terhadap dosen, karyawan dan mahasisa yang berprestasi diberikan reward dan kepada yang melanggar aturan dibrikan sanksi (punishment) serta sivitas akademika mendapat perlakuan yang sama sesuai dengan standar-standar yang berlaku.\n3) Transparan dalam penilaian secara terbuka antara pemberi nilai dan yang diniliai.\n4) Akuntabel dengan  setiap kegiatan yang sudah dilaksanakan harus dipertanggungjawabkan dan dilaporkan hasilnya.\n5) Bertanggung jawab ditandai adanya struktur organisasi, uraian tugas, fungsi dan tanggung jawab. Universitas memiliki dan memberlakukan Kode Etik dosen yang mendukung pelaksanaan system yang bertanggung jawab.\nPenjelsan normatif, perlu konfirmasi bentuk penerapannya.\n', 'A. UPPS memiliki struktur organisasi terdiri dari Dekan, Unit Penjaminan Mutu, Pimpinan Prodi, Bag Akademik, Sub TU, Kasubag, Kalab dan Operator yang dilengkapi deskripsi ttupoksi dan tugas wewenang, tercantum dalam LED hal 11-19. \nDisebutkan ada dokumen Statuta untuk acuan persyaratan Kaprodi.\nB. UPPS menerapkan tata pamong yang mencakup aspek :\n1) Kredibel, dalam hal pemilihan Kaprodi  yang dilakukan melalui rapat senat sesuai persyaratan yang mengacu kepada STatuta Universitas.\nPenerapan peraturan akademik, kode etik mahasiswa, dosen dan pegawai, buku panduan dan tata tertib baik dalam penyelanggaraan, pembelajaran maupun disiplin kepegawaian.\n2)  Adil terhadap dosen, karyawan dan mahasisa yang berprestasi diberikan reward dan kepada yang melanggar aturan dibrikan sanksi (punishment) serta sivitas akademika mendapat perlakuan yang sama sesuai dengan standar-standar yang berlaku.\n3) Transparan dalam penilaian secara terbuka antara pemberi nilai dan yang diniliai.\n4) Akuntabel dengan  setiap kegiatan yang sudah dilaksanakan harus dipertanggungjawabkan dan dilaporkan hasilnya.\n5) Bertanggung jawab ditandai adanya struktur organisasi, uraian tugas, fungsi dan tanggung jawab. Universitas memiliki dan memberlakukan Kode Etik dosen yang mendukung pelaksanaan system yang bertanggung jawab.\nPada AL, dikonfirmasi dokumen formal struktur organisasi dan tata kerja adalah SK Dekan No. 94/2019 yang dilengkapi dengan keberadaan Senat Fakultas (jalur koordinasi dengan Dekan) dan Ketua Ruang Baca Fakultas.\nAspek Bertanggung jawab dijelaskan dengan pembuatan Laporan Kaprodi ke Dekan setiap akhir semester terkait pelaksanaan akademis, untuk selanjutnya dituangkan dalam Laporan Dekan ke Rektor.\n', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22880, 96, '8', 'C.2.4.b) Kepemimpinan dan Kemampuan Manajerial\nA. Komitmen pimpinan UPPS.\nB. Kapabilitas pimpinan UPPS, mencakup aspek: 1) perencanaan, 2) pengorganisasian, 3) penempatan personel, 4) pelaksanaan, 5) pengendalian dan pengawasan, dan 6) pelaporan yang menjadi dasar tindak lanjut. ', 'A) Karakteristik kepemimpinan operasinal dalam melaksanakan tugas dan tanggung jawab kepemimpinan dengan memberikan arahan, tujuan, peran dan tugas kepada seluruh unsur di dalam Jurusan Teknik Mesin. Pelaksanaan tugas dan tanggung jawab kepemimpinan dilakukan oleh ketua jurusan. Sekretarisjurusan bertugas melakukan pembinaan dan mengkoordinasi pelaksanaan tugas tenaga pendidikan. Kepemimpinan organisasaia dalam bentuk mengarahkan dan mempengaruhi perilaku semua unsurdalam program studi, mengikuti nilai, norma, etika, dan budaya organisasi yangdisepakati Bersama, serta mampu membuat keputusan yang tepat dan cepat Fakultas Teknik Universitas Garuda Dipimpin oleh seorang Dekan dengan dibantu oleh Wakil Dekan bidang Akademik (PD I), WakilDekan Bidang Administrasi dan Keuangan (PD II), Wakil Dekan BidangKemahasiswaan (PD. III), sedangkan kepemimpinan pada Program Studidipimpin oleh Ketua Program Studi. \r\nBelum ada informasi kepemimpinan Publik.\r\nB) Kapabilitas pimpinan UPPS mencakup :\r\n1) Perencanaan, dengan membuat program kerja tahunan, setiap tahunnya dilakukan diskusi dengan seluruh tenaga akademik dalam rapat program studi. Bentuk kegiatan dijelaskan bahwa setiap awal semester dilakukan perencanaan untuk kegiatan akademis pada semester bersangkutan, seperti penentuan mata kuliah yang diampu oleh masing-masing tenaga akademik.\r\n2) Pengorganisasian, dengan mengkoordinasikan penyusunan kurikukulum, penyelenggaraan kegiatan akademik, pelaksanaan penelitian dan PkM berkoordinasi dengan LPPM.\r\n3) Penempatan Personil, dengan memperoleh tenaga akademik yang relevan dengan kebutuhan PS  melalui proses rekruitment oleh pihak rektorat dengan mempertimbangkan spesifikasi yang ditentukan PS TM.\r\n4) Pengendalian, dengan cara memantau sebelum, sesama dan setelah kegiatan Tri Dharma Perguruan Tinggi serta juga memantau kesesuaiannya dengan manual prosedur dalam setiap kegiatan.\r\nBelum ada informasi kapabilitas pimpinan terkait pelaksanaan dan pelaporan  yang menjadi dasar tindak lanjut. Pelu konfirmasi pada AL.', 'A) Karakteristik kepemimpinan operasinal dalam melaksanakan tugas dan tanggung jawab kepemimpinan dengan memberikan arahan, tujuan, peran dan tugas kepada seluruh unsur di dalam Jurusan Teknik Mesin. Pelaksanaan tugas dan tanggung jawab kepemimpinan dilakukan oleh ketua jurusan. Sekretarisjurusan bertugas melakukan pembinaan dan mengkoordinasi pelaksanaan tugas tenaga pendidikan. Kepemimpinan organisasaia dalam bentuk mengarahkan dan mempengaruhi perilaku semua unsurdalam program studi, mengikuti nilai, norma, etika, dan budaya organisasi yangdisepakati bersama, serta mampu membuat keputusan yang tepat dan cepat Fakultas Teknik Universitas Garuda Dipimpin oleh seorang Dekan dengan dibantu oleh Wakil Dekan bidang Akademik (PD I), WakilDekan Bidang Administrasi dan Keuangan (PD II), Wakil Dekan BidangKemahasiswaan (PD. III), sedangkan kepemimpinan pada Program Studi dipimpin oleh Ketua Program Studi. \r\nB) Kapabilitas pimpinan UPPS mencakup :\r\n1) Perencanaan, dengan membuat program kerja tahunan, setiap tahunnya dilakukan diskusi dengan seluruh tenaga akademik dalam rapat program studi. Bentuk kegiatan dijelaskan bahwa setiap awal semester dilakukan perencanaan untuk kegiatan akademis pada semester bersangkutan, seperti penentuan mata kuliah yang diampu oleh masing-masing tenaga akademik.\r\n2) Pengorganisasian, dengan mengkoordinasikan penyusunan kurikukulum, penyelenggaraan kegiatan akademik, pelaksanaan penelitian dan PkM berkoordinasi dengan LPPM.\r\n3) Penempatan Personil, dengan memperoleh tenaga akademik yang relevan dengan kebutuhan PS  melalui proses rekruitment oleh pihak rektorat dengan mempertimbangkan spesifikasi yang ditentukan PS TM.\r\n4) Pengendalian, dengan cara memantau sebelum, sesama dan setelah kegiatan Tri Dharma Perguruan Tinggi serta juga memantau kesesuaiannya dengan manual prosedur dalam setiap kegiatan.\r\nPada AL, dikonfirmasi adanya karakter kepemimpinan publik Dekan sebagai Wakil Ketua PAPPI, Koordinator Penelitian dan Pengurus PII Cabang Sumatera Tengah; Sekprodi sebagai Pengurus Bidang Konsultan dan Riset PAPPI. Bukti dokumen tersedia.\r\nAda aspek pelaporan dalam bidang akademik yang didiskusikan dalam rapat dan dilaporkan kepada Rektor.\r\n', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22881, 96, '9', 'C.2.4.c) Kerjasama\nMutu, manfaat, kepuasan dan keberlanjutan kerjasama pendidikan, penelitian dan PkM yang relevan dengan program studi.UPPS memiliki bukti yang sahih terkait kerjasama yang ada telah memenuhi 3 aspek berikut :1) memberikan manfaat bagi program studi dalam pemenuhan proses pembelajaran, penelitian, PkM. 2) memberikan peningkatan kinerja tridharma dan fasilitas pendukung program studi. 3) memberikan kepuasan kepada mitra industri dan mitra kerjasama lainnya, serta menjamin keberlanjutan kerjasama dan hasilnya.', 'Terdapat 12 Kerjasama yang sudah dibangun oleh Fakultas Teknik sebagai UPPS dan Prgram Studi TM,  khusunya dengan berbagai universitas lain/stakeholder di tingkat lokal, nasional dan internasional. Kerjasama tersebut meliputi kegiatan Tri Dharma Perguruan Tinggi yaitu kegiatan pendidikan, pengabdian dan penelitian. Bukti pendukung kegiatan kerjasama  adalah SPK. 1) Ada penjelasan ttg manfaat kerjasama antara lain meningkatkan hubungan kelembagaan dan kemitraan, membantu dalam melaksanakan kegiatan pendidikan dan uji tes di lapangan, kegiatan tridarma dalam bidang TM; 2) peningkatan kinerja tridharma berupa fasilitas uji tes; 3) belum ada evaluasi kepauasan kepada mitra industri/kerjasama. \nPenjelasn aspek manfaat masin normatif. Perlu dikonfirmasi.', 'Terdapat 12 Kerjasama yang sudah dibangun oleh Fakultas Teknik sebagai UPPS dan Prgram Studi TM,  khusunya dengan berbagai universitas lain/stakeholder di tingkat lokal, nasional dan internasional. Kerjasama tersebut meliputi kegiatan Tri Dharma Perguruan Tinggi yaitu kegiatan pendidikan, pengabdian dan penelitian. Bukti pendukung kegiatan kerjasama  adalah SPK. 1) Ada penjelasan ttg manfaat kerjasama antara lain meningkatkan hubungan kelembagaan dan kemitraan, membantu dalam melaksanakan kegiatan pendidikan dan uji tes di lapangan, kegiatan tridarma dalam bidang TM; 2) peningkatan kinerja tridharma berupa fasilitas uji tes; 3) belum ada evaluasi kepauasan kepada mitra industri/kerjasama. \nPada AL, dikonfirmasi manfaat kerjasama adalah penelitian bersama, pemanfaatan sapras mitra untuk praktikum, pelaksanaan KKN tematik.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22882, 96, '10', 'A. Kerjasama pendidikan, penelitian dan PkM yang relevan dengan program studi dan dikelola oleh UPPS dalam 3 tahun terakhir.\nB. Kerjasama tingkat internasional, nasional, wilayah/lokal yang relevan dengan program studi dan dikelola oleh UPPS dalam 3 tahun terakhir.\nTabel 1 LKPS\nTabel 3.a.1 LKPS', 'Dari tabel 1 LKPS, terlihat jumlah kerjasama adalah sbb: N1= pendidikan=12, N2=penelitian=12 dan, N3= pengabdian kepada masyarakat=11, sedangkan jumlah dosen tetap NDTPS=8, sehingga RK=6.45. Sedangkan tingkat kerjasama adalah tingkat lokal/wilayah (6), nasioinal (5) dan 1 kerjasama internasional. Akan diverifikasi saat AL.', 'Dari tabel 1 LKPS, terlihat jumlah kerjasama adalah sbb: N1= pendidikan=12, N2=penelitian=12 dan, N3= pengabdian kepada masyarakat=11, sedangkan jumlah dosen tetap NDTPS=8, sehingga RK=6.45. Sedangkan tingkat kerjasama adalah tingkat lokal/wilayah (6), nasioinal (5) dan 1 kerjasama internasional. \nPada AL, data terverifikasi didukung dokumen MoU dan laporan kegiatan.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22883, 96, '11', 'C.2.5 Indikator Kinerja Tambahan\nPelampauan SN-DIKTI yang ditetapkan dengan indikator kinerja tambahan yang berlaku di UPPS berdasarkan standar pendidikan tinggi yang ditetapkan perguruan tinggi pada tiap kriteria.', 'UPPS telah menetapkan indikator kinerja tambahan pada seluruh kriteria yang menunjukkan daya saing di tingkat nasional, antara lain terlaksananya pengelolaan adm pendidikan d Univ, keaktifan mahasiswa di bid non akademik, target 40% dosen berprestasi dalam luaran tridarma.. Tidak semua indikator kinerja tambahan memiliki indikator kinerja yang dapat diukur. Ada evaluasi capaian kinerja yang dilakukan, yang dilengkapi dengan informasi identifikasi akar masalah, faktor pendukung dan penghampat ketrecapaian.', 'UPPS telah menetapkan indikator kinerja tambahan pada seluruh kriteria yang menunjukkan daya saing di tingkat nasional, antara lain terlaksananya pengelolaan adm pendidikan d Univ, keaktifan mahasiswa di bid non akademik, target 40% dosen berprestasi dalam luaran tridarma. Tidak semua indikator kinerja tambahan memiliki indikator kinerja yang dapat diukur. Ada evaluasi capaian kinerja yang dilakukan, yang dilengkapi dengan informasi identifikasi akar masalah, faktor pendukung dan penghambat ketercapaian.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22884, 96, '12', 'C.2.6 Evaluasi Capaian Kinerja\nAnalisis keberhasilan dan/atau ketidakberhasilan pencapaian kinerja UPPS yang telah ditetapkan di tiap kriteria memenuhi 2 aspek sebagai berikut: 1) capaian kinerja diukur dengan metoda yang tepat, dan hasilnya dianalisis serta dievaluasi, dan 2) analisis terhadap capaian kinerja mencakup identifikasi akar masalah, faktor pendukung keberhasilan dan faktor penghambat ketercapaian standard, dan deskripsi singkat tindak lanjut yang akan dilakukan.', 'Ada evaluasi capaian kinerja yang dilakukan, yang dilengkapi dengan informasi identifikasi akar masalah, faktor pendukung dan penghampat ketrecapaian. Belum ada informasi metode pengukuran dan analisis keberhasilan dan/atau ketidakberhasilan yang dilakukan. Belum ada informasi publikasi hasil analisis yang dilakukan.', 'Ada evaluasi capaian kinerja yang dilakukan, yang dilengkapi dengan informasi identifikasi akar masalah, faktor pendukung dan penghambat ketercapaian. \nPada AL, dikonfirmasi pengukuran capaian program termuat dalam dokumen Renop menggunakan perhitungan capaian terhadap target.\nPublikasi ke sivitas akademika dilakukan di dalam Rapat Yudisium untuk kinerja dosen terbaik, ada penghargaan reward untuk dosen sesuai SK Rektor.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22885, 96, '13', 'C.3. Mahasiswa\nC.3.4 Indikator kinerja Utama\nC.3.4.a) Kualitas Input Mahasiswa\nMetoda rekrutmen dan keketatan seleksi', 'Dari tabel 2.a LKPS terlihat jumlah calon mhs yang ikut seleksi=NA=89, dan yg lulus seleksi NB=89, Rasio=1', 'Dari tabel 2.a LKPS terlihat jumlah calon mhs yang ikut seleksi=NA=89, dan yg lulus seleksi NB=89, Rasio=1\nPada AL, tersedia dokumen PMB, SK PMB, dokumen ujian dan SOP PMB.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22886, 96, '14', 'C.3.4.b) Daya Tarik Program Studi\nA. Peningkatan animo calon mahasiswa.\nTabel 2.a.1 LKPS\nB. Mahasiswa asing\nTabel 2.b LKPS', 'A) Dari LKPS terlihat jumlah calon yang mendaftar adalah sbb: pd TS-2= 24, pd TS-1= 19, dan pada TS=17. Artinya mengalami penurunan selama 3 tahun terakhir. Upaya yang dilakukan untuk meningkatkan animo sebagai tindak lanjut, yaitu Meningkatkan sosialisasi program studi teknik mesin Universitas Garuda lebih intensif melalui media sosial, alumni dan mahasiswa PS,  Kegiatan himpunan yang ada diluar kampus dan road show ke SMA/MA/SMK, Meningkatkan jumlah layanan kepada mahaiswa untuk minat dan bakat, Meningkatkan sarana dan prasarana pada bidang akademik maupun non akademik   \r\nB)  Tidak ada mahasiswa asing.\r\nData pada LKPS berbeda dengan LED, perlu dikonfirmasi. ', 'A) Dari LKPS terlihat jumlah calon yang mendaftar adalah sbb: pd TS-2= 24, pd TS-1= 19, dan pada TS=17. Artinya mengalami penurunan selama 3 tahun terakhir. Upaya yang dilakukan untuk meningkatkan animo sebagai tindak lanjut, yaitu Meningkatkan sosialisasi program studi teknik mesin Universitas Garuda lebih intensif melalui media sosial, alumni dan mahasiswa PS,  Kegiatan himpunan yang ada diluar kampus dan road show ke SMA/MA/SMK, Meningkatkan jumlah layanan kepada mahaiswa untuk minat dan bakat, Meningkatkan sarana dan prasarana pada bidang akademik maupun non akademik   \r\nB)  Tidak ada mahasiswa asing.\r\nPada AL, data terkonfirmas sesuai LKPS.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22887, 96, '15', 'C.3.4.c) Layanan Kemahasiswaan\nA. Ketersediaan layanan kemahasiswaan di bidang: 1) penalaran, minat dan bakat, 2) kesejahteraan (bimbingan dan konseling, layanan beasiswa, dan layanan kesehatan), dan 3) bimbingan karir dan kewirausahaan.\nB. Akses dan mutu layanan kemahasiswaan.', 'A) Jenis layanan yang tersedia mencakup Layanan bimbingan konseling dengan dosen PA, dosen pembimbing KP dan Skripsi, dan pendamping kegiatan kelembagaan.\nTidak ada informasi layanan minat bakat, layanan beasiswa, layanan kesehatan, layanan bimbingan karir dan kewirausahaan.\nB) Layanan bimbingan dan konseling dapat diaksaes dengan mudah.', 'A) Jenis layanan yang tersedia mencakup Layanan bimbingan konseling dengan dosen PA, dosen pembimbing KP dan Skripsi, dan pendamping kegiatan kelembagaan.\nB) Layanan bimbingan dan konseling dapat diakses dengan mudah.\nPada AL, dikonfirmasi tersedia layanan minat bakat dengan adanya UKM Seni dan Fotografi, Tari, Scrubble; tersedia Layanan Beasiswa : KIP, beasiswa Dhuafa, Supersemar dan Beasiswa Tahfidz; tersedia layanan kesehatan dengan adanya UKS yang dilayani oleh Bidan; layanan bimbingan karir di bawah koordinasi WR3 mengenai informasi lowongan pekerjaan setiap semester, bursa kerja; dan layanan kewirausahaan di bawah koordinasi WR3 (ada bukti kegiatan pelatihan kuliner untuk calon wirausaha, pelatihan teknis servis kendaraan).\nSeluruh layanan sudah dikonfirmasi ketersediaan dan akses oleh mahasiswa pada saat wawancara dengan mahasiswa.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22888, 96, '16', 'C.4. Sumber Daya Manusia\nC.4.4. Indikator Kinerja Utama\nC.4.4.a) Profil Dosen\nKecukupan jumlah DTPS.\nTabel 3.a.1) LKPS', 'Dari LPKS terlihat jumlah dosen tetap yang ditugaskan sbg pengampu mata kuliah sesuai bidang keahlian PS yang diakreditasi DTPS= 8 dari 15 dosen tetap. DTPS tersebut adalah Ari Beni, M. Thohirin, Agus A., Kemas MA, M. Yunus, Indriyani, Wisnaningsih dan Refi Arioen. Tidak ada dosen tidak tetap.', 'Dari LPKS terlihat jumlah dosen tetap yang ditugaskan sbg pengampu mata kuliah sesuai bidang keahlian PS yang diakreditasi DTPS= 8 dari 15 dosen tetap. DTPS tersebut adalah Ari Beni, M. Thohirin, Agus A., Kemas MA, M. Yunus, Indriyani, Wisnaningsih dan Refi Arioen. Tidak ada dosen tidak tetap. \nPada AL, data terkonfirmasi.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22889, 96, '17', 'Kualifikasi akademik DTPS.\nTabel 3.a.1) LKPS', 'Dari LPKS terlihat jumlah dosen tetap  bergelar S3 sebanyak 3 orang, dengan bidang keahlian hukum, manajemen dan ilmu pertanian. Dari bidang keahlian ini yang sesuai dengan kompetensi PS hanya 1 orang an Dr. Refi Arioen.', 'Dari LPKS terlihat jumlah dosen tetap  bergelar S3 sebanyak 3 orang, dengan bidang keahlian hukum, manajemen dan ilmu pertanian. Dari bidang keahlian ini yang sesuai dengan kompetensi PS hanya 1 orang an Dr. Refi Arioen.\nPada AL, data terverifikasi.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22890, 96, '18', 'Jabatan akademik DTPS.\nTabel 3.a.1) LKPS', 'Dari 8 DTPS, dosen dengan jabatan akademik Lektor sebanyak 3 orang dan 1 orang Lektor Kepala.', 'Dari 8 DTPS, dosen dengan jabatan akademik Lektor sebanyak 3 orang dan 1 orang Lektor Kepala.\nPada AL, data terverifikasi.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22891, 96, '19', 'Rasio jumlah mahasiswa program studi terhadap jumlah DTPS.\nTabel 2.a.1) LKPS\nTabel 3.a.1) LKPS', 'Jumlah mahasiswa pada TS=NM=81, sedangkan DTPS=8, sehingga rasio mahasiswa dengan dosen = 6.38. Perlu konfirmasi jumlah mahasiswa transfer 30 orang.', 'Jumlah mahasiswa pada TS=NM=81, sedangkan DTPS=8, sehingga rasio mahasiswa dengan dosen = 6.38. Pada AL, sudah dikonfirmasi jumlah mahasiswa transfer 30 orang pada TS dengan seleksi PMB sesuai ketentuan.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22892, 96, '20', 'Penugasan DTPS sebagai pembimbing utama tugas akhir mahasiswa.\nTabel 3.a.2) LKPS ', 'Rata-rata jumlah mhs yang dibimbing sebagai pembimbing utama TA = 0.42. Perlu konfirmasi DTPS.', 'Rata-rata jumlah mhs yang dibimbing sebagai pembimbing utama TA = 0.42. Data terverifikasi, ada dokumen SK Pembimbing dan Bukti kegiatan pembimbingan.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22893, 96, '21', 'Ekuivalensi Waktu Mengajar Penuh DTPS.\nTabel 3.a.3) LKPS', 'Rata-rata EWMP DTPS pd TS=12.18 dengan DTPS berjumlah 8 orang.', 'Rata-rata EWMP DTPS pd TS=12.18 dengan DTPS berjumlah 8 orang.\nPada AL, data terverifikasi.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22894, 96, '22', 'Dosen tidak tetap.\nTabel 3.a.4) LKPS', 'Tidak ada dosen tidak tetap yang ditugaskan mengampu MK PS.', 'Tidak ada dosen tidak tetap yang ditugaskan mengampu MK PS.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22895, 96, '23', 'C.4.4.b) Kinerja Dosen\nPengakuan/rekognisi atas kepakaran/prestasi/kinerja DTPS.\nTabel 3.b.1) LKPS', 'Disebutkan dalam LKPS, dari 8 DTPS terdapat 18 rekognisi dalam 3 tahun terakhir. Rekognisi tersebut antara lain sebagai keynote speaker, staf ahli, editor atau mitra bestari. Perlu cek dokumen.', 'Disebutkan dalam LKPS, dari 8 DTPS terdapat 18 rekognisi dalam 3 tahun terakhir. Rekognisi tersebut antara lain sebagai keynote speaker, staf ahli, editor atau mitra bestari.\nPada AL, data terverifikasi dilengkapi bukti dokumen sertifikat.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22896, 96, '24', 'Kegiatan penelitian DTPS yang relevan dengan bidang program studi dalam 3 tahun terakhir.\nTabel 3.b.2) LKPS', 'Jumlah penelitian 8 DTPS dalam 3 tahun terakhir adalah sbb: Biaya luar negeri NI=0, biaya dalam negeri NN=2, dan biaya PT/Mandiri NL=66.\nData LKPS berbeda dengan LED (biaya dalam negeri = 1), perlu konfirmasi.\nCek dokumen pada AL.\n', 'Jumlah penelitian 8 DTPS dalam 3 tahun terakhir adalah sbb: Biaya luar negeri NI=0, biaya dalam negeri NN=2, dan biaya PT/Mandiri NL=66.\nData LKPS berbeda dengan LED (biaya dalam negeri = 1).\nPada AL, data terverifikasi penelitian dengan biaya dalam negeri = 2 dengan bukti dokumen kontrak peneltian dan publikasi.\n', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22897, 96, '25', 'Kegiatan PkM DTPS yang relevan dengan bidang program studi dalam 3 tahun terakhir.\nTabel 3.b.3) LKPS', 'Jumlah kegiatan PkM 8 DTPS dalam 3 tahun terakhir adalah sbb: Biaya luar negeri NI=0, biaya dalam negeri NN=2, dan biaya PT/mandiri NL=45.\nData LKPS berbeda dengan LED (biaya dalam negeri = 0), perlu konfirmasi.\nCek dokumen pada AL.', 'Jumlah kegiatan PkM 8 DTPS dalam 3 tahun terakhir adalah sbb: Biaya luar negeri NI=0, biaya dalam negeri NN=2, dan biaya PT/mandiri NL=45.\nPada AL, data terverifikasi PkM dengan biaya dalam negeri = 2 dengan bukti dokumen kontrak kegiatan PkM dan laporan kegiatan.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22898, 96, '26', 'Publikasi ilmiah dengan tema yang relevan dengan bidang program studi yang dihasilkan DTPS dalam 3 tahun terakhir.\nTabel 3.b.4) LKPS', 'Jumlah publikasi 8 DTPS dalam 3 tahun terakhir adalah sbb: di jurnal nasional tidak terakreditasi NA1=43, di jurnal nasional terakreditasi NA2=14, di jurnal internasional NA3=10, di jurnal internasional bereputasi NA4=0. Jumlah publikasi di seminar adalah sbb:  wilayah/lokal NB1=0, nasional NB2=6, internasional NB3=2. Jumlah tulisan di media massa sbb: wilayah NC1=1, nasional NC2=0, dan internasional NC3=0.\nPerlu cek dokumen.', 'Jumlah publikasi 8 DTPS dalam 3 tahun terakhir adalah sbb: di jurnal nasional tidak terakreditasi NA1=43, di jurnal nasional terakreditasi NA2=14, di jurnal internasional NA3=10, di jurnal internasional bereputasi NA4=0. Jumlah publikasi di seminar adalah sbb:  wilayah/lokal NB1=0, nasional NB2=6, internasional NB3=2. Jumlah tulisan di media massa sbb: wilayah NC1=1, nasional NC2=0, dan internasional NC3=0.\nPada AL, data terverifikasi. Ada peningkatan publikasi jurnal nasional terakreditasi menjadi 18 pada TS karena jurnal internal telah terakreditasi SInta 5 mulai tahun 2019.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22899, 96, '27', 'Artikel karya ilmiah DTPS yang disitasi dalam 3 tahun terakhir.\nTabel 3.b.6) LKPS', 'Dari 8 DTPS, terdapat 10 judul artikel yang disitasi.\nPerlu cek dokumen. ', 'Dari 8 DTPS, terdapat 10 judul artikel yang disitasi.\nPada AL, data terverifikasi dengan bukti dokumen lengkap.', NULL, NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22900, 96, '28', 'Luaran penelitian dan PkM yang dihasilkan DTPS dalam 3 tahun terakhir.\nTabel 3.b.8) LKPS', 'Dari 8 DTPS, luaran penelitian dan PkM dalam 3 tahun terakhir adalah sbb:  NA=19 paten, NB=0, Teknologi tepat guna/karya seni/poduk NC= 0, dan Buku berISBN, Book chapter ND=11. \nPerlu konfirmasi Paten termasuk skripsi. Akan diverifikasi saat AL.', 'Pada AL terverifikasi data : dari 8 DTPS, luaran penelitian dan PkM dalam 3 tahun terakhir adalah sbb:  NA=0, NB=19 HKI (skripsi-HKI), Teknologi tepat guna/karya seni/poduk NC= 0, dan Buku berISBN, Book chapter ND=11. \n', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22901, 96, '29', 'C.4.4.c) Pengembangan Dosen\nUpaya pengembangan dosen.', 'Upaya pengembangan dosen tercantum dalam rencana strategis Unit Pengelola Program Studi, yaitu kewajiban dosen yang mengajar diwajibkan memiliki kepangkatan akademik dan NIDN, sertifikasi dosen dan beasiswa bagi dosen studi lanjut S3.', 'Upaya pengembangan dosen tercantum dalam rencana strategis Unit Pengelola Program Studi, yaitu kewajiban dosen yang mengajar diwajibkan memiliki kepangkatan akademik dan NIDN, sertifikasi dosen dan beasiswa bagi dosen studi lanjut S3. Pada AL, ada rekomendasi studi lanjut S3 dari Rektor.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22902, 96, '30', 'C.4.4.d) Tenaga Kependidikan\nA. Kualifikasi dan kecukupan tenaga kependidikan berdasarkan jenis pekerjaannya (administrasi, pustakawan, teknisi, dll.)\nB. Kualifikasi dan kecukupan laboran untuk mendukung proses pembelajaran sesuai dengan kebutuhan program studi.\n', 'A) Jumlah total tenaga kependidikan di PS  adalah 14 orang, terdiri dari 1 orang berpendidikan S2 sebagai Ka.Lab Fakultas, 10 orang berpendidikan S1 (1 pustawakan, 6 laboran dan 3 tenaga administrasi), 2 orang teknisi lab dari SMA/SMK dan 1 orang OB.  Jumlah keseluruhan tersebut cukup. B) Laboran PSTM ada 6 orang, seluruhnya S1.\nBelum ada informasi tendik di UPPS.', 'A) Jumlah total tenaga kependidikan di PS  adalah 14 orang, terdiri dari 1 orang berpendidikan S2 sebagai Ka.Lab Fakultas, 10 orang berpendidikan S1 (1 pustawakan, 6 laboran dan 3 tenaga administrasi), 2 orang teknisi lab dari SMA/SMK dan 1 orang OB.  Jumlah keseluruhan tersebut cukup. B) Laboran PSTM ada 6 orang, seluruhnya S1.\nPada AL, dikonfirmasi data tendik adalah di UPPS yang juga melayani PS. \nLaboran TM memiliki sertifikasi kompetensi sebagai Juru Las dari BNSP dan laboran TS memiliki sertifikasi teknisi lab beton.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22903, 96, '31', 'C.5. Keuangan, Sarana dan Prasarana\nC.5.4. Indikator Kinerja Utama\nC.5.4.a) Keuangan\nBiaya operasional pendidikan.\nTabel 4.a LKPS', 'Rata-rata biaya operasional pendidikan dalam 3 tahun BOP= Rp.1128682600 , sedangkan jumlah mhs pada TS=81, sehigga DOP=13.9 juta.', 'Rata-rata biaya operasional pendidikan dalam 3 tahun BOP= Rp.1128682600 , sedangkan jumlah mhs pada TS=81, sehigga DOP=13.9 juta.\nPada AL, data terverifikasi. Tersedia dokumen laporan keuangan.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22904, 96, '32', 'Dana penelitian DTPS.\nTabel 4.a LKPS', 'Rata-rata jumlah dana penelitian yg diperoleh 8 DTPS dlm 3 tahun terakhir DP= Rp.133,3 juta, sehingga rata-rata dana penelitian DTPS per tahun= Rp. 16,67 juta. Perlu konfirmasi.', 'Rata-rata jumlah dana penelitian yg diperoleh 8 DTPS dlm 3 tahun terakhir DP= Rp.133,3 juta, sehingga rata-rata dana penelitian DTPS per tahun= Rp. 16,67 juta. Pada AL, data terverifikasi.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22905, 96, '33', 'Dana pengabdian kepada masyarakat DTPS.\nTabel 4.a LKPS', 'Rata-rata jumlah dana PkM yg diperoleh 8 DTPS dlm 3 tahun terakhir DPkM= Rp. 66 juta, sehingga rata-rata dana PkM DTPS per tahun= Rp. 8,3 juta.', 'Rata-rata jumlah dana PkM yg diperoleh 8 DTPS dlm 3 tahun terakhir DPkM= Rp. 66 juta, sehingga rata-rata dana PkM DTPS per tahun= Rp. 8,3 juta.\nPada AL, data terverifikasi.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22906, 96, '34', 'Realisasi investasi (SDM, sarana dan prasarana) yang mendukung penyelenggaraan tridharma.', 'Penggunaan dana untuk investasi pada PS rata-rata selama 3 tahun terakhir adalah Rp. 69 juta. Lab yang tersedia ada 4 lab. Belum ada informasi target investasi yang direncanakan. ', 'Penggunaan dana untuk investasi pada PS rata-rata selama 3 tahun terakhir adalah Rp. 69 juta. Lab yang tersedia ada 4 lab. Pada AL, ada informasi target investasi yang direncanakan yang tertuang dalam Statuta dan Renstra (Investasi SDM dan Sapras berupa pengembangan Lab).', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22907, 96, '35', 'Kecukupan dana untuk menjamin pencapaian capaian pembelajaran.', 'Semua sumber dana diperoleh dari Yayasan dengan mekanisme pelaporan secara tertulis. Usulan kebutuhan anggaran dari unversitas, fakultas atau lembaga secara tertulis sesuai dengan program kerja. Pengadaan sumber dana dilakukan oleh Yayasan atas usul dari rektor. Pimpinan Univ diperkenankan mencari dan menerima sumbangan dari pihak lain dengan persetujuan Yayasan, yang dikelola dan ditetapkan dalam rapat kerja kemudian dialokasikan kepada Program Studi Teknik Mesin sesuai mekanisme yang diatur oleh surat keputusan Yayasan. Dengan rata-rata BOP 22 juta, mencukupi untuk mendukung proses pembelajaran.', 'Semua sumber dana diperoleh dari Yayasan dengan mekanisme pelaporan secara tertulis. Usulan kebutuhan anggaran dari unversitas, fakultas atau lembaga secara tertulis sesuai dengan program kerja. Pengadaan sumber dana dilakukan oleh Yayasan atas usul dari rektor. Pimpinan Univ diperkenankan mencari dan menerima sumbangan dari pihak lain dengan persetujuan Yayasan, yang dikelola dan ditetapkan dalam rapat kerja kemudian dialokasikan kepada Program Studi Teknik Mesin sesuai mekanisme yang diatur oleh surat keputusan Yayasan. Dengan rata-rata BOP 22 juta, mencukupi untuk mendukung proses pembelajaran.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22908, 96, '36', 'C.5.4.b) Sarana dan Prasarana\nKecukupan, aksesibilitas dan mutu sarana dan prasarana untuk menjamin pencapaian capaian pembelajaran dan meningkatkan suasana akademik.\nTabel 4.b LKPS\nTabel 4.c LKPS\n', 'Sarana penunjang pendidikan program studi Sarjana Teknik Mesin terdiri atas 4 laboratorium, yaitu Lab Manufaktur, Lab Tugas Elemen, Lab Prestasi Mesin dan Lab Komputer. Juga terdapat ruang baca, ruang kelas, ruang lab bahasa Inggris, ruang Ka. Lab.', 'Sarana penunjang pendidikan program studi Sarjana Teknik Mesin terdiri atas 4 laboratorium, yaitu Lab Manufaktur, Lab Tugas Elemen, Lab Prestasi Mesin dan Lab Komputer. Juga terdapat ruang baca, ruang kelas, ruang lab bahasa Inggris, ruang Ka. Lab.\nPada AL, terverifikasi ketersediaan sarana prasarana yang menjamin capaian pembelajaran dan meningkatkan suasana akademik.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22909, 96, '37', 'C.6. Pendidikan\nC.6.4. Indikator Kinerja Utama\nC.6.4.a) Kurikulum\nA. Keterlibatan pemangku kepentingan dalam proses evaluasi dan pemutakhiran kurikulum.\nB. Kesesuaian capaian pembelajaran dengan profil lulusan dan jenjang KKNI/SKKNI.\nC. Ketepatan struktur kurikulum dalam pembentukan capaian pembelajaran.', 'A) Kurikulum program studi dilakukan pemutakhiran setiap 5 tahun sekali, yang dilakukan oleh tim pengembang kurikulum program studi dan Fak dengan mengundang dosen, stakeholder untuk informasi perkembangan IPTEK, dan direview pakar.\nBelum ada informasi pemutakhiran terakhir yang dilakukan.\nPerlu dikonfirmasi pakar yang dilibatkan.\nB) Kurikulum program studi Sarjana Teknik Mesin disusun dengan mengacu pada profil lulusan yang ditetapkan berdasarkan KKNI Level 6 dan SN-Dikti.\nBelum ada informasi keberkalaan pemutakhiran CPL. Perlu dikonfirmasi.\nC) Pada Tabel 5a-1,  semua MK pada struktur kurikulum memuat CPL, namun belum ada informasi peta kurikulum yang menunjukkan pemenuhan dan keterkaitan CPL dengan CPMK.', 'A) Kurikulum program studi dilakukan pemutakhiran setiap 5 tahun sekali, yang dilakukan oleh tim pengembang kurikulum program studi dan Fak dengan mengundang dosen, stakeholder untuk informasi perkembangan IPTEK, dan direview pakar.\r\nPada AL, terkonfirmasi bahwa pakar dilibatkan dalam pemutahkiran kurikulum. Ada rapat lokakarya pembahasan perubahan kurikulum, ada dokumentasi dan SK Rektor:10/021/003/R/KPTS/VIII/KP/2020.  Pakar yang terlibat: Dr. Panca Indra , St, MSc. (UNISUTENG/Sipil, topik tentang Kampus Merdeka).  Perwakilan Organisasi Profesi ada yang hadir dalam lokakarya perubahana kurikulum, berdasarkan data kehadiran peserta, data anggota profesi yang hadir adalah sebagai berikut: Pertahkindo (Persatuan konsultan Indonesia) Barak Obama dan Bill Clinton, peserta Dinas Balai Latihan Kerja, Bambang Pamungkas, peserta. Peserta memberi masukkan terkait perubahan kurikulum yang diperlukan.\r\nB) Kurikulum program studi Sarjana Teknik Mesin disusun dengan mengacu pada profil lulusan yang ditetapkan berdasarkan KKNI Level 6 dan SN-Dikti.\r\nPada AL, Bukti ditunjukkan dalam RPS mata kuliah.\r\nC) Pada Tabel 5a-1,  semua MK pada struktur kurikulum memuat CPL, namun belum ada informasi peta kurikulum yang menunjukkan pemenuhan dan keterkaitan CPL dengan CPMK.\r\nHasil konfirmasi menunjukkan ada beberapa mata kuliah yang dalam RPS nya menunjukkan keterkaitan anata CPL dan CPMK, tetapi keterkaitan antara CPL dan CPMK untuk keseluruhan mata kuliah di PS belum tersedia.\r\n', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22910, 96, '38', 'C.6.4.b) Karakteristik Proses Pembelajaran\nPemenuhan karakteristik proses pembelajaran, yang terdiri atas sifat: 1) interaktif, 2) holistik, 3) integratif, 4) saintifik, 5) kontekstual, 6) tematik, 7) efektif, 8) kolaboratif, dan 9) berpusat pada mahasiswa.\n', 'Tidak ada informasi pemenuhan pemenuhan karakteristik proses pembelajaran, yang terdiri atas sifat: 1) interaktif, 2) holistik, 3) integratif, 4) saintifik, 5) kontekstual, 6) tematik, 7) efektif, 8) kolaboratif, dan 9) berpusat pada mahasiswa.', 'Tidak ada informasi pemenuhan pemenuhan karakteristik proses pembelajaran, yang terdiri atas sifat: 1) interaktif, 2) holistik, 3) integratif, 4) saintifik, 5) kontekstual, 6) tematik, 7) efektif, 8) kolaboratif, dan 9) berpusat pada mahasiswa.\nTerkonfirmasi hanya ada beberapa unsur yang terpenuhi, seperti pada mata kuliah Rekayasa Mutu sudah menerapakan Problem Based Learning (PBL).', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22911, 96, '39', 'C.6.4.c) Rencana Proses Pembelajaran\nA. Ketersediaan dan kelengkapan dokumen rencana pembelajaran semester (RPS)\nB. Kedalaman dan keluasan RPS sesuai dengan capaian pembelajaran lulusan.', 'A). Pada LED hal 93 dan Tabel 5a-1 LKPS disebutkan bahwa seluruh MK dilengkapi dengan silabus dan RPS yang selalu dimutakhirkan. Namun tidak ada informasi kelengkapan RPS mencakup target capaian pembelajaran, bahan kajian, metode pembelajaran, waktu dan tahapan, asesmen hasil capaian pembelajaran.\nB) Belum ada informasi isi materi pembelajaran sesuai dengan RPS, dan memiliki kedalaman dan keluasan yang relevan untuk mencapai capaian pembelajaran lulusan.\nPerlu konfirmasi.', 'A). Pada LED hal 93 dan Tabel 5a-1 LKPS disebutkan bahwa seluruh MK dilengkapi dengan silabus dan RPS yang selalu dimutakhirkan. Namun tidak ada informasi kelengkapan RPS mencakup target capaian pembelajaran, bahan kajian, metode pembelajaran, waktu dan tahapan, asesmen hasil capaian pembelajaran.\nB) Pada LED belum ada informasi isi materi pembelajaran sesuai dengan RPS, dan memiliki kedalaman dan keluasan yang relevan untuk mencapai capaian pembelajaran lulusan.\nHasil konfirmasi di lapangan, sekitar 31 mata kuliah dari 74 mata kuliah sudah memiliki RPS. Dalam beberapa RPS terkonfirmasi ada kedalaman materi berupa studi kasus dan PBL.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22912, 96, '40', 'C.6.4.d) Pelaksanaan Proses Pembelajaran\nA. Bentuk interaksi antara dosen, mahasiswa dan sumber belajar\nB. Pemantauan kesesuaian proses terhadap rencana pembelajaran\nC. Proses pembelajaran yang terkait dengan penelitian harus mengacu SN Dikti Penelitian: 1) hasil penelitian: harus memenuhi pengembangan IPTEKS, meningkatkan kesejahteraan masyarakat, dan daya saing bangsa. 2) isi penelitian: memenuhi kedalaman dan keluasan materi penelitian sesuai capaian pembelajaran. 3) proses penelitian: mencakup perencanaan, pelaksanaan, dan pelaporan. 4) penilaian penelitian memenuhi unsur edukatif, obyektif, akuntabel, dan transparan.\nD. Proses pembelajaran yang terkait dengan PkM harus mengacu SN Dikti PkM: 1) hasil PkM: harus memenuhi pengembangan IPTEKS, meningkatkan kesejahteraan masyarakat, dan daya saing bangsa. 2) isi PkM: memenuhi kedalaman dan keluasan materi PkM sesuai capaian pembelajaran. 3) proses PkM:  mencakup perencanaan, pelaksanaan, dan pelaporan. 4) penilaian PkM memenuhi unsur edukatif, obyektif, akuntabel, dan transparan.\nE. Kesesuaian metode pembelajaran dengan capaian pembelajaran. Contoh: RBE (research based education), IBE (industry based education), teaching factory/teaching industry, dll.', 'A) Interaksi dosen dengan mahasiswa dalam perkuliahan, bimbingan akademik/konseling, bimbingan tugas perancangan, bimbingan kerja praktek dan bimbingan skripsi/TA. Selain itu ada interaksi dosen melibatkan mahasiswa untuk membantu dalam praktikum maupun penelitian. \nB) Monitoring dan evaluasi (monev) proses belajar mengajar pada PS dilakukan sesuai dengan Peraturan Akademik Universitas  serta RPS. \nBelum disebutkan dokumen yang mendukung kegiatan. Perlu konfirmasi.\nC) Proses pembelajaran yang terkait dengan penelitian dijalankan dengan pelaksanaan penelitian oleh dosen dan mahsiswa. \nPerlu konfirmasi dokumen yang mendukung proses pembelajaran. \nD) Belum ada informasi Integrasi pembelajaran dengan PkM.\nE) Belum ada informasi kesesuaian metode pembelajaran dengan capaian pembelajaran.', 'A) Interaksi dosen dengan mahasiswa dalam perkuliahan, bimbingan akademik/konseling, bimbingan tugas perancangan, bimbingan kerja praktek dan bimbingan skripsi/TA. Selain itu ada interaksi dosen melibatkan mahasiswa untuk membantu dalam praktikum maupun penelitian. \nB) Monitoring dan evaluasi (monev) proses belajar mengajar pada PS dilakukan sesuai dengan Peraturan Akademik Universitas  serta RPS. \nPada LED belum disebutkan dokumen yang mendukung kegiatan.\nC) Proses pembelajaran yang terkait dengan penelitian dijalankan dengan pelaksanaan penelitian oleh dosen dan mahsiswa. \nD) Pada LED belum ada informasi Integrasi pembelajaran dengan PkM.\nE) Pada LED belum ada informasi kesesuaian metode pembelajaran dengan capaian pembelajaran.\nHasil konfirmasi menunjukkan ada monitoring kesesuaian proses belajar mengajar oleh PS berupa dokumen checklist perkuliahan tiap minggu yang diperiksa oleh Kaprodi dan diketahui oleh Dekan.  Bukti keterlibatan mahasiswa dalam penelitian mahasiswa, dibuktikan dengan makalah dalam jurnal yang melibatkan mahasiswa dan dosen sebagai author (jumlah sesuai dengan table LKPS).\nAda dokumen pengesahan RPS oleh PS, ditandatangani oleh Kaprodi dan Dekan\nAda bukti bahwa penelitian dosen mendukung proses pembelajaran dan integrasi antara pembelajaran dengan PKM.\nAda pembuktian kesesuaian metode pembelajaran dengan capaian pembelajaran.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22913, 96, '41', 'Pembelajaran yang dilaksanakan dalam bentuk praktikum, praktik studio, praktik bengkel, atau praktik lapangan.\nTabel 5.a.1) LKPS', 'Jumlah sks pembelajaran praktikum, praktik studio, praktik bengkel, atau praktek lapangan (termasuk KKN) = 25 sedangkan jumlah sks pembelajaran total selama masa pendidikan= 144. \nData diisi dalam sks, perlu dikonfirmasi jumlah total jam belajar perkuliahan dan jam praktikum/praktek', 'Jumlah sks pembelajaran praktikum, praktik studio, praktik bengkel, atau praktek lapangan (termasuk KKN) = 24 sks, sedangkan jumlah sks pembelajaran total selama masa pendidikan= 144 sks.\nPada AL, sudah terkonfirmasi jam praktikum, praktik studio, praktik bengkel atau praktek lapangan termasuk KKN, sebesar 23.3 jam dari total 173.3 jam.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22914, 96, '42', 'C.6.4.e) Monitoring dan Evaluasi Proses Pembelajaran\nMonitoring dan evaluasi pelaksanaan proses pembelajaran mencakup karakteristik, perencanaan, pelaksanaan, proses pembelajaran dan beban belajar mahasiswa untuk memperoleh capaian pembelajaran lulusan.', 'Pelaksanaan monitoring yang dilakukan dengan cara mengumpulkan data untuk melihat penyimpangan dan kesenjangan dalam melakukan proses pembelajaran, meminta penjelasan, membandingkan, menelaah dokumen untuk menilai tingkat relevansi materi yang disampaikan pada saat proses pembelajaran (tatap muka) dengan RPS. UPPS dan program studi teknik mesin melakukan pemantauan, serta melaporkan hasil program pembelajaran secara periodik.\nBelum ada informasi dokumentasi terkait dan tindak lanjut.', 'Pelaksanaan monitoring yang dilakukan dengan cara mengumpulkan data untuk melihat penyimpangan dan kesenjangan dalam melakukan proses pembelajaran, meminta penjelasan, membandingkan, menelaah dokumen untuk menilai tingkat relevansi materi yang disampaikan pada saat proses pembelajaran (tatap muka) dengan RPS. UPPS dan program studi teknik mesin melakukan pemantauan, serta melaporkan hasil program pembelajaran secara periodik.\nHasil konfirmasi pada AL, ada dokumentasi monitoring proses pembelajaran yang dilakukan oleh PS melalui Berita Acara Perkuliahan yang dicheck oleh Kaprodi tentang kesesuaian anatra RPS dan proses pembelajaran dan dokumen tersebut diketahui oleh Dekan.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22915, 96, '43', 'C.6.4.f) Penilaian Pembelajaran\nA. Mutu pelaksanaan penilaian pembelajaran (proses dan hasil belajar mahasiswa) untuk mengukur ketercapaian capaian pembelajaran berdasarkan prinsip penilaian yang mencakup: 1) edukatif, 2) otentik, 3) objektif, 4) akuntabel, dan 5) transparan, yang dilakukan secara terintegrasi.\nB. Pelaksanaan penilaian terdiri atas teknik dan instrumen penilaian. Teknik penilaian terdiri dari: 1) observasi, 2) partisipasi, 3) unjuk kerja, 4) test tertulis, 5) test lisan, dan 6) angket. Instrumen penilaian terdiri dari: 1) penilaian proses dalam bentuk rubrik, dan/ atau; 2) penilaian hasil dalam bentuk portofolio, atau 3) karya disain.\nC. Pelaksanaan penilaian memuat unsur-unsur sebagai berikut: 1) mempunyai kontrak rencana penilaian, 2) melaksanakan penilaian sesuai kontrak atau kesepakatan, 3) memberikan umpan balik dan memberi kesempatan untuk mempertanyakan hasil kepada mahasiswa, 4) mempunyai dokumentasi penilaian proses dan hasil belajar mahasiswa, 5) mempunyai prosedur yang mencakup tahap perencanaan, kegiatan pemberian tugas atau soal, observasi kinerja, pengembalian hasil observasi, dan pemberian nilai akhir, 6) pelaporan penilaian berupa kualifikasi keberhasilan mahasiswa dalam menempuh suatu mata kuliah dalam bentuk huruf dan angka, 7) mempunyai bukti-bukti rencana dan telah melakukan proses perbaikan berdasar hasil monev penilaian.', 'A) Pada LED hal 91 disebutkan bahwa prinsip penilaian dilakukan secara edukatif, otentik, objektif, akuntable,dan transparan yang dilakukan secara terintegrasi. Namun belum ada informasi bukti shahih terpenuhinya 5 prinsip penilaian pembelajaran edukatif, otentik, objektif, akuntabel, dan transparan yang dilakukan secara terintegrasi untuk mengukur ketercapaian capaian pembelajaran lulusan. Belum ada informasi rubrik/portofolio penilaian. \nB) Belum ada informasi pelaksanaan penilaian dimuat dalam dokumen pedoman akademik universitas tentang teknik dan instrumen penilaian.\nC) Belum ada informasi pelaksanaan penilaian mencakup 7 unsur.', 'A) Pada LED hal 91 disebutkan bahwa prinsip penilaian dilakukan secara edukatif, otentik, objektif, akuntable,dan transparan yang dilakukan secara terintegrasi. Namun pada LED belum ada informasi bukti shahih terpenuhinya 5 prinsip penilaian pembelajaran edukatif, otentik, objektif, akuntabel, dan transparan yang dilakukan secara terintegrasi untuk mengukur ketercapaian capaian pembelajaran lulusan. Belum ada informasi pada LED mengenai rubrik/portofolio penilaian. \nB) Belum ada informasi pada LED pelaksanaan penilaian dimuat dalam dokumen pedoman akademik universitas tentang teknik dan instrumen penilaian.\nC) Belum ada informasi pada LED terkait pelaksanaan penilaian mencakup 7 unsur.\nHasil konfirmasi, ada pedoman akademik universitas/fakultas yang mengatur teknik dan instrumentasi penilaian.  Terkonfirmasi juga bahwa penilaian mencakup sebagian dari 7 unsur yang ditetapkan.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22916, 96, '44', 'C.6.4.g) Basic Sciences dan Matematika\nKetersediaan mata kuliah basic sciences dan matematika.\nTabel 5.a.3) LKPS', 'Pada Tabel 5a.3 LKPS, jumlah sks MK basic science dan matematika adalah 17 sks mencakup kimia dasar, fisika dasar, kalkulus, fisika II, matematika teknik 1, matematika teknik 2. \nPerlu konfirmasi struktur kurikulum yang digunakan pada TS, kurikulum baru atau lama.', 'Pada Tabel 5a.3 LKPS, jumlah sks MK basic science dan matematika adalah 17 sks mencakup kimia dasar, fisika dasar, kalkulus, fisika II, matematika teknik 1, matematika teknik 2. \nHasil konfirmasi, mata kuliah basic science dan matematikia adalah 22 sks dengan komposis sebagai berikut: kimia dasar (2 sks), fisika I (2 sks) , kalkulus (3 sks), fisika II (3 sks), matematika 1 (3 sks), matematika 2 (3 sks), statistik dan probabilitas 93 sks) dan metode numerik (3 sks).', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22917, 96, '45', 'C.6.4.h) Proyek rekayasa penciri bidang prodi (Capstone design)\nTerselenggaranya capstone design yang memiliki:\n1.        Panduan pelaksanaan\n2.        Memiliki rumusan  capaian pembelajaran mata kuliah \n3.        Menggunakan standar-standar keteknikan dan batasan-batasan realistis berdasarkan pada pengetahuan dan ketrampilan yang telah diperoleh di perkuliahan sebelumnya.\n4.        Mempunyai bukti sahih pelaksanaan\nTabel 5.a.4) LKPS\n', 'Pada Tabel 5a.4 LKPS, MK casptone design adalah Menggambar Teknik, Pemrograman Komputer, Menggambar Mesin, Tugas Elemen Mesin dan Tugas Akhir. Semua MK tersebut memiliki CPL sesuai Tabel 5a.1.\nTidak ada informasi panduan pelaskanaan, penggunaan standar keteknikan dan batasan realistis dan bukti shahih pelaksanaan.', 'Pada Tabel 5a.4 LKPS, MK casptone design adalah Menggambar Teknik, Pemrograman Komputer, Menggambar Mesin, Tugas Elemen Mesin dan Tugas Akhir. Semua MK tersebut memiliki CPL sesuai Tabel 5a.1.\nPada LED tidak ada informasi panduan pelaskanaan, penggunaan standar keteknikan dan batasan realistis dan bukti shahih pelaksanaan. \nTerkonfirmasi bahwa memang belum ada panduan yang jelas mengenai sistem penilaian untuk mengukur pencapaian mata kuliah caption design.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22918, 96, '46', 'C.6.4.i) Merdeka Belajar - Kampus Merdeka (MBKM)\nPelaksanaan dan jumlah SKS MBKM yang disediakan oleh UPPS dan PS\nTabel 5.b.1;  5.b.2; 5.b.3) LKPS\n', 'Pada LKPS, terdapat 13 sks perkuliahan untuk belajar di luar PS dan 2 kegiatan MBKM dengan jenis kegiatan penelitian dengan Jumlah mahasiswa yang terlibat = 2orang.', 'Pada LKPS, terdapat 13 sks perkuliahan untuk belajar di luar PS dan 2 kegiatan MBKM dengan jenis kegiatan penelitian dengan Jumlah mahasiswa yang terlibat = 2orang.\nTidak ada keterlibatan mahasiswa TS pada kegiatan perkuliahan yang ditawarkan TS pada program studi lain, hanya terkonfrmasi 2 orang mahasiswa saja yang mengikuti kegiatan MBKM dengan jenis kegiatan penelit', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22919, 96, '47', 'C.6.4.j) Integrasi kegiatan penelitian dan PkM dalam pembelajaran\nIntegrasi kegiatan penelitian dan PkM dalam pembelajaran oleh DTPS dalam 3 tahun terakhir.\nTabel 5.c)  LKPS\n', 'Pada LKPS, terdapat 40 MK yang dikembangkan berdasarkan hasil penelitian dan/atau PkM DTPS dalam 3 tahun terakhir. \nPerlu konfirmasi data.', 'Pada LKPS, terdapat 40 MK yang dikembangkan berdasarkan hasil penelitian dan/atau PkM DTPS dalam 3 tahun terakhir. \nData terverifikasi, dalam bentuk studi kasus dan bahan ajar.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22920, 96, '48', 'C.6.4.k) Suasana Akademik\nKeterlaksanaan dan keberkalaan program dan kegiatan diluar kegiatan pembelajaran terstruktur untuk meningkatkan suasana akademik. Contoh: kegiatan himpunan, mahasiswa,kuliah umum/studium generale, seminar ilmiah, bedah buku.\n', 'Kegiatan-kegiatan yang sudah dijalankan oleh PSTM untuk mendukung suasana akademik adalah pelatihan bidang ketenikmesinan (SAP dan AUTOCAD), pengenalan kehidupan kampus yang diadakan pada waktu mahasiswa baru masuk, seminar dan lokakarya dosen bekerja sama dengan Universitas, temu dosen, mahasiswa dan alumni pada saat yudisium. \nBelum ada informasi jadwal dan keberkalaan kegiatan. Perlu konfirmasi bukti.', 'Kegiatan-kegiatan yang sudah dijalankan oleh PSTM untuk mendukung suasana akademik adalah pelatihan bidang ketenikmesinan (SAP dan AUTOCAD), pengenalan kehidupan kampus yang diadakan pada waktu mahasiswa baru masuk, seminar dan lokakarya dosen bekerja sama dengan Universitas, temu dosen, mahasiswa dan alumni pada saat yudisium. \nPada AL, ada kalendar akademik yang memuat agenda kegiatan per bulan mencakup loka karya ilmiah, pelaksanaan seminar, seminar hasil penelitian. Terkofirmmaasi juga kegiatan bakti sosial dan perlombaan yang dapat membangkitkan kepedulian sosial mahasiswa dan juga menumbuhkan jiwa kewirausahaan mahasiswa.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22921, 96, '49', 'C.6.4.l) Kepuasan Mahasiswa\nA. Tingkat kepuasan mahasiswa terhadap proses pendidikan.\nB. Analisis dan tindak lanjut dari hasil pengukuran kepuasan mahasiswa.\nTabel 5.d LKPS\n', 'A) Ada 5 aspek yang diukur, yaitu: keandalan, daya tanggap, kepastian, empati dan tangible. Berikut adalah tingkat kepuasan masing-masing aspek, yaitu: untuk keandalan dengan tingkat kepuasan sangat baik= 27.8%, baik = 72.2%, cukup = 0 dan kurang = 0. Untuk daya tanggap, tingkat kepuasan sangat baik = 52.8%, baik = 47.2%, cukup = 0, dan kurang = 0. Untuk kepastian, tingkat kepuasan dgn sangat baik = 31.9%, baik = 68.1%, cukup = 0, dan kurang = 0, untuk aspek empati, tingkat kepuasan sangat baik = 31.8%, baik = 68.1%, cukup = 0, dan kurang= 0, sedangkan untuk tangible dengan tingkat kepuasan sangat baik = 30.6%, baik = 69.4%, cukup = 0 dan kurang = 0. \nB) Tidak ada informasi dilakukannya evaluasi terhadap kepuasan terhadap proses pembelajaran. Tidak ada penjelasan rencana perbaikan dan pengembangan pendidikan.', 'A) Ada 5 aspek yang diukur, yaitu: keandalan, daya tanggap, kepastian, empati dan tangible. Berikut adalah tingkat kepuasan masing-masing aspek, yaitu: untuk keandalan dengan tingkat kepuasan sangat baik= 27.8%, baik = 72.2%, cukup = 0 dan kurang = 0. Untuk daya tanggap, tingkat kepuasan sangat baik = 52.8%, baik = 47.2%, cukup = 0, dan kurang = 0. Untuk kepastian, tingkat kepuasan dgn sangat baik = 31.9%, baik = 68.1%, cukup = 0, dan kurang = 0, untuk aspek empati, tingkat kepuasan sangat baik = 31.8%, baik = 68.1%, cukup = 0, dan kurang= 0, sedangkan untuk tangible dengan tingkat kepuasan sangat baik = 30.6%, baik = 69.4%, cukup = 0 dan kurang = 0. \nB) Pad LED tidak ada informasi dilakukannya evaluasi terhadap kepuasan terhadap proses pembelajaran;  tidak ada penjelasan rencana perbaikan dan pengembangan pendidikan.\nPada AL, dikonfirmasia kegiatan evaluasi dengan EDOM menggunakan Google Form yang terdokumentasi di Laporan Sistem Kepuasan, yang memuat rekomendasi perbaikan dan tindak lanjut. Terkonfirmasi adanya tindak lajut dari hasil kepuasan mahasiswa dengan adanya pemanggilan dosen yang berkinerja rendah berdasrkan hasil survei kepuasan mahasiswa.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45');
INSERT INTO `tanggapan_al` (`id`, `al_id`, `nomor`, `kriteria`, `deskripsi_berdasarkan_hasil_ak`, `deskripsi_berdasarkan_verifikasi_al`, `tanggapan_prodi`, `informasi_faktual`, `tanggapan_asesor`, `created_at`, `updated_at`) VALUES (22922, 96, '50', 'C.7. Penelitian\nC.7.4. Indikator Kinerja Utama\nC.7.4.a) Relevansi Penelitian\nRelevansi penelitian pada UPPS mencakup unsur-unsur sebagai berikut:\n1) memiliki peta jalan yang memayungi tema penelitian dosen dan mahasiswa,\n2) dosen dan mahasiswa melaksanakan penelitian sesuai dengan agenda penelitian dosen yang merujuk kepada peta jalan penelitian.\n3) melakukan evaluasi kesesuaian penelitian dosen dan mahasiswa dengan peta jalan, dan\n4) menggunakan hasil evaluasi untuk perbaikan relevansi penelitian dan pengembangan keilmuan program studi\n', 'Relevansi penelitian pada UPPS mencakup : \n1) ada informasi kebijakan arah dan peta jalan penyelenggaraan penelitian berpedoman pada rencana induk penelitian Universitas sesuai Statuta Univ.\n2) ada informasi kebijakan bahwa dalam pelaksanaan penelitian berdasarkan pedoman penelitian dan dapat melibatkan dosen dan/ tendik. Terdapat 21 penelitian dosen yang melibatkan mahasiswa selama 3 tahun terakhir.\n3) UPPS memiliki manual standar evaluasi dan pengendalian hasil penelitian, namun tidak ada informasi melakukan evaluasi kesesuaian penelitian dosen dan mahasiswa dengan peta jalan. \n4) Tidak ada informasi menggunakan hasil evaluasi untuk perbaikan relevansi penelitian dan pengembangan keilmuan program studi.', 'Relevansi penelitian pada UPPS mencakup : \n1) ada informasi kebijakan arah dan peta jalan penyelenggaraan penelitian berpedoman pada rencana induk penelitian Universitas sesuai Statuta Univ.\n2) ada informasi kebijakan bahwa dalam pelaksanaan penelitian berdasarkan pedoman penelitian dan dapat melibatkan dosen dan/ tendik. Terdapat 21 penelitian dosen yang melibatkan mahasiswa selama 3 tahun terakhir.\n3) UPPS memiliki manual standar evaluasi dan pengendalian hasil penelitian, namun tidak ada informasi melakukan evaluasi kesesuaian penelitian dosen dan mahasiswa dengan peta jalan. \n4) Pada LED, tidak ada informasi menggunakan hasil evaluasi untuk perbaikan relevansi penelitian dan pengembangan keilmuan program studi.\nPada AL, tersedia dokumen road map penelitian. Belum dilakukan evaluasi kesesuaian penelitian dosen dengan peta jalan. Tersedia monev dan pengendalian penelitian.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22923, 96, '51', 'C.7.4.b) Penelitian Dosen dan Mahasiswa\nPenelitian DTPS yang dalam pelaksanaannya melibatkan mahasiswa program studi dalam 3 tahun terakhir.\nTabel 6.a LKPS\n', 'Pada LKPS, terdapat 21 penellitan dosen yang melibatkan mahasiswa, dari total 68 penelitian dosen selama 3 tahun terakhir.\nPerlu konfirmasi bukti keterlibatan.', 'Pada LKPS, terdapat 21 penellitan dosen yang melibatkan mahasiswa, dari total 68 penelitian dosen selama 3 tahun terakhir.\nPada AL, data terverifikasi.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22924, 96, '52', 'C.8 Pengabdian kepada Masyarakat\nC.8.4 Indikator Kinerja Utama\nC.8.4.a) Relevansi PkM\nRelevansi PkM pada UPPS mencakup unsur-unsur sebagai berikut: \n 1) memiliki peta jalan yang memayungi tema PkM dosen dan mahasiswa serta hilirisasi/penerapan keilmuan program studi, \n 2) dosen dan mahasiswa melaksanakan PkM sesuai dengan peta jalan PkM. \n 3) melakukan evaluasi kesesuaian PkM dosen dan mahasiswa dengan peta jalan, dan \n 4) menggunakan hasil evaluasi untuk perbaikan relevansi PkM dan pengembangan keilmuan program studi.', 'Relevansi PkM pada UPPS mencakup : \n1) ada informasi kebijakan yang tercantum di Statuta Univ bahwa Arah dan peta jalan penyelanggaran pengabdian kepada masyarakat berpedoman pada rencana induk pengabdian universitas.\n2) ada informasi kebijakan bahwa dalam melaksanakan PkM sesuai dengan agenda dosen yang merujuk kepada peta jalan penelitian, dapat melibatkan mahasiswa dan/ tendik.\n3) Tidak ada informasi melakukan evaluasi kesesuaian PkM dosen dan mahasiswa dengan peta jalan, dan \n4) Tidak ada informasi menggunakan hasil evaluasi untuk perbaikan relevansi penelitian dan pengembangan keilmuan program studi.', 'Relevansi PkM pada UPPS mencakup : \n1) ada informasi kebijakan yang tercantum di Statuta Univ bahwa Arah dan peta jalan penyelanggaran pengabdian kepada masyarakat berpedoman pada rencana induk pengabdian universitas.\n2) ada informasi kebijakan bahwa dalam melaksanakan PkM sesuai dengan agenda dosen yang merujuk kepada peta jalan penelitian, dapat melibatkan mahasiswa dan/ tendik.\n3) Pada LED tidak ada informasi melakukan evaluasi kesesuaian PkM dosen dan mahasiswa dengan peta jalan, dan \n4) Pada LED, tidak ada informasi menggunakan hasil evaluasi untuk perbaikan relevansi penelitian dan pengembangan keilmuan program studi.\nTerkonfirmasi pada saat AL, tersedia dokumen road map PkM dan bukti keterlibatan mahasiswa. Belum dilakukan evaluai kesesuaian relevansi PkM dengan roadmap.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22925, 96, '53', 'C.8.4.b) PkM Dosen dan Mahasiswa\nPkM DTPS yang dalam pelaksanaannya melibatkan mahasiswa program studi dalam 3 tahun terakhir.\nTabel 7 LKPS', 'Pada LKPS, terdapat 3 PkM dosen yang melibatkan mahasiswa, dari total 68 penelitian dosen selama 3 tahun terakhir.\nPerlu konfirmasi bukti keterlibatan.', 'Pada LKPS, terdapat 3 PkM dosen yang melibatkan mahasiswa, dari total 68 penelitian dosen selama 3 tahun terakhir.\nTerkonfirmasi keterlibatan mahasiswa sebagai anggota pelaksana kegiatan dengan bukti dokumen Lap PkM dan prosiding PkM.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22926, 96, '54', 'C.9. Luaran dan Capaian Tridharma\nC.9.4. Indikator Kinerja Utama\nC.9.4.a) Luaran Dharma Pendidikan\nAnalisis pemenuhan capaian pembelajaran lulusan (CPL) yang diukur dengan metoda yang sahih dan relevan, mencakup aspek:\n1) keserbacakupan,\n2) kedalaman, dan\n3) kebermanfaatan analisis yang ditunjukkan dengan peningkatan CPL dari waktu ke waktu dalam 3 tahun terakhir.\n', 'Tidak ada informasi dilakukan analisis pemenuhan capaian pembelajaran lulusan yang memenuhi 3 aspek.', 'Pada LED, tidak ada informasi dilakukan analisis pemenuhan capaian pembelajaran lulusan yang memenuhi 3 aspek.\nHasil konfirmasi pada AL, tersedia dokumen CPL dalam Buku Kurikulum dan dokumen monev ketercapaian CPL untuk Gasal 2021/2022. Belum ada analisis pemenuhan CPL pada TS.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22927, 96, '55', 'IPK lulusan.\nTabel 8.a LKPS', 'Data jumlah lulusan adalah sbb: pd TS-2= 6, pd TS-1= 10, dan pad TS= 10, sedangkan IPK rata-rata adalah sbb: pada TS-2=3.09, pd TS-1=3.01, dan pd TS= 3,07, sehingga rata-rata IPK lulusan dalam 3 tahun terakhir adalah=3,05. ', 'Data jumlah lulusan adalah sbb: pd TS-2= 6, pd TS-1= 10, dan pad TS= 10, sedangkan IPK rata-rata adalah sbb: pada TS-2=3.09, pd TS-1=3.01, dan pd TS= 3,07, sehingga rata-rata IPK lulusan dalam 3 tahun terakhir adalah=3,05. \nData terverifikasi. ', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22928, 96, '56', 'Prestasi mahasiswa di bidang akademik dalam 3 tahun terakhir.\nTabel 8.b.1) LKPS', 'Disebutkan terdapat jumlah prestasi mhs di bidang akdemik dlm 3 th terakhir sbb: NI=internasional =0, NN=nasional= 2, dan prestasi lokal/wilayah NW=2, jumlah mhs NM=81. Perlu konfirmasi saat AL', 'Disebutkan terdapat jumlah prestasi mhs di bidang akdemik dlm 3 th terakhir sbb: NI=internasional =0, NN=nasional= 2, dan prestasi lokal/wilayah NW=2, jumlah mhs NM=81. \nData terverifikasi, ada bukti sertifikat perhargaan.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22929, 96, '57', 'Prestasi mahasiswa di bidang nonakademik dalam 3 tahun terakhir.\nTabel 8.b.2) LKPS', 'Disebutkan terdapat jumlah prestasi mhs di bidang non-akdemik dlm 3 th terakhir sbb: NI=internasional =0, NN=nasional= 9, dan prestasi lokal/wilayah NW=1, jumlah mhs NM=81. Akan diverfikasi saat AL', 'Disebutkan terdapat jumlah prestasi mhs di bidang non-akdemik dlm 3 th terakhir sbb: NI=internasional =0, NN=nasional= 9, dan prestasi lokal/wilayah NW=1, jumlah mhs NM=81.\nData terverifikasi, ada bukti sertifikat perhargaan.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22930, 96, '58', 'Masa studi.\nTabel 8.c LKPS', 'Dari jumlah mahasiswa TS-6 = 10 orang, rata-rata masa studi = 5.10 tahun', 'Dari jumlah mahasiswa TS-6 = 10 orang, rata-rata masa studi = 5.10 tahun', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22931, 96, '59', 'Persentase Kelulusan tepat waktu (PTW)\nTabel 8.c LKPS', 'Jumlah mahasiswa yang diterima pada TS-3 sebanyak 8 orang, belum ada yang lulus pada TS.', 'Jumlah mahasiswa yang diterima pada TS-3 sebanyak 8 orang, belum ada yang lulus pada TS.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22932, 96, '60', 'Persentase mahasiswa yang DO atau mengundurkan diri (MDO).\nTabel 8.c LKPS', 'Dari jumlah mahasiswa yang diterima pada TS-6 sebanyak 10 orang, selurunya telah lulus pada akhir TS.', 'Dari jumlah mahasiswa yang diterima pada TS-6 sebanyak 10 orang, selurunya telah lulus pada akhir TS.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22933, 96, '61', 'Pelaksanaan tracer study yang mencakup 5 aspek sebagai berikut: \n1) pelaksanaan tracer study terkoordinasi di tingkat PT,\n2) kegiatan tracer study dilakukan secara reguler setiap tahun dan terdokumentasi,\n3) isi kuesioner mencakup seluruh pertanyaan inti tracer study DIKTI.\n4) ditargetkan pada seluruh populasi (lulusan TS-4 s.d. TS-2),\n5) hasilnya disosialisasikan dan digunakan untuk pengembangan kurikulum dan pembelajaran. ', 'Disebutkan pelaksanaan tracer study dilakukan oleh Fakultas Teknik pada anggl 06 Ags 2021- 09 Oktober 2021 (LED hal 8).  Pelaksanaan telah dilakukan terhadap 230 lulusan. \nTidak ada informasi : dokumentasi dan keberkalaan tracer study; isi kuesioner, target populasi dan sosialisasi hasil tracer study.', 'Disebutkan pelaksanaan tracer study dilakukan oleh Fakultas Teknik pada anggl 06 Ags 2021- 09 Oktober 2021 (LED hal 8).  Pelaksanaan telah dilakukan terhadap 230 lulusan. \nPada LED tidak ada informasi : dokumentasi dan keberkalaan tracer study; isi kuesioner, target populasi dan sosialisasi hasil tracer study.\nHasil konfirmasi pada AL, tersedia dokumen Laporan Tracer Study Fakultas yang dilakukan setiap tahun dengan bukti dokumen Laporan tahun 2019, 2020, 2021. Laporan disosialisasikan pada website https://tracerstudy.saburai.ac.id.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22934, 96, '62', 'Waktu tunggu.                                                                                                       \nWT = lulusan untuk mendapatkan pekerjaan pertama dalam 3 tahun, mulai TS-4 s.d. TS-2.\nTabel 8.d.1) LKPS', 'Dari tabel 8.d.1 LKPS, jumlah lulusan: pada TS-4=12, pd TS-3 = 19, dan pd TS-2=6, selurunya terlacak (100%). Data waktu tunggu lulusannya: (WT) < 6 bulan, dengan tahun lulus pada: TS-4=11, TS-3=17 dan TS-2=5. (WT) 6 bulan ≤ WT ≤ 6 bulan, dengan tahun lulus pada: TS-4=1, TS-3=2 dan TS-2=1. Sedangkan WT > 6 bulan, dengan tahun lulus pada: TS-4=0, TS-3=0 dan TS-2=0. Dari data tersebut, maka rata-rata waktu tunggu lulusan (WT) = 1.8 bulan. ', 'Dari tabel 8.d.1 LKPS, jumlah lulusan: pada TS-4=12, pd TS-3 = 19, dan pd TS-2=6, selurunya terlacak (100%). Data waktu tunggu lulusannya: (WT) < 6 bulan, dengan tahun lulus pada: TS-4=11, TS-3=17 dan TS-2=5. (WT) 6 bulan ≤ WT ≤ 6 bulan, dengan tahun lulus pada: TS-4=1, TS-3=2 dan TS-2=1. Sedangkan WT > 6 bulan, dengan tahun lulus pada: TS-4=0, TS-3=0 dan TS-2=0. Dari data tersebut, maka rata-rata waktu tunggu lulusan (WT) = 1.8 bulan. \nData terverifikasi.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22935, 96, '63', 'Kesesuaian bidang kerja. \nTabel 8.d.2) LKPS', 'Dari tabel 8.d.2 LKPS, jumlah lulusan: pada TS-4=12, pd TS-3 = 19, dan pd TS-2=6, selurunya terlacak (100%).. Jumlah lulusan dengan kesesuaian: bidang kerja rendah: pada TS-4=0; TS-3=0, dan pd TS-2=0, bidang kerja sedang: pada TS-4=1; TS-3=2 dan pada TS-2=3, dan bidang kerja tinggi: pada TS-4=11; TS-3=17 dan pada TS-2=3, sehingga PBS = Kesesuaian bidang kerja lulusan saat mendapatkan pekerjaan pertama = 91.9%', 'Dari tabel 8.d.2 LKPS, jumlah lulusan: pada TS-4=12, pd TS-3 = 19, dan pd TS-2=6, selurunya terlacak (100%).. Jumlah lulusan dengan kesesuaian: bidang kerja rendah: pada TS-4=0; TS-3=0, dan pd TS-2=0, bidang kerja sedang: pada TS-4=1; TS-3=2 dan pada TS-2=3, dan bidang kerja tinggi: pada TS-4=11; TS-3=17 dan pada TS-2=3, sehingga PBS = Kesesuaian bidang kerja lulusan saat mendapatkan pekerjaan pertama = 91.9%\nData terverifikasi.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22936, 96, '64', 'Tingkat dan ukuran tempat kerja lulusan.\nTabel 8.e.1) LKPS        ', 'Dari tabel 8.e.1 LKPS, jumlah lulusan: pada TS-4=12, pd TS-3 = 19, dan pd TS-2=6, selurunya terlacak (100%). Tingkat dan ukuran tempat kerja lulusan, adalah sbb: Tidak ada lulusan bekerja pada tingkat multi nasional/internasional, lulusan bekerja pada lokal/wilayah/berwirausaha berijin pada TS-4=5, TS-3=8, TS-2=5, lulusan bekerja pada lokal/wilayah/berwirausaha tidak berijin pada TS-4=7, TS-3=11, TS-2=1.', 'Dari tabel 8.e.1 LKPS, jumlah lulusan: pada TS-4=12, pd TS-3 = 19, dan pd TS-2=6, selurunya terlacak (100%). Tingkat dan ukuran tempat kerja lulusan, adalah sbb: Tidak ada lulusan bekerja pada tingkat multi nasional/internasional, lulusan bekerja pada lokal/wilayah/berwirausaha berijin pada TS-4=5, TS-3=8, TS-2=5, lulusan bekerja pada lokal/wilayah/berwirausaha tidak berijin pada TS-4=7, TS-3=11, TS-2=1.\nData terverifikasi.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22937, 96, '65', 'Tingkat kepuasan pengguna lulusan.\nTabel 8.e.2) LKPS', 'Dari tabel 8.e.2 LKPS, jumlah lulusan: pada TS-4=12, pd TS-3 = 19, dan pd TS-2=6, selurunya terlacak (100%). Tingkat kepuasan pengguna dalam 7 aspek adalah sbb: 1) Aspek Etika: sangat baik=SB= 80%, baik=B= 20%, cukup=C=0 dan kurang K=0. 2) Aspek Keahlian: SB= 90%, B=10%, C=0, dan K=0. 3) Aspek Kemampuan berbahasa asing: SB=0,9, B=0,1, C=0, dan K= 0. 4) Aspek Penggunaan teknologi informasi: SB=60%, B=40%, C=0, dan K=0. 5) Aspek kemampuan Berkomunikasi: SB=70%, B=30%, C=0, dan K=0. 6) Aspek kerjasama tim: SB=90%, B=10%, C=0, dan K=0. 7) Aspek Pengembangan diri: SB= 90%, B=10%, C=0, dan K=0. ', 'Dari tabel 8.e.2 LKPS, jumlah lulusan: pada TS-4=12, pd TS-3 = 19, dan pd TS-2=6, selurunya terlacak (100%). Tingkat kepuasan pengguna dalam 7 aspek adalah sbb: 1) Aspek Etika: sangat baik=SB= 80%, baik=B= 20%, cukup=C=0 dan kurang K=0. 2) Aspek Keahlian: SB= 90%, B=10%, C=0, dan K=0. 3) Aspek Kemampuan berbahasa asing: SB=0,9, B=0,1, C=0, dan K= 0. 4) Aspek Penggunaan teknologi informasi: SB=60%, B=40%, C=0, dan K=0. 5) Aspek kemampuan Berkomunikasi: SB=70%, B=30%, C=0, dan K=0. 6) Aspek kerjasama tim: SB=90%, B=10%, C=0, dan K=0. 7) Aspek Pengembangan diri: SB= 90%, B=10%, C=0, dan K=0. \nData terverifikasi.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22938, 96, '66', 'C.9.4.b) Luaran Dharma Penelitian dan PkM \nPublikasi ilmiah mahasiswa, yang dihasilkan secara mandiri atau bersama DTPS, dengan judul yang relevan dengan bidang program studi dalam 3 tahun terakhir.\nTabel 8.f.1) LKPS', 'Publikasi ilmiah dari mahasiswa yang dihasilkan secara mandiri atau bersama DTPS dengan judul relevan dengan bidang PS dalam 3 tahun terakhir adalah sbb: NA1=publikasi di jurnal nasional tidak terakreditasi = 5, seminar nasional = 6. Sedangkan publikasi lainnya tidak ada.', 'Publikasi ilmiah dari mahasiswa yang dihasilkan secara mandiri atau bersama DTPS dengan judul relevan dengan bidang PS dalam 3 tahun terakhir adalah sbb: NA1=publikasi di jurnal nasional tidak terakreditasi = 5, seminar nasional = 6. Sedangkan publikasi lainnya tidak ada.\nPada AL data terverifikasi.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22939, 96, '67', 'Luaran penelitian dan PkM yang dihasilkan mahasiswa, baik secara mandiri atau bersama DTPS dalam 3 tahun terakhir.\nTabel 8.f.5) LKPS', 'Terdapat luaran penelitian/PkM yang dihasilkan mahasiswa secara mandiri atau bersama dosen, dengan perincian sbb : luaran penelitian/PkM yang mendapat pengakuan HKI (Paten, Paten Sederhana) = 6; luaran penelitian/PkM yang diterbitkan dalam bentuk Buku ber-ISBN, Book Chapter=2. Luaran lainnya tidak ada.\nPerlu konfirmasi luaran dalam bentuk paten/paten sederhana dalam bentuk skripsi (5 skripsi)', 'Terdapat luaran penelitian/PkM yang dihasilkan mahasiswa secara mandiri atau bersama dosen, dengan perincian sbb : luaran penelitian/PkM yang mendapat pengakuan HKI = 6; luaran penelitian/PkM yang diterbitkan dalam bentuk Buku ber-ISBN, Book Chapter=2. Luaran lainnya tidak ada.\nHasil konfirmasi luaran skripsi (5 skripsi) dalam bentuk HKI.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22940, 96, '68', 'D. Penjaminan Mutu\nD.1 Keberadaan unit peminjaman dan komitmen pimpinan\n\nKeberadaan unit penjaminan mutu UPPS dan komitmen pimpinan dengan keberadaan 4 aspek.\n1) Dokumen legal pembentukan unsur pelaksana penjaminan mutu.\n2) Dokumen legal bahwa auditor bersifat independen.\n3) Dokumen pelaksanaan audit mutu internal\n4) Dokumen Rapat Tinjauan Manajemen (RTM)\n', 'Keterlaksanaan sistem penjaminan mutu internal :\n1) Ada informasi struktur organisasi sesuai Statuta yang terdiri dari LPM di tingkat Univ, Kabid SPMI, Kabid SPME dan UPM Fakultas. \nDokumen pembentuk tercantum dalam SK Ketua UPPS mengenao penempatan pegawai tetap LPM dan Keputusan Badan Penyelenggaran.\n2) Belum ada informsai dokumen legal auditor bersifat independen.\n3) Pelaksanaan audit mutu internal pada tahun 2019/2020, dengan hasil mencapai standar dikti. Pelaksanaan AMI 2020/2021 memperoleh hasil Melampaui Standar Dikti.\nPerlu konfirmasi dokumen Laporan AMI.\n4) Belum ada informasi dokumen RTM.', 'Keterlaksanaan sistem penjaminan mutu internal :\n1) Ada informasi struktur organisasi sesuai Statuta yang terdiri dari LPM di tingkat Univ, Kabid SPMI, Kabid SPME dan UPM Fakultas. \nDokumen pembentuk tercantum dalam SK Ketua UPPS mengenao penempatan pegawai tetap LPM dan Keputusan Badan Penyelenggaran.\n2) Pada LED, belum ada informsai dokumen legal auditor bersifat independen.\n3) Pelaksanaan audit mutu internal pada tahun 2019/2020, dengan hasil mencapai standar dikti. Pelaksanaan AMI 2020/2021 memperoleh hasil Melampaui Standar Dikti.\n4) Pada LED, belum ada informasi dokumen RTM.\nHasil konfirmasi di lapangan, tersedia dokumen Laporan AMI, terdapat auditor berjumlah 5 orang yang tersertifikasi pelatihan audit dan dilengapi dokumen deklarasi komitmen mutu. Tersedia dokumen RTM tahun 2021 yang dilaksanakan sekali dalam setahun.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22941, 96, '69', 'D.2 Ketersediaan dokumen dan pengakuan mutu eksternal\nKetersediaan dokumen sistem penjaminan mutu (Kebijakan SPMI, Manual SPMI, Standar SPMI dan Formulir SPMI) dan memiliki pengakuan mutu dari lembaga audit eksternal, lembaga akreditasi, dan lembaga sertifikasi\nTabel 9.b LKPS', 'UPPS memiliki dokumen sistem penjaminan mutu, menakup SK Ketua UPPSTahun 2019 tentang Penetapan Kebijakan Sistem Penjaminan Mutu Internal (SPMI); SK Ketua UPPSTahun 2020 tentang Penetapan Standar Nasional Pendidikan Tinggi UPPS; SK Ketua UPPSTahun 2019 tentang Penetapan Manual Sistem Penjaminan Mutu Internal dan SK Ketua UPPSTahun 2020 tentang Penetapan Buku Formulir SPMI. Sistem penjaminan mutu mengalami peningkatan dengan meningkatkan status hasil AMI menjadi melampaui standar dikti. PS memiliki pengakuan mutu dari lembaga akreditasi BAN PT, telah terakreditasi C.', 'UPPS memiliki dokumen sistem penjaminan mutu, menakup SK Ketua UPPSTahun 2019 tentang Penetapan Kebijakan Sistem Penjaminan Mutu Internal (SPMI); SK Ketua UPPSTahun 2020 tentang Penetapan Standar Nasional Pendidikan Tinggi UPPS; SK Ketua UPPSTahun 2019 tentang Penetapan Manual Sistem Penjaminan Mutu Internal dan SK Ketua UPPSTahun 2020 tentang Penetapan Buku Formulir SPMI. Sistem penjaminan mutu mengalami peningkatan dengan meningkatkan status hasil AMI menjadi melampaui standar dikti. PS memiliki pengakuan mutu dari lembaga akreditasi BAN PT, telah terakreditasi C.\nAda bukti auditor eksternal terkait keuangan.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22942, 96, '70', 'D.3 Keterlaksanaan Penjaminan Mutu dan Audit Mutu Internal\nKeterlaksanaan Sistem Penjaminan Mutu Internal (SPMI) yang memenuhi aspek berikut: \n1) Tersedianya  standar nasional pendidikan tinggi  mencakup IKU dan IKT yang terdiri dari: (1) Tata Pamong, Tata Kelola dan Kerjasama; (2) Mahasiswa; (3) Sumber Daya Manusia; (4) Keuangan, Sarana dan Prasarana; (5) Pendidikan; (6) Penelitian; (7) Pengabdian kepada Masyarakat; (8) Luaran dan Capaian Tridharma Perguruan Tinggi. \n2) Terlaksananya siklus penjaminan mutu (siklus PPEPP)\n3) Bukti sahih efektivitas pelaksanaan penjaminan mutu.\n4) Tersedianya bukti peningkatan standar. \nTabel 9.a LKPS\n', 'Keterlaksanan SPMI memenuhi aspek :\n1) tersedianya SN DIKTI  untuk seluruh standar pada SN DIKTI (24 standar pendidikan) mencakup IKU dan IKT pada kriteria tata pamong, mahasiswa, SDM, keuangan sapras, pendidikan, penelitian, PkM dan Luaran & capaian tridarma PT.\n2) Terlaksananya siklus penjaminan mutu (siklus PPEPP) , didkung kegiatan audit mutu internal dengan tanggal audt 9/12/2021. \nPerlu konfirmasi dokumen bukti terlaksannya siklus PPEPP.\n3) Bukti shahih efektivitas pelaksanaan penjaminan mutu, antara lain implementasi sistem penjaminan mutu pada standar kemahasiswaan dengan bikti dokumen standar non akademik, berita acara rapat kerja dengan peningkatan standar kemahasiswaan.\n4) Belum tersedia informasi peningkatan standar.\n', 'Keterlaksanan SPMI memenuhi aspek :\n1) tersedianya SN DIKTI  untuk seluruh standar pada SN DIKTI (24 standar pendidikan) mencakup IKU dan IKT pada kriteria tata pamong, mahasiswa, SDM, keuangan sapras, pendidikan, penelitian, PkM dan Luaran & capaian tridarma PT.\n2) Terlaksananya siklus penjaminan mutu (siklus PPEPP) , didkung kegiatan audit mutu internal dengan tanggal audt 9/12/2021. \n3) Bukti shahih efektivitas pelaksanaan penjaminan mutu, antara lain implementasi sistem penjaminan mutu pada standar kemahasiswaan dengan bikti dokumen standar non akademik, berita acara rapat kerja dengan peningkatan standar kemahasiswaan.\n4) Pada LED, belum tersedia informasi peningkatan standar.\nHasil konfirmasi di lapangan, dokumen PPEPP : dokumen standar, dokumen SOP sebanyak 150, dokumen rapat dosen, rapat RTM dilengkapi notulen, dokumen Laporan AMI dan Laporan RTM. Peningkatan standar dilakukan dalam bentuk catatan hasil rapat dimasukkan dalam rencana kerja dan anggaran tahun berikutnya.\n', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22943, 96, '71', 'D.4 Kepuasan Pemangku Kepentingan\nPengukuran kepuasan para pemangku kepentingan (mahasiswa, dosen, tenaga kependidikan, lulusan, pengguna, mitra industri, dan mitra lainnya) terhadap layanan manajemen, yang memenuhi aspek-aspek berikut:\n1) Menggunakan instrumen kepuasan yang sahih, andal, mudah digunakan,\n2) dilaksanakan secara  berkala, serta datanya terekam secara komprehensif,\n3) dianalisis dengan metode yang tepat serta bermanfaat untuk pengambilan keputusan,\n4) tingkat kepuasan dan umpan balik ditindaklanjuti untuk perbaikan dan peningkatan mutu luaran secara berkala dan tersistem.\n5) dilakukan review terhadap pelaksanaan pengukuran kepuasan dosen dan mahasiswa, serta\n6) hasilnya dipublikasikan dan mudah diakses oleh dosen dan mahasiswa.\n\n', 'Pada LED hal 150, ada informasi UPPS melakukan survey kepuasan pengguna terhadap layanan manajemen terhadap para pemangku kepentingan, layanan pengelolaan dan pengembangan SDM, layanan pengelolaan keuangan dan fasilitas, layanan dan pelaksanaan proses pendidikan, layanan dan pelaksanaan proses penelitian, layanan dan pelaksanaan PkM dan Kepuasan pengguna lulusan dan mitra kerja terhadap kinerja lulusan dengan metode kuisioner secara langsung pada saat akhir semester. \nBelum ada informasi hasil pengukuran kepuasan, tindak lanjut, review hasil pengukuran dan publikasinya.', 'Pada LED hal 150, ada informasi UPPS melakukan survey kepuasan pengguna terhadap layanan manajemen terhadap para pemangku kepentingan, layanan pengelolaan dan pengembangan SDM, layanan pengelolaan keuangan dan fasilitas, layanan dan pelaksanaan proses pendidikan, layanan dan pelaksanaan proses penelitian, layanan dan pelaksanaan PkM dan Kepuasan pengguna lulusan dan mitra kerja terhadap kinerja lulusan dengan metode kuisioner secara langsung pada saat akhir semester. \nPada LED, belum ada informasi hasil pengukuran kepuasan, tindak lanjut, review hasil pengukuran dan publikasinya.\nHasil konfirmasi di lapangan, pengukuran kepuasan mahasiswa terhadap proses pembelajaran menggunakan instrumen survei dengan Google Form. Pertanyaan mencakup mengenai pembelajaran, dosen, tendik dan aspek layanan (UKM dan kelompok ilmiah), dengan hasil survei : 27.8% sangat baik dan 72.2% baik. Pengukuran dilakukan per semester. \nPengukuran kepuasan pengguna lulusan dengan survei yang dilakukan secara manual dengan formulir, ada bukti dokumen 30 form hasil survei yang dilengkapi stempel yang dilaksanakan pada tahun 2021. Pengukuran dilaksanakan per tahun.\nPengukuran kepuasan lulusan melalui tracer study menggunakan instrumen Google Form dengan pertanyaan sesuai DIKTI, yang dilakukan per tahun. \nBelum dilakukan pengukuran kepuasan dosen, tendik dan mitra.\nHasil pengukuran dianalisis dengan metode statistik deskriptif, dievaluasi dan dibahas dalam rapat serta dilaporkan dalam Laporan Tracer Study yang disosialisasikan dalam website https://ftsaburai.ac.id.\n', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22944, 96, '72', 'E. Program Pengembangan Berkelanjutan\nE.1) Analisis SWOT\nKetepatan analisis SWOT', '1) UPPS melakukan analisis SWOT dengan mengidentifikasi kekuatan, kelemahan dan ancaman.\nBelum ada identifikasi peluang.\n2) Belum ada informasi analisis yang dilakukan terkait dengan hasil analisis capaian kinerja.\n3) Tersedia rumusan strategi pengembangan (12 strategi), namun perlu didukung data dan penetepan tahap sesuai prioritas pengembangan.\n4) UPPS telah merumuskan program pengembangan berkelanjutan, mencakup program peningkatan pengetahuan VMTS, peningkatan kualitas pembelajaran, peningkatan mutu lulusan, peningkatan kerjasama dan promosi, peningkatan penelitian dan PkM.', '1) UPPS melakukan analisis SWOT dengan mengidentifikasi kekuatan, kelemahan dan ancaman.\nPada AL, ada informasi mengenai identifikasi peluang yang tercantum dalam dokumen Renstra.\n2) Belum ada informasi analisis yang dilakukan terkait dengan hasil analisis capaian kinerja.\n3) Tersedia rumusan strategi pengembangan (12 strategi), namun perlu didukung data dan penetepan tahap sesuai prioritas pengembangan.\n4) UPPS telah merumuskan program pengembangan berkelanjutan, mencakup program peningkatan pengetahuan VMTS, peningkatan kualitas pembelajaran, peningkatan mutu lulusan, peningkatan kerjasama dan promosi, peningkatan penelitian dan PkM.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22945, 96, '73', 'E.2) Tujuan Strategi Pengembangan\nKetepatan di dalam menetapkan tujuan strategis pengembangan.', 'Belum ada informasi prioritas program pengembangan, namun ada informasi stratego pengembangan PS TM sebanyak 12 strategi. Penetapan strategi antara lain memperhatikan SDM, ketersediaan sapras dan daya saing global untuk publikasi karya ilmiah.', 'Pada LED belum ada informasi prioritas program pengembangan, namun ada informasi stratego pengembangan PS TM sebanyak 12 strategi. Penetapan strategi antara lain memperhatikan SDM, ketersediaan sapras dan daya saing global untuk publikasi karya ilmiah.\nPada AL, terkonfirmasi program pengembangan tercantum dalam Renstra dan Renop yang dilengkapi indikator per tahun.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45'), (22946, 96, '74', 'E.3) Program Pengembangan Berkelanjutan\nUPPS memiliki kebijakan, ketersediaan sumberdaya, kemampuan melaksanakan, dan kerealistikan program pengembangan berkelanjutan.', 'UPPS memiliki kebijakan dalam mengatur SDM dan Sapras, kemampuan melaksanakan ditunjukkan dengan keberadaan SOP. Penjaminan mutu berkelanjutan dengan audit internal, namun perlu konfirmasi  bukti pendukung.', 'UPPS memiliki kebijakan dalam mengatur SDM dan Sapras, kemampuan melaksanakan ditunjukkan dengan keberadaan SOP. Penjaminan mutu berkelanjutan dengan audit internal.\nPada AL terkonfirmasi tersedia dokumen peningkatan SDM dan sapras dalam dokumen Rencana Kerja dan Anggaran.', 'Menerima', NULL, 'Ok', '2024-07-28 07:43:45', '2024-07-28 07:43:45');
COMMIT;

